window.LD_ARTS={"食品安全法|第四十五条":["第四十五条食品生产经营者应当建立并执行从业人员健康管理制度。患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",1,"现行有效","2025-12-01",[["cr-aea9cae03c","无锡市市场监管局发布网络餐饮食品安全典型案例（第四批）","无锡市市场监督管理局","2026-09-15","行政处罚决定书"]]],"食品安全法|第一百二十六条":["第一百二十六条违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处五千元以上五万元以下罚款；情节严重的，责令停产停业，直至吊销许可证：\n（一）食品、食品添加剂生产者未按规定对采购的食品原料和生产的食品、食品添加剂进行检验；\n（二）食品生产经营企业未按规定建立食品安全管理制度，或者未按规定配备或者培训、考核食品安全管理人员；\n（三）食品、食品添加剂生产经营者进货时未查验许可证和相关证明文件，或者未按规定建立并遵守进货查验记录、出厂检验记录和销售记录制度；\n（四）食品生产经营企业未制定食品安全事故处置方案；\n（五）餐具、饮具和盛放直接入口食品的容器，使用前未经洗净、消毒或者清洗消毒不合格，或者餐饮服务设施、设备未按规定定期维护、清洗、校验；\n（六）食品生产经营者安排未取得健康证明或者患有国务院卫生行政部门规定的有碍食品安全疾病的人员从事接触直接入口食品的工作；\n（七）食品经营者未按规定要求销售食品；\n（八）保健食品生产企业未按规定向食品安全监督管理部门备案，或者未按备案的产品配方、生产工艺等技术要求组织生产；\n（九）婴幼儿配方食品生产企业未将食品原料、食品添加剂、产品配方、标签等向食品安全监督管理部门备案；\n（十）特殊食品生产企业未按规定建立生产质量管理体系并有效运行，或者未定期提交自查报告；\n（十一）食品生产经营者未定期对食品安全状况进行检查评价，或者生产经营条件发生变化，未按规定处理；\n（十二）学校、托幼机构、养老机构、建筑工地等集中用餐单位未按规定履行食品安全管理责任；\n（十三）食品生产企业、餐饮服务提供者未按规定制定、实施生产经营过程控制要求。餐具、饮具集中消毒服务单位违反本法规定用水，使用洗涤剂、消毒剂，或者出厂的餐具、饮具未按规定检验合格并随附消毒合格证明，或者未按规定在独立包装上标注相关内容的，由县级以上人民政府卫生行政部门依照前款规定给予处罚。食品相关产品生产者未按规定对生产的食品相关产品进行检验的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。食用农产品销售者违反本法第六十五条规定的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",11,"现行有效","2025-12-01",[["cr-aea9cae03c","无锡市市场监管局发布网络餐饮食品安全典型案例（第四批）","无锡市市场监督管理局","2026-09-15","行政处罚决定书"],["cr-3e65fd3408","购进陈皮时未如实记录该批陈皮的名称、规格、数量、生产日期","江门市市场监督管理局","2026-09-11","行政处罚信息公开表"],["cr-1f33bce7fe","肖鹏销售侵犯“郎”注册商标专用权的商品案（泸市监处罚〔2026〕54号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-5444bf25c1","四川清幽泉酒业有限责任公司未取得食品生产许可从事食品生产活动和仿冒他人注册商标案（泸市监处罚〔2026〕55号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-8676d3d4a8","无锡市市场监管局发布网络餐饮食品安全典型案例（第二批）","无锡市市场监督管理局","2026-06-08","行政处罚决定书"],["cr-f20d801f10","泸州振宏工程项目管理咨询有限公司经营标签不符合食品安全法规定的食品及销售应知是实施了混淆行为的商品案（泸市监处罚〔2026〕29号）","泸州市市场监督管理局","2026-05-07","行政处罚信息公开表"],["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-214bf92256","四川唐朝老窖（集团）有限公司生产标签含有虚假内容的食品案（泸市监处罚〔2026〕25号）","泸州市市场监督管理局","2026-04-09","行政处罚信息公开表"]]],"产品质量法|第十三条":["第十三条 可能危及人体健康和人身、财产安全的工业产品，必须符合保障人体健康和人身、财产安全的国家标准、行业标准；未制定国家标准、行业标准的，必须符合保障人体健康和人身、财产安全的要求。\n禁止生产、销售不符合保障人体健康和人身、财产安全的标准和要求的工业产品。具体管理办法由国务院规定。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",13,"现行有效","2018-12-29",[["cr-af7fe70c05","市场监管总局公布一批打击劣质低价 典型案例","市场监管总局","2026-09-11","行政处罚/通报"],["cr-6263bf5fc5","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-50aa93ac01","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-bf0317be4f","湖南省市场监管局发布一批民生领域 “铁拳”行动产品质量典型案例","地方市场监管局","2026-08-10","行政处罚/通报"],["cr-1d68827497","2025江苏省“守护消费”铁拳行动典型案例（第二批）","地方市场监管局","2025-10-21","行政处罚/通报"],["cr-1579716331","天津公布2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-09-18","行政处罚/通报"],["cr-b93c046109","海南公布7件2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-07-02","行政处罚/通报"],["cr-d6e9d69272","河南省市场监管局公布2025“守护消费” 铁拳行动典型案例（第一批）","地方市场监管局","2025-05-07","行政处罚/通报"]]],"认证认可条例|第二十七条":["第二十七条 为了保护国家安全、防止欺诈行为、保护人体健康或者安全、保护动植物生命或者健康、保护环境，国家规定相关产品必须经过认证的，应当经过认证并标注认证标志后，方可出厂、销售、进口或者在其他经营活动中使用。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",2,"现行有效","2023-07-20",[["cr-af7fe70c05","市场监管总局公布一批打击劣质低价 典型案例","市场监管总局","2026-09-11","行政处罚/通报"],["cr-63d332ac3c","行政处罚决定书（粤市监广办罚〔2023〕003号）","广东省市场监督管理局","2023-12-08","行政处罚决定书"]]],"反不正当竞争法|第九条":["第九条 经营者不得对其商品的性能、功能、质量、销售状况、用户评价、曾获荣誉等作虚假或者引人误解的商业宣传，欺骗、误导消费者和其他经营者。\n经营者不得通过组织虚假交易、虚假评价等方式，帮助其他经营者进行虚假或者引人误解的商业宣传。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",5,"现行有效","2025-10-15",[["cr-af7fe70c05","市场监管总局公布一批打击劣质低价 典型案例","市场监管总局","2026-09-11","行政处罚/通报"],["cr-bc8d5869d9","市场监管总局公布九起养老服务领域 不正当竞争典型案例","市场监管总局","2026-09-02","行政处罚/通报"],["cr-cf7d2cfc01","市场监管总局公布六起市场化活动 违法违规行为专项整治典型案件","市场监管总局","2026-07-30","行政处罚/通报"],["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"],["cr-6700c4b6f5","福建泉州发布2026年“铁拳”行动典型案例暨2025年度消费侵权典型案例","地方市场监管局","2026-03-17","行政处罚/通报"]]],"行政处罚法|第四十四条":["第四十四条 行政机关在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",19,"现行有效","2021-07-15",[["cr-3a3fa5c7c2","青岛市黄岛区市场监督管理局行政处罚文书送达公告（青黄市监罚送告〔2026〕8020-8044号）","青岛市市场监督管理局","2026-09-09","行政处罚告知送达公告"],["cr-08dada6839","青岛市市场监督管理局行政处罚告知送达公告（第一批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-472d54fe7a","青岛市市场监督管理局行政处罚告知送达公告(第二批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-af1aecc967","青岛市黄岛区市场监督管理局行政处罚文书送达公告(青黄市监罚送告〔2026〕7737-7758号)","青岛市市场监督管理局","2026-09-03","行政处罚告知送达公告"],["cr-df988c921d","青岛市黄岛区市场监督管理局行政处罚文书送达公告","青岛市市场监督管理局","2026-08-28","行政处罚告知送达公告"],["cr-b5c01cb958","昆明市市场监督管理局关于云南宿达酒店管理有限公司等92户市场主体《行政处罚告知书》送达公告","昆明市市场监督管理局","2025-12-30","行政处罚决定书"],["cr-facabe9e2b","昆明市市场监督管理局关于云南孟白企业管理咨询有限公司等23户市场主体《行政处罚告知书》送达公告","昆明市市场监督管理局","2025-11-10","行政处罚决定书"],["cr-a3fa259b5a","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1898号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"]]],"企业信息公示暂行条例|第八条":["第八条 企业应当于每年1月1日至6月30日，通过国家企业信用信息公示系统向市场监督管理部门报送上一年度年度报告，并向社会公示。\n当年设立登记的企业，自下一年起报送并公示年度报告。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",16,"现行有效","2024-05-01",[["cr-08dada6839","青岛市市场监督管理局行政处罚告知送达公告（第一批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-472d54fe7a","青岛市市场监督管理局行政处罚告知送达公告(第二批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-b5c01cb958","昆明市市场监督管理局关于云南宿达酒店管理有限公司等92户市场主体《行政处罚告知书》送达公告","昆明市市场监督管理局","2025-12-30","行政处罚决定书"],["cr-e12e8099ef","昆明市市场监督管理局关于云南孟白企业管理咨询有限公司等23户市场主体《行政处罚决定书》送达公告","昆明市市场监督管理局","2025-12-29","行政处罚决定书"],["cr-9796e7cc5e","昆明市市场监督管理局关于昆明新嘎商贸有限公司等5户市场主体《行政处罚决定书》的送达公告","昆明市市场监督管理局","2025-12-25","行政处罚决定书"],["cr-a3fa259b5a","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1898号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"],["cr-000d1a6504","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1896号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"],["cr-9257e44655","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1899号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"]]],"企业信息公示暂行条例|第十八条":["第十八条 企业未按照本条例规定的期限公示年度报告或者未按照市场监督管理部门责令的期限公示有关企业信息的，由县级以上市场监督管理部门列入经营异常名录，并依法给予行政处罚。企业因连续2年未按规定报送年度报告被列入经营异常名录未改正，且通过登记的住所或者经营场所无法取得联系的，由县级以上市场监督管理部门吊销营业执照。\n企业公示信息隐瞒真实情况、弄虚作假的，法律、行政法规有规定的，依照其规定；没有规定的，由市场监督管理部门责令改正，处1万元以上5万元以下罚款；情节严重的，处5万元以上20万元以下罚款，列入市场监督管理严重违法失信名单，并可以吊销营业执照。被列入市场监督管理严重违法失信名单的企业的法定代表人、负责人，3年内不得担任其他企业的法定代表人、负责人。\n企业被吊销营业执照后，应当依法办理注销登记；未办理注销登记的，由市场监督管理部门依法作出处理。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",17,"现行有效","2024-05-01",[["cr-08dada6839","青岛市市场监督管理局行政处罚告知送达公告（第一批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-472d54fe7a","青岛市市场监督管理局行政处罚告知送达公告(第二批）","青岛市市场监督管理局","2026-09-08","行政处罚告知送达公告"],["cr-af1aecc967","青岛市黄岛区市场监督管理局行政处罚文书送达公告(青黄市监罚送告〔2026〕7737-7758号)","青岛市市场监督管理局","2026-09-03","行政处罚告知送达公告"],["cr-b5c01cb958","昆明市市场监督管理局关于云南宿达酒店管理有限公司等92户市场主体《行政处罚告知书》送达公告","昆明市市场监督管理局","2025-12-30","行政处罚决定书"],["cr-e12e8099ef","昆明市市场监督管理局关于云南孟白企业管理咨询有限公司等23户市场主体《行政处罚决定书》送达公告","昆明市市场监督管理局","2025-12-29","行政处罚决定书"],["cr-9796e7cc5e","昆明市市场监督管理局关于昆明新嘎商贸有限公司等5户市场主体《行政处罚决定书》的送达公告","昆明市市场监督管理局","2025-12-25","行政处罚决定书"],["cr-a3fa259b5a","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1898号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"],["cr-000d1a6504","昆明市市场监督管理局行政处罚告知书云市监昆罚告〔2025〕1896号","昆明市市场监督管理局","2025-07-04","行政处罚决定书"]]],"商标法|第六十条":["第六十条 集体商标、证明商标注册人有下列行为之一的，由负责商标执法的部门责令限期改正；逾期不改正的，处一万元以下的罚款；情节严重的，处一万元以上十万元以下的罚款：\n（一）怠于行使商标管理职责，对消费者造成损害；\n（三）违反本法、有关行政法规和国家有关规定行使注册商标专用权，造成不良影响。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",9,"即将实施","2027-01-01",[["cr-1f33bce7fe","肖鹏销售侵犯“郎”注册商标专用权的商品案（泸市监处罚〔2026〕54号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-5444bf25c1","四川清幽泉酒业有限责任公司未取得食品生产许可从事食品生产活动和仿冒他人注册商标案（泸市监处罚〔2026〕55号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-b93c046109","海南公布7件2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-07-02","行政处罚/通报"],["cr-1617148b24","无锡市市场监管局公布2025“守护消费”铁拳行动（知识产权执法保护）典型案例","无锡市市场监督管理局","2025-04-29","行政处罚决定书"],["cr-9ae647430b","泸州泸南酒业有限公司仿冒他人注册商标案（泸市监处罚〔2025〕6号）","泸州市市场监督管理局","2025-04-15","行政处罚信息公开表"],["cr-cfe8d1a573","新疆公布八起“铁拳”行动典型案例","地方市场监管局","2025-03-31","行政处罚/通报"],["cr-d16932937a","陕西省市场监管局公布2024民生领域 “铁拳”行动典型案例（第四批）","地方市场监管局","2024-08-26","行政处罚/通报"],["cr-c777844d03","山东省青岛市市场监督管理局公布 2024民生领域案件查办“铁拳”行动典型案例（第二批）","地方市场监管局","2024-05-22","行政处罚/通报"]]],"行政处罚法|第二十八条":["第二十八条 行政机关实施行政处罚时，应当责令当事人改正或者限期改正违法行为。\n当事人有违法所得，除依法应当退赔的外，应当予以没收。违法所得是指实施违法行为所取得的款项。法律、行政法规、部门规章对违法所得的计算另有规定的，从其规定。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",9,"现行有效","2021-07-15",[["cr-1f33bce7fe","肖鹏销售侵犯“郎”注册商标专用权的商品案（泸市监处罚〔2026〕54号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-5444bf25c1","四川清幽泉酒业有限责任公司未取得食品生产许可从事食品生产活动和仿冒他人注册商标案（泸市监处罚〔2026〕55号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"],["cr-f20d801f10","泸州振宏工程项目管理咨询有限公司经营标签不符合食品安全法规定的食品及销售应知是实施了混淆行为的商品案（泸市监处罚〔2026〕29号）","泸州市市场监督管理局","2026-05-07","行政处罚信息公开表"],["cr-aba53c243f","江门市**医院使用过期的医疗器械案（江市监行罚〔2026〕1号）","江门市市场监督管理局","2026-03-19","行政处罚信息公开表"],["cr-e53ef52dcb","组织虚假交易帮助其他经营者进行引人误解的商业宣传的不正当竞争案（粤市监罚〔2025〕粤北办002号）","广东省市场监督管理局","2026-01-15","行政处罚决定书"],["cr-ab746c57e1","泸州国宾泉酒业有限公司实施混淆行为案（泸市监处罚〔2025〕19号）","泸州市市场监督管理局","2025-10-11","行政处罚信息公开表"],["cr-6483b0b8e4","泸州益点康医疗器械有限公司从事医疗器械网络销售未按照规定告知负责药品监督管理的部门和将非消费者自行使用的医疗器械销售给消费者个人案（泸市监罚〔2025〕7号）","泸州市市场监督管理局","2025-05-29","行政处罚信息公开表"]]],"食品安全法|第一百二十二条":["第一百二十二条\n违反本法规定，未取得食品生产经营许可\n从事食品生产经营活动，或者未取得食品添加剂生产许可从事食品添加剂生产活动的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂以及用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款。明知从事前款规定的违法行为，仍为其提供生产经营场所或者其他条件的，由县级以上人民政府食品安全监督管理部门责令停止违法行为，没收违法所得，并处五万元以上十万元以下罚款；使消费者的合法权益受到损害的，应当与食品、食品添加剂生产经营者承担连带责任。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",6,"现行有效","2025-12-01",[["cr-1f33bce7fe","肖鹏销售侵犯“郎”注册商标专用权的商品案（泸市监处罚〔2026〕54号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-5444bf25c1","四川清幽泉酒业有限责任公司未取得食品生产许可从事食品生产活动和仿冒他人注册商标案（泸市监处罚〔2026〕55号）","泸州市市场监督管理局","2026-09-08","行政处罚信息公开表"],["cr-42567b47d4","安徽省淮南市市场监管局公布 2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-23","行政处罚/通报"],["cr-2223a26dfb","生产经营标签不符合规定的预包装食品案（粤市监广州办罚〔2025〕1220号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"],["cr-88c87fbcbd","生产经营标签不符合规定的食品等违法行为案（粤市监罚〔2025〕广州办1219号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"],["cr-9469fdc476","行政处罚决定书（粤市监广州办罚〔2025〕0825号）","广东省市场监督管理局","2025-09-12","行政处罚决定书"]]],"产品质量法|第四十九条":["第四十九条 生产、销售不符合保障人体健康和人身、财产安全的国家标准、行业标准的产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品（包括已售出和未售出的产品，下同）货值金额等值以上三倍以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照；构成犯罪的，依法追究刑事责任。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",6,"现行有效","2018-12-29",[["cr-6263bf5fc5","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-50aa93ac01","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-1d68827497","2025江苏省“守护消费”铁拳行动典型案例（第二批）","地方市场监管局","2025-10-21","行政处罚/通报"],["cr-d6e9d69272","河南省市场监管局公布2025“守护消费” 铁拳行动典型案例（第一批）","地方市场监管局","2025-05-07","行政处罚/通报"],["cr-897dbc0ba5","无锡市市场监管局公布电动自行车安全隐患全链条整治违法典型案例（第二批）","无锡市市场监督管理局","2024-10-31","行政处罚决定书"],["cr-f1bd00ef59","福建泉州公布一批涉消防、特种设备领域 典型案例","地方市场监管局","2024-04-12","行政处罚/通报"]]],"产品质量法|第三十九条":["第三十九条 销售者销售产品，不得掺杂、掺假，不得以假充真、以次充好，不得以不合格产品冒充合格产品。\n第四章 损害赔偿","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",4,"现行有效","2018-12-29",[["cr-6263bf5fc5","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-50aa93ac01","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-bf0317be4f","湖南省市场监管局发布一批民生领域 “铁拳”行动产品质量典型案例","地方市场监管局","2026-08-10","行政处罚/通报"],["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"]]],"产品质量法|第五十条":["第五十条 在产品中掺杂、掺假，以假充真，以次充好，或者以不合格产品冒充合格产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额百分之五十以上三倍以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照；构成犯罪的，依法追究刑事责任。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",5,"现行有效","2018-12-29",[["cr-6263bf5fc5","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-50aa93ac01","市场监管总局公布一批“守护消费”铁拳行动 产品质量安全典型案例","市场监管总局","2026-09-01","行政处罚/通报"],["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"],["cr-9dbcae37f7","四川鑫亿佳防水工程有限公司销售以不合格产品冒充合格产品案（泸市监罚〔2026〕7号）","泸州市市场监督管理局","2026-01-20","行政处罚信息公开表"],["cr-c884d918d5","泸州宁品润建筑材料有限公司销售以不合格产品冒充合格产品案（泸市监罚〔2026〕5号）","泸州市市场监督管理局","2025-01-13","行政处罚信息公开表"]]],"广告法|第五十八条":["第五十八条 有下列行为之一的，由工商行政管理部门责令停止发布广告，责令广告主在相应范围内消除影响，处广告费用一倍以上三倍以下的罚款，广告费用无法计算或者明显偏低的，处十万元以上二十万元以下的罚款；情节严重的，处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款，可以吊销营业执照，并由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请：\n（一）违反本法第十六条规定发布医疗、药品、医疗器械广告的；\n（二）违反本法第十七条规定，在广告中涉及疾病治疗功能，以及使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语的；\n（三）违反本法第十八条规定发布保健食品广告的；\n（四）违反本法第二十一条规定发布农药、兽药、饲料和饲料添加剂广告的；\n（五）违反本法第二十三条规定发布酒类广告的；\n（六）违反本法第二十四条规定发布教育、培训广告的；\n（七）违反本法第二十五条规定发布招商等有投资回报预期的商品或者服务广告的；\n（八）违反本法第二十六条规定发布房地产广告的；\n（九）违反本法第二十七条规定发布农作物种子、林木种子、草种子、种畜禽、水产苗种和种养殖广告的；\n（十）违反本法第三十八条第二款规定，利用不满十周岁的未成年人作为广告代言人的；\n（十一）违反本法第三十八条第三款规定，利用自然人、法人或者其他组织作为广告代言人的；\n（十二）违反本法第三十九条规定，在中小学校、幼儿园内或者利用与中小学生、幼儿有关的物品发布广告的；\n（十三）违反本法第四十条第二款规定，发布针对不满十四周岁的未成年人的商品或者服务的广告的；\n（十四）违反本法第四十六条规定，未经审查发布广告的。医疗机构有前款规定违法行为，情节严重的，除由工商行政管理部门依照本法处罚外，卫生行政部门可以吊销诊疗科目或者吊销医疗机构执业许可证。广告经营者、广告发布者明知或者应知有本条第一款规定违法行为仍设计、制作、代理、发布的，由工商行政管理部门没收广告费用，并处广告费用一倍以上三倍以下的罚款，广告费用无法计算或者明显偏低的，处十万元以上二十万元以下的罚款；情节严重的，处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款，并可以由有关部门暂停广告发布业务、吊销营业执照、吊销广告发布登记证件。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",6,"现行有效","2021-04-29",[["cr-2c1be8ee40","发布涉及疾病治疗功能及使用医疗用语的违法广告案（粤市监处罚〔2026〕13号）","广东省市场监督管理局","2026-08-24","行政处罚决定书"],["cr-9972d1c417","四川川一口腔门诊部有限公司未经审查及利用患者形象作推荐证明发布医疗广告案（泸市监罚〔2026〕42号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"],["cr-3e7fd3552e","古蔺县山态农业发展有限公司未按规定明码标价、不执行政府定价案（泸市监处罚〔2026〕22号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-970741d869","四川浓香老窖品牌管理有限公司实施混淆行为案（泸市监处罚〔2026〕23号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-92b8b28fd7","四川省川酒集团国浆销售有限公司涉嫌发布涉及疾病治疗功能的酒类广告及含有保证性投资回报承诺的招商广告案（泸市监罚〔2026〕24号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-d2aca5b8c5","发布含有利用受益者的名义作推荐、证明的教育、培训违法广告案（粤市监北稽罚〔2024〕018号）","广东省市场监督管理局","2025-02-21","行政处罚决定书"]]],"行政处罚法|第七十二条":["第七十二条 当事人逾期不履行行政处罚决定的，作出行政处罚决定的行政机关可以采取下列措施：\n（一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额；\n（二）根据法律规定，将查封、扣押的财物拍卖、依法处理或者将冻结的存款、汇款划拨抵缴罚款；\n（三）根据法律规定，采取其他行政强制执行方式；\n（四）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。\n行政机关批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",14,"现行有效","2021-07-15",[["cr-2c1be8ee40","发布涉及疾病治疗功能及使用医疗用语的违法广告案（粤市监处罚〔2026〕13号）","广东省市场监督管理局","2026-08-24","行政处罚决定书"],["cr-e8dc966852","专利代理条例》第二十七条规定所指的“违反本条例规定擅自开展专利代理业务”案（粤市监处罚〔2026〕8号）","广东省市场监督管理局","2026-07-06","行政处罚决定书"],["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-214bf92256","四川唐朝老窖（集团）有限公司生产标签含有虚假内容的食品案（泸市监处罚〔2026〕25号）","泸州市市场监督管理局","2026-04-09","行政处罚信息公开表"],["cr-d806f4fadf","生产不符合国家标准的卧式干发护发机案（粤市监罚〔2025〕粤北办007号）","广东省市场监督管理局","2026-01-23","行政处罚决定书"],["cr-e53ef52dcb","组织虚假交易帮助其他经营者进行引人误解的商业宣传的不正当竞争案（粤市监罚〔2025〕粤北办002号）","广东省市场监督管理局","2026-01-15","行政处罚决定书"],["cr-88c87fbcbd","生产经营标签不符合规定的食品等违法行为案（粤市监罚〔2025〕广州办1219号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"],["cr-d2aca5b8c5","发布含有利用受益者的名义作推荐、证明的教育、培训违法广告案（粤市监北稽罚〔2024〕018号）","广东省市场监督管理局","2025-02-21","行政处罚决定书"]]],"食品安全法|第三十四条":["第三十四条\n禁止生产经营下列食品、食品添加剂、食品相\n关产品：\n（一）用非食品原料生产的食品或者添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品，或者用回收食品作为原料生产的食品；\n（二）致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品、食品添加剂、食品相关产品；\n（三）用超过保质期的食品原料、食品添加剂生产的食品、食品添加剂；\n（四）超范围、超限量使用食品添加剂的食品；\n（五）营养成分不符合食品安全标准的专供婴幼儿和其他特定人群的主辅食品；\n（六）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂；\n（七）病死、毒死或者死因不明的禽、畜、兽、水产动物肉类及其制品；\n（八）未按规定进行检疫或者检疫不合格的肉类，或者未经检验或者检验不合格的肉类制品；\n（九）被包装材料、容器、运输工具等污染的食品、食品添\n加剂；\n（十）标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂；\n（十一）无标签的预包装食品、食品添加剂；\n（十二）国家为防病等特殊需要明令禁止生产经营的食品；\n（十三）其他不符合法律、法规或者食品安全标准的食品、食品添加剂、食品相关产品。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",15,"现行有效","2025-12-01",[["cr-914952d9a5","整治制售假劣肉制品专项行动典型案例","无锡市市场监督管理局","2026-08-07","行政处罚决定书"],["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-ed581c8f1b","无锡市市场监管局发布网络餐饮食品安全典型案例（第一批）","无锡市市场监督管理局","2026-03-31","行政处罚决定书"],["cr-ff376ddcea","福州公布“铁拳”行动第三批典型案例","地方市场监管局","2025-12-29","行政处罚/通报"],["cr-ea1afe8345","生产虚假标注生产日期的食品案（泸市监处〔2025〕30号）","泸州市市场监督管理局","2025-12-26","行政处罚信息公开表"],["cr-787c296e78","生产虚假标注生产日期的食品案（泸市监处〔2025〕31号）","泸州市市场监督管理局","2025-12-26","行政处罚信息公开表"],["cr-ce03af7695","重庆公布五起农村假冒伪劣食品典型违法案件","市场监管总局","2025-12-03","行政处罚/通报"],["cr-d1ae688d03","福建泉州公布2025年“守护消费”案件查办 铁拳行动典型案例","地方市场监管局","2025-06-25","行政处罚/通报"]]],"食品安全法|第一百二十四条":["第一百二十四条违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚\n款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款；情节严重的，吊销许可证：\n（一）生产经营致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品、食品添加剂；\n（二）用超过保质期的食品原料、食品添加剂生产食品、食品添加剂，或者经营上述食品、食品添加剂；\n（三）生产经营超范围、超限量使用食品添加剂的食品；\n（四）生产经营腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂；\n（五）生产经营标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂；\n（六）生产经营未按规定注册的保健食品、特殊医学用途配方食品、婴幼儿配方乳粉，或者未按注册的产品配方、生产工艺等技术要求组织生产；\n（七）以分装方式生产婴幼儿配方乳粉，或者同一企业以同一配方生产不同品牌的婴幼儿配方乳粉；\n（八）利用新的食品原料生产食品，或者生产食品添加剂新品种，未通过安全性评估；\n（九）食品生产经营者在食品安全监督管理部门责令其召回或者停止经营后，仍拒不召回或者停止经营。除前款和本法第一百二十三条、第一百二十五条规定的情形\n外，生产经营不符合法律、法规或者食品安全标准的食品、食品添加剂的，依照前款规定给予处罚。生产食品相关产品新品种，未通过安全性评估，或者生产不符合食品安全标准的食品相关产品的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",9,"现行有效","2025-12-01",[["cr-914952d9a5","整治制售假劣肉制品专项行动典型案例","无锡市市场监督管理局","2026-08-07","行政处罚决定书"],["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-ed581c8f1b","无锡市市场监管局发布网络餐饮食品安全典型案例（第一批）","无锡市市场监督管理局","2026-03-31","行政处罚决定书"],["cr-ea1afe8345","生产虚假标注生产日期的食品案（泸市监处〔2025〕30号）","泸州市市场监督管理局","2025-12-26","行政处罚信息公开表"],["cr-787c296e78","生产虚假标注生产日期的食品案（泸市监处〔2025〕31号）","泸州市市场监督管理局","2025-12-26","行政处罚信息公开表"],["cr-57db04f5aa","西藏自治区市场监管局民生领域案件查办 “铁拳”行动典型案例（第一批）","地方市场监管局","2025-05-21","行政处罚/通报"],["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"],["cr-f30fcd274a","泸州市杰蒙商贸有限公司经营五氯酚酸钠超过食品安全标准限量的食品案（泸市监罚〔2024〕37号）","泸州市市场监督管理局","2024-11-11","行政处罚信息公开表"]]],"反垄断法|第二十二条":["第二十二条 禁止具有市场支配地位的经营者从事下列滥用市场支配地位的行为：\n（一）以不公平的高价销售商品或者以不公平的低价购买商品；\n（二）没有正当理由，以低于成本的价格销售商品；\n（三）没有正当理由，拒绝与交易相对人进行交易；\n（四）没有正当理由，限定交易相对人只能与其进行交易或者只能与其指定的经营者进行交易；\n（五）没有正当理由搭售商品，或者在交易时附加其他不合理的交易条件；\n（六）没有正当理由，对条件相同的交易相对人在交易价格等交易条件上实行差别待遇；\n（七）国务院反垄断执法机构认定的其他滥用市场支配地位的行为。\n具有市场支配地位的经营者不得利用数据和算法、技术以及平台规则等从事前款规定的滥用市场支配地位的行为。\n本法所称市场支配地位，是指经营者在相关市场内具有能够控制商品价格、数量或者其他交易条件，或者能够阻碍、影响其他经营者进入相关市场能力的市场地位。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",1,"现行有效","2022-08-01",[["cr-df6c2025c1","市场监管总局依法对携程集团有限公司实施 垄断行为作出行政处罚并责令其全面整改","市场监管总局","2026-07-25","行政处罚/通报"]]],"反垄断法|第五十七条":["第五十七条 经营者违反本法规定，滥用市场支配地位的，由反垄断执法机构责令停止违法行为，没收违法所得，并处上一年度销售额百分之一以上百分之十以下的罚款。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",1,"现行有效","2022-08-01",[["cr-df6c2025c1","市场监管总局依法对携程集团有限公司实施 垄断行为作出行政处罚并责令其全面整改","市场监管总局","2026-07-25","行政处罚/通报"]]],"特种设备安全法|第九十条":["第九十条 发生事故，对负有责任的单位除要求其依法承担相应的赔偿等责任外，依照下列规定处以罚款：\n（一）发生一般事故，处十万元以上二十万元以下罚款；\n（二）发生较大事故，处二十万元以上五十万元以下罚款；\n（三）发生重大事故，处五十万元以上二百万元以下罚款。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-eac5c847f5","**经营部（经营者：区**）对事故发生负有主体责任案（江市监处罚〔2026〕3号）","江门市市场监督管理局","2026-07-24","行政处罚信息公开表"]]],"广告法|第四十六条":["第四十六条 发布医疗、药品、医疗器械、农药、兽药和保健食品广告，以及法律、行政法规规定应当进行审查的其他广告，应当在发布前由有关部门（以下称广告审查机关）对广告内容进行审查；未经审查，不得发布。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",1,"现行有效","2021-04-29",[["cr-9972d1c417","四川川一口腔门诊部有限公司未经审查及利用患者形象作推荐证明发布医疗广告案（泸市监罚〔2026〕42号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"]]],"广告法|第三十四条":["第三十四条 广告经营者、广告发布者应当按照国家有关规定，建立、健全广告业务的承接登记、审核、档案管理制度。广告经营者、广告发布者依据法律、行政法规查验有关证明文件，核对广告内容。对内容不符或者证明文件不全的广告，广告经营者不得提供设计、制作、代理服务，广告发布者不得发布。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",2,"现行有效","2021-04-29",[["cr-9972d1c417","四川川一口腔门诊部有限公司未经审查及利用患者形象作推荐证明发布医疗广告案（泸市监罚〔2026〕42号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"],["cr-7f04f21ed5","泸州亦叁广告传媒有限公司未履行广告查验核对义务设计制作违法医疗广告案（泸市监罚〔2026〕43号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"]]],"广告法|第六十条":["第六十条 违反本法第二十九条规定，广播电台、电视台、报刊出版单位未办理广告发布登记，擅自从事广告发布业务的，由工商行政管理部门责令改正，没收违法所得，违法所得一万元以上的，并处违法所得一倍以上三倍以下的罚款；违法所得不足一万元的，并处五千元以上三万元以下的罚款。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",2,"现行有效","2021-04-29",[["cr-9972d1c417","四川川一口腔门诊部有限公司未经审查及利用患者形象作推荐证明发布医疗广告案（泸市监罚〔2026〕42号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"],["cr-7f04f21ed5","泸州亦叁广告传媒有限公司未履行广告查验核对义务设计制作违法医疗广告案（泸市监罚〔2026〕43号）","泸州市市场监督管理局","2026-07-15","行政处罚信息公开表"]]],"市场主体登记管理条例|第四十条":["第四十条 提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得市场主体登记的，受虚假市场主体登记影响的自然人、法人和其他组织可以向登记机关提出撤销市场主体登记的申请。\n登记机关受理申请后，应当及时开展调查。经调查认定存在虚假市场主体登记情形的，登记机关应当撤销市场主体登记。相关市场主体和人员无法联系或者拒不配合的，登记机关可以将相关市场主体的登记时间、登记事项等通过国家企业信用信息公示系统向社会公示，公示期为45日。相关市场主体及其利害关系人在公示期内没有提出异议的，登记机关可以撤销市场主体登记。\n因虚假市场主体登记被撤销的市场主体，其直接责任人自市场主体登记被撤销之日起3年内不得再次申请市场主体登记。登记机关应当通过国家企业信用信息公示系统予以公示。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",1,"现行有效","2022-03-01",[["cr-8b617c0867","提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得市场主体登记”案（云昆市监撤〔2026〕9-001号）","昆明市市场监督管理局","2026-07-09","行政处罚决定书"]]],"市场主体登记管理条例|第十七条":["第十七条 申请人应当对提交材料的真实性、合法性和有效性负责。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",1,"现行有效","2022-03-01",[["cr-8b617c0867","提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得市场主体登记”案（云昆市监撤〔2026〕9-001号）","昆明市市场监督管理局","2026-07-09","行政处罚决定书"]]],"网络食品安全违法行为查处办法|第十六条":["第十六条 入网食品生产经营者应当依法取得许可，入网食品生产者应当按照许可的类别范围销售食品，入网食品经营者应当按照许可的经营项目范围从事食品经营。法律、法规规定不需要取得食品生产经营许可的除外。\n取得食品生产许可的食品生产者，通过网络销售其生产的食品，不需要取得食品经营许可。取得食品经营许可的食品经营者通过网络销售其制作加工的食品，不需要取得食品生产许可。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",1,"现行有效","2016-10-01",[["cr-42567b47d4","安徽省淮南市市场监管局公布 2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-23","行政处罚/通报"]]],"网络食品安全违法行为查处办法|第三十八条":["第三十八条 违反本办法第十六条规定，入网食品生产经营者未依法取得食品生产经营许可的，或者入网食品生产者超过许可的类别范围销售食品、入网食品经营者超过许可的经营项目范围从事食品经营的，依照食品安全法第一百二十二条的规定处罚。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",1,"现行有效","2016-10-01",[["cr-42567b47d4","安徽省淮南市市场监管局公布 2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-23","行政处罚/通报"]]],"食品安全法|第五十四条":["第五十四条\n食品经营者应当按照保证食品安全的要求贮\n存食品，定期检查库存食品，及时清理变质或者超过保质期的食\n品。\n食品经营者贮存散装食品，应当在贮存位置标明食品的名\n称、生产日期或者生产批号、保质期、生产者名称及联系方式等\n内容。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",2,"现行有效","2025-12-01",[["cr-42567b47d4","安徽省淮南市市场监管局公布 2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-23","行政处罚/通报"],["cr-8676d3d4a8","无锡市市场监管局发布网络餐饮食品安全典型案例（第二批）","无锡市市场监督管理局","2026-06-08","行政处罚决定书"]]],"食品安全法|第一百三十二条":["第一百三十二条违反本法规定，未按要求进行食品贮存、运输和装卸的，由县级以上人民政府食品安全监督管理等部门按\n照各自职责分工责令改正，给予警告；拒不改正的，责令停产停业，并处一万元以上五万元以下罚款；情节严重的，吊销许可证。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",1,"现行有效","2025-12-01",[["cr-42567b47d4","安徽省淮南市市场监管局公布 2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-23","行政处罚/通报"]]],"消费者权益保护法实施条例|第二十一条":["第二十一条 经营者决定停业或者迁移服务场所的，应当提前30日在其经营场所、网站、网店首页等的醒目位置公告经营者的有效联系方式等信息。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",1,"现行有效","2024-07-01",[["cr-a281fb2855","安徽省市场监管局公布2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-10","行政处罚/通报"]]],"消费者权益保护法实施条例|第五十条":["第五十条 经营者违反本条例第十条至第十四条、第十六条、第十七条、第十九条至第二十一条规定，其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由市场监督管理部门或者其他有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得1倍以上5倍以下的罚款，没有违法所得的，处以30万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照。经营者违反本条例第二十二条规定的，由有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得1倍以上10倍以下的罚款，没有违法所得的，处以50万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照。经营者违反本条例其他规定的，依照消费者权益保护法第五十六条的规定予以处罚。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",2,"现行有效","2024-07-01",[["cr-a281fb2855","安徽省市场监管局公布2026“守护消费”铁拳行动典型案例","地方市场监管局","2026-06-10","行政处罚/通报"],["cr-7594e321d4","安徽省市场监管局公布“守护消费”铁拳行动第一批典型案例","地方市场监管局","2025-03-19","行政处罚/通报"]]],"食品安全法实施条例|第二十九条":["第二十九条 食品生产经营者应当对变质、超过保质期或者回收的食品进行显著标示或者单独存放在有明确标志的场所，及时采取无害化处理、销毁等措施并如实记录。\n食品安全法所称回收食品，是指已经售出，因违反法律、法规、食品安全标准或者超过保质期等原因，被召回或者退回的食品，不包括依照食品安全法第六十三条第三款的规定可以继续销售的食品。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",1,"现行有效","2019-12-01",[["cr-8676d3d4a8","无锡市市场监管局发布网络餐饮食品安全典型案例（第二批）","无锡市市场监督管理局","2026-06-08","行政处罚决定书"]]],"食品安全法实施条例|第六十九条":["第六十九条 有下列情形之一的，依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚：\n(一)接受食品生产经营者委托贮存、运输食品，未按照规定记录保存信息；\n(二)餐饮服务提供者未查验、留存餐具饮具集中消毒服务单位的营业执照复印件和消毒合格证明；\n(三)食品生产经营者未按照规定对变质、超过保质期或者回收的食品进行标示或者存放，或者未及时对上述食品采取无害化处理、销毁等措施并如实记录；\n(四)医疗机构和药品零售企业之外的单位或者个人向消费者销售特殊医学用途配方食品中的特定全营养配方食品；\n(五)将特殊食品与普通食品或者药品混放销售。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",1,"现行有效","2019-12-01",[["cr-8676d3d4a8","无锡市市场监管局发布网络餐饮食品安全典型案例（第二批）","无锡市市场监督管理局","2026-06-08","行政处罚决定书"]]],"反不正当竞争法|第二十五条":["第二十五条 经营者违反本法第九条规定对其商品作虚假或者引人误解的商业宣传，或者通过组织虚假交易、虚假评价等方式帮助其他经营者进行虚假或者引人误解的商业宣传的，由监督检查部门责令停止违法行为，处一百万元以下的罚款；情节严重的，处一百万元以上二百万元以下的罚款，可以并处吊销营业执照。\n经营者违反本法第九条规定，属于发布虚假广告的，依照《中华人民共和国广告法》的规定处罚。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",3,"现行有效","2025-10-15",[["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"],["cr-e479322e38","市场监管总局集中发布第六批直播电商 领域典型案例","市场监管总局","2026-04-29","行政处罚/通报"],["cr-2223a26dfb","生产经营标签不符合规定的预包装食品案（粤市监广州办罚〔2025〕1220号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"]]],"行政处罚法|第二十九条":["第二十九条 对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",3,"现行有效","2021-07-15",[["cr-dbdde78360","市场监管总局公布一批传统工艺市场 “打假清源”典型案例","市场监管总局","2026-06-04","行政处罚/通报"],["cr-b93c046109","海南公布7件2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-07-02","行政处罚/通报"],["cr-897dbc0ba5","无锡市市场监管局公布电动自行车安全隐患全链条整治违法典型案例（第二批）","无锡市市场监督管理局","2024-10-31","行政处罚决定书"]]],"广告法|第二十八条":["第二十八条 广告以虚假或者引人误解的内容欺骗、误导消费者的，构成虚假广告。广告有下列情形之一的，为虚假广告：\n（一）商品或者服务不存在的；\n（二）商品的性能、功能、产地、用途、质量、规格、成分、价格、生产者、有效期限、销售状况、曾获荣誉等信息，或者服务的内容、提供者、形式、质量、价格、销售状况、曾获荣誉等信息，以及与商品或者服务有关的允诺等信息与实际情况不符，对购买行为有实质性影响的；\n（三）使用虚构、伪造或者无法验证的科研成果、统计资料、调查结果、文摘、引用语等信息作证明材料的；\n（四）虚构使用商品或者接受服务的效果的；\n（五）以虚假或者引人误解的内容欺骗、误导消费者的其他情形。\n第三章 广告行为规范","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",3,"现行有效","2021-04-29",[["cr-a9f64ac71c","无锡市市场监管局发布保护未成年人权益典型案例","无锡市市场监督管理局","2026-05-29","行政处罚决定书"],["cr-420b03de40","四川成都公布2024“铁拳”“春雷”行动 第三批典型案例","地方市场监管局","2024-10-11","行政处罚/通报"],["cr-d16932937a","陕西省市场监管局公布2024民生领域 “铁拳”行动典型案例（第四批）","地方市场监管局","2024-08-26","行政处罚/通报"]]],"广告法|第五十五条":["第五十五条 违反本法规定，发布虚假广告的，由工商行政管理部门责令停止发布广告，责令广告主在相应范围内消除影响，处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款；两年内有三次以上违法行为或者有其他严重情节的，处广告费用五倍以上十倍以下的罚款，广告费用无法计算或者明显偏低的，处一百万元以上二百万元以下的罚款，可以吊销营业执照，并由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请。医疗机构有前款规定违法行为，情节严重的，除由工商行政管理部门依照本法处罚外，卫生行政部门可以吊销诊疗科目或者吊销医疗机构执业许可证。广告经营者、广告发布者明知或者应知广告虚假仍设计、制作、代理、发布的，由工商行政管理部门没收广告费用，并处广告费用三倍以上五倍以下的罚款，广告费用无法计算或者明显偏低的，处二十万元以上一百万元以下的罚款；两年内有三次以上违法行为或者有其他严重情节的，处广告费用五倍以上十倍以下的罚款，广告费用无法计算或者明显偏低的，处一百万元以上二百万元以下的罚款，并可以由有关部门暂停广告发布业务、吊销营业执照、吊销广告发布登记证件。广告主、广告经营者、广告发布者有本条第一款、第三款规定行为，构成犯罪的，依法追究刑事责任。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",3,"现行有效","2021-04-29",[["cr-a9f64ac71c","无锡市市场监管局发布保护未成年人权益典型案例","无锡市市场监督管理局","2026-05-29","行政处罚决定书"],["cr-420b03de40","四川成都公布2024“铁拳”“春雷”行动 第三批典型案例","地方市场监管局","2024-10-11","行政处罚/通报"],["cr-d16932937a","陕西省市场监管局公布2024民生领域 “铁拳”行动典型案例（第四批）","地方市场监管局","2024-08-26","行政处罚/通报"]]],"食品安全法|第一百二十五条":["第一百二十五条违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五千元以上五万元以下罚款；货值金额一万元以上的，并处货值金额五倍以上十倍以下罚款；情节严重的，责令停产停业，直至吊销许可证：\n（一）生产经营被包装材料、容器、运输工具等污染的食品、食品添加剂；\n（二）生产经营无标签的预包装食品、食品添加剂或者标签、说明书不符合本法规定的食品、食品添加剂；\n（三）生产经营转基因食品未按规定进行标示；\n（四）食品生产经营者采购或者使用不符合食品安全标准的食品原料、食品添加剂、食品相关产品。生产经营的食品、食品添加剂的标签、说明书存在瑕疵但不影响食品安全且不会对消费者造成误导的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，处二千元以下罚\n款。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",7,"现行有效","2025-12-01",[["cr-f20d801f10","泸州振宏工程项目管理咨询有限公司经营标签不符合食品安全法规定的食品及销售应知是实施了混淆行为的商品案（泸市监处罚〔2026〕29号）","泸州市市场监督管理局","2026-05-07","行政处罚信息公开表"],["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-88c87fbcbd","生产经营标签不符合规定的食品等违法行为案（粤市监罚〔2025〕广州办1219号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"],["cr-ce03af7695","重庆公布五起农村假冒伪劣食品典型违法案件","市场监管总局","2025-12-03","行政处罚/通报"],["cr-57db04f5aa","西藏自治区市场监管局民生领域案件查办 “铁拳”行动典型案例（第一批）","地方市场监管局","2025-05-21","行政处罚/通报"],["cr-966d2f8de2","生产标签不符合法律规定的白酒案（泸市监罚〔2024〕39号）","泸州市市场监督管理局","2024-10-31","行政处罚信息公开表"],["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"四川省反不正当竞争条例|第二十九条":["第二十九条 经营者之间不得通过协议、约定等手段采取下列限制或妨碍公平竞争的联合行为:\n（一）联合限定价格或者约定其他不合理的经济条件;\n（二）分割市场;\n（三）联合拒绝购买、销售或者服务。\n有下列联合行为之一的，不属于不正当竞争行为:\n（一）为降低成本、改进质量而统一商品规格和技术要求或者共同研究开发商品的;\n（二）为适应市场经营而优化组合，进行专业化发展的;\n（三）其他有利于社会经济发展和社会公共利益而采取的联合行为。\n第三章 监督检查","d1a9a919c5","四川省反不正当竞争条例","https://flk.npc.gov.cn/detail2.html?NDAyOGFiY2M2MTI3Nzc5MzAxNjEyODg3ZTYwMDNmMzg=",1,"已修改","2012-07-27",[["cr-f20d801f10","泸州振宏工程项目管理咨询有限公司经营标签不符合食品安全法规定的食品及销售应知是实施了混淆行为的商品案（泸市监处罚〔2026〕29号）","泸州市市场监督管理局","2026-05-07","行政处罚信息公开表"]]],"国务院关于经营者集中申报标准的规定|第三条":["第三条 经营者集中达到下列标准之一的，经营者应当事先向国务院反垄断执法机构申报，未申报的不得实施集中：\n（一）参与集中的所有经营者上一会计年度在全球范围内的营业额合计超过120亿元人民币，并且其中至少两个经营者上一会计年度在中国境内的营业额均超过8亿元人民币；\n（二）参与集中的所有经营者上一会计年度在中国境内的营业额合计超过40亿元人民币，并且其中至少两个经营者上一会计年度在中国境内的营业额均超过8亿元人民币。\n营业额的计算，应当考虑银行、保险、证券、期货等特殊行业、领域的实际情况，具体办法由国务院反垄断执法机构会同国务院有关部门制定。","be03f745f8","国务院关于经营者集中申报标准的规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4ZDczNmUwODAxOGRjZjhmOTYwZjA1NGQ=",1,"现行有效","2024-01-22",[["cr-5fcbf477a0","违反反垄断法实施经营者集中 市场监管总局对上海奔汇企业管理有限公司罚款200万元","市场监管总局","2026-04-29","行政处罚/通报"]]],"反垄断法|第三十条":["第三十条 国务院反垄断执法机构应当自收到经营者提交的符合本法第二十八条规定的文件、资料之日起三十日内，对申报的经营者集中进行初步审查，作出是否实施进一步审查的决定，并书面通知经营者。国务院反垄断执法机构作出决定前，经营者不得实施集中。\n国务院反垄断执法机构作出不实施进一步审查的决定或者逾期未作出决定的，经营者可以实施集中。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",1,"现行有效","2022-08-01",[["cr-5fcbf477a0","违反反垄断法实施经营者集中 市场监管总局对上海奔汇企业管理有限公司罚款200万元","市场监管总局","2026-04-29","行政处罚/通报"]]],"市场主体登记管理条例|第四十六条":["第四十六条 市场主体未依照本条例办理变更登记的，由登记机关责令改正；拒不改正的，处1万元以上10万元以下的罚款；情节严重的，吊销营业执照。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",1,"现行有效","2022-03-01",[["cr-e479322e38","市场监管总局集中发布第六批直播电商 领域典型案例","市场监管总局","2026-04-29","行政处罚/通报"]]],"食品安全法|第六十七条":["第六十七条\n预包装食品的包装上应当有标签。标签应当标\n明下列事项：\n（一）名称、规格、净含量、生产日期；\n（二）成分或者配料表；\n（三）生产者的名称、地址、联系方式；\n（四）保质期；\n（五）产品标准代号；\n（六）贮存条件；\n（七）所使用的食品添加剂在国家标准中的通用名称；\n（八）生产许可证编号；\n（九）法律、法规或者食品安全标准规定应当标明的其他事项。专供婴幼儿和其他特定人群的主辅食品，其标签还应当标明主要营养成分及其含量。食品安全国家标准对标签标注事项另有规定的，从其规定。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",2,"现行有效","2025-12-01",[["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-966d2f8de2","生产标签不符合法律规定的白酒案（泸市监罚〔2024〕39号）","泸州市市场监督管理局","2024-10-31","行政处罚信息公开表"]]],"食品安全法|第五十条":["第五十条食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明；对无法提供合格证明的食品原料，应当按照食品安全标准进行检验；不得采购或者使用不符合食品安全标准的食品原料、食品添加剂、食品相关产品。\n食品生产企业应当建立食品原料、食品添加剂、食品相关产品进货查验记录制度，如实记录食品原料、食品添加剂、食品相关产品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",3,"现行有效","2025-12-01",[["cr-b47a56289d","古蔺县盛源农业开发有限公司提供虚假材料申请食品生产许可、生产超范围使用食品添加剂和标签不符合法律规定的食品案（泸市监处罚〔2026〕28号）","泸州市市场监督管理局","2026-04-13","行政处罚信息公开表"],["cr-214bf92256","四川唐朝老窖（集团）有限公司生产标签含有虚假内容的食品案（泸市监处罚〔2026〕25号）","泸州市市场监督管理局","2026-04-09","行政处罚信息公开表"],["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"医疗器械监督管理条例|第八十六条":["第八十六条 有下列情形之一的，由负责药品监督管理的部门责令改正，没收违法生产经营使用的医疗器械；违法生产经营使用的医疗器械货值金额不足1万元的，并处2万元以上5万元以下罚款；货值金额1万元以上的，并处货值金额5倍以上20倍以下罚款；情节严重的，责令停产停业，直至由原发证部门吊销医疗器械注册证、医疗器械生产许可证、医疗器械经营许可证，对违法单位的法定代表人、主要负责人、直接负责的主管人员和其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入30%以上3倍以下罚款，10年内禁止其从事医疗器械生产经营活动：\n（一）生产、经营、使用不符合强制性标准或者不符合经注册或者备案的产品技术要求的医疗器械；\n（二）未按照经注册或者备案的产品技术要求组织生产，或者未依照本条例规定建立质量管理体系并保持有效运行，影响产品安全、有效；\n（三）经营、使用无合格证明文件、过期、失效、淘汰的医疗器械，或者使用未依法注册的医疗器械；\n（四）在负责药品监督管理的部门责令召回后仍拒不召回，或者在负责药品监督管理的部门责令停止或者暂停生产、进口、经营后，仍拒不停止生产、进口、经营医疗器械；\n（五）委托不具备本条例规定条件的企业生产医疗器械，或者未对受托生产企业的生产行为进行管理；\n（六）进口过期、失效、淘汰等已使用过的医疗器械。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",2,"现行有效","2025-01-20",[["cr-08dd2bb5ab","四川立心命智慧医疗科技有限公司未按照经备案的产品技术要求组织生产以及生产说明书、标签不符合《医疗器械监督管理条例》规定的医疗器械案（泸市监罚〔2026〕21号）","泸州市市场监督管理局","2026-04-08","行政处罚信息公开表"],["cr-aba53c243f","江门市**医院使用过期的医疗器械案（江市监行罚〔2026〕1号）","江门市市场监督管理局","2026-03-19","行政处罚信息公开表"]]],"价格法|第十二条":["第十二条 经营者进行价格活动，应当遵守法律、法规，执行依法制定的政府指导价、政府定价和法定的价格干预措施、紧急措施。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",7,"现行有效","1998-05-01",[["cr-3e7fd3552e","古蔺县山态农业发展有限公司未按规定明码标价、不执行政府定价案（泸市监处罚〔2026〕22号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-51459aafa2","严查收费乱象 规范市场秩序 江西通报一批电动自行车充电市场价格执法 典型案例","地方市场监管局","2025-06-18","行政处罚/通报"],["cr-18e6e1afca","四川兴叙水业有限公司扩大范围收费案（泸市监罚〔2025〕13号）","泸州市市场监督管理局","2025-06-10","行政处罚信息公开表"],["cr-d7d563059a","合江县殡仪馆价格违法案（泸市监罚〔2025〕8号）","泸州市市场监督管理局","2025-05-22","行政处罚信息公开表"],["cr-d17c346805","泸州市殡仪馆价格违法案（泸市监罚〔2025〕9号）","泸州市市场监督管理局","2025-05-22","行政处罚信息公开表"],["cr-225434fe70","古蔺县德馨殡葬服务有限公司不执行政府指导价、政府定价案（泸市监罚〔2025〕10号）","泸州市市场监督管理局","2025-05-21","行政处罚信息公开表"],["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"]]],"价格违法行为行政处罚规定|第九条":["第九条 经营者不执行政府指导价、政府定价，有下列行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款，情节较重的处50万元以上200万元以下的罚款；情节严重的，责令停业整顿：\n(一)超出政府指导价浮动幅度制定价格的；\n(二)高于或者低于政府定价制定价格的；\n(三)擅自制定属于政府指导价、政府定价范围内的商品或者服务价格的；\n(四)提前或者推迟执行政府指导价、政府定价的；\n(五)自立收费项目或者自定标准收费的；\n(六)采取分解收费项目、重复收费、扩大收费范围等方式变相提高收费标准的；\n(七)对政府明令取消的收费项目继续收费的；\n(八)违反规定以保证金、抵押金等形式变相收费的；\n(九)强制或者变相强制服务并收费的；\n(十)不按照规定提供服务而收取费用的；\n(十一)不执行政府指导价、政府定价的其他行为。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",5,"现行有效","2010-12-04",[["cr-3e7fd3552e","古蔺县山态农业发展有限公司未按规定明码标价、不执行政府定价案（泸市监处罚〔2026〕22号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-18e6e1afca","四川兴叙水业有限公司扩大范围收费案（泸市监罚〔2025〕13号）","泸州市市场监督管理局","2025-06-10","行政处罚信息公开表"],["cr-d7d563059a","合江县殡仪馆价格违法案（泸市监罚〔2025〕8号）","泸州市市场监督管理局","2025-05-22","行政处罚信息公开表"],["cr-d17c346805","泸州市殡仪馆价格违法案（泸市监罚〔2025〕9号）","泸州市市场监督管理局","2025-05-22","行政处罚信息公开表"],["cr-225434fe70","古蔺县德馨殡葬服务有限公司不执行政府指导价、政府定价案（泸市监罚〔2025〕10号）","泸州市市场监督管理局","2025-05-21","行政处罚信息公开表"]]],"反不正当竞争法|第七条":["第七条 经营者不得实施下列混淆行为，引人误认为是他人商品或者与他人存在特定联系：\n（一）擅自使用与他人有一定影响的商品名称、包装、装潢等相同或者近似的标识；\n（二）擅自使用他人有一定影响的名称（包括简称、字号等）、姓名（包括笔名、艺名、网名、译名等）；\n（三）擅自使用他人有一定影响的域名主体部分、网站名称、网页、新媒体账号名称、应用程序名称或者图标等；\n（四）其他足以引人误认为是他人商品或者与他人存在特定联系的混淆行为。\n经营者不得帮助他人实施混淆行为。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",3,"现行有效","2025-10-15",[["cr-3e7fd3552e","古蔺县山态农业发展有限公司未按规定明码标价、不执行政府定价案（泸市监处罚〔2026〕22号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-970741d869","四川浓香老窖品牌管理有限公司实施混淆行为案（泸市监处罚〔2026〕23号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-01257ad3f3","国药集团四川省医疗技术有限公司商业贿赂案（泸市监罚〔2025〕16号）","泸州市市场监督管理局","2025-06-27","行政处罚信息公开表"]]],"反不正当竞争法|第二十三条":["第二十三条 经营者违反本法第七条规定实施混淆行为或者帮助他人实施混淆行为的，由监督检查部门责令停止违法行为，没收违法商品。违法经营额五万元以上的，可以并处违法经营额五倍以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以并处二十五万元以下的罚款；情节严重的，并处吊销营业执照。\n销售本法第七条规定的违法商品的，依照前款规定予以处罚；销售者不知道其销售的商品属于违法商品，能证明该商品是自己合法取得并说明提供者的，由监督检查部门责令停止销售，不予行政处罚。\n经营者登记的名称违反本法第七条规定的，应当及时办理名称变更登记；名称变更前，由登记机关以统一社会信用代码代替其名称。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",2,"现行有效","2025-10-15",[["cr-3e7fd3552e","古蔺县山态农业发展有限公司未按规定明码标价、不执行政府定价案（泸市监处罚〔2026〕22号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-970741d869","四川浓香老窖品牌管理有限公司实施混淆行为案（泸市监处罚〔2026〕23号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"]]],"市场主体登记管理条例|第四十四条":["第四十四条 提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得市场主体登记的，由登记机关责令改正，没收违法所得，并处5万元以上20万元以下的罚款；情节严重的，处20万元以上100万元以下的罚款，吊销营业执照。\n实行注册资本实缴登记制的市场主体的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，或者在市场主体成立后抽逃出资的，由登记机关责令改正，处虚假出资金额5%以上15%以下的罚款。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",3,"现行有效","2022-03-01",[["cr-970741d869","四川浓香老窖品牌管理有限公司实施混淆行为案（泸市监处罚〔2026〕23号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-92b8b28fd7","四川省川酒集团国浆销售有限公司涉嫌发布涉及疾病治疗功能的酒类广告及含有保证性投资回报承诺的招商广告案（泸市监罚〔2026〕24号）","泸州市市场监督管理局","2026-04-07","行政处罚信息公开表"],["cr-592b8b5c54","泸州泸酒酒业有限公司隐瞒重要事实取得注销登记案（泸市监罚〔2026〕13号）","泸州市市场监督管理局","2026-03-05","行政处罚信息公开表"]]],"医疗器械监督管理条例|第五十五条":["第五十五条 医疗器械经营企业、使用单位不得经营、使用未依法注册或者备案、无合格证明文件以及过期、失效、淘汰的医疗器械。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",1,"现行有效","2025-01-20",[["cr-aba53c243f","江门市**医院使用过期的医疗器械案（江市监行罚〔2026〕1号）","江门市市场监督管理局","2026-03-19","行政处罚信息公开表"]]],"食品安全法|第五十三条":["第五十三条食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明（以下称合格证明文件）。食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。\n实行统一配送经营方式的食品经营企业，可以由企业总部统一查验供货者的许可证和食品合格证明文件，进行食品进货查验记录。从事食品批发业务的经营企业应当建立食品销售记录制度，如实记录批发食品的名称、规格、数量、生产日期或者生产批号、保质期、销售日期以及购货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",5,"现行有效","2025-12-01",[["cr-6700c4b6f5","福建泉州发布2026年“铁拳”行动典型案例暨2025年度消费侵权典型案例","地方市场监管局","2026-03-17","行政处罚/通报"],["cr-17133bc05f","使用不符合食品安全标准的食品案（泸市监罚〔2025〕23号）","泸州市市场监督管理局","2025-10-16","行政处罚信息公开表"],["cr-813a8ce035","陕西省市场监管局2025“守护消费”铁拳行动第一批暨知识产权执法十大典型案例","地方市场监管局","2025-04-30","行政处罚/通报"],["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"],["cr-392c667c87","重大损害风险案","无锡市市场监督管理局","2025-03-17","行政处罚决定书"]]],"网络交易监督管理办法|第十四条":["第十四条网络交易经营者不得违反《中华人民共和国反不正当竞争法》等规定，实施扰乱市场竞争秩序，损害其他经营者或者消费者合法权益的不正当竞争行为。网络交易经营者不得以下列方式，作虚假或者引人误解的商业宣传，欺骗、误导消费者：\n（一）虚构交易、编造用户评价；\n（二）采用误导性展示等方式，将好评前置、差评后置，或者不显著区分不同商品或者服务的评价等；\n（三）采用谎称现货、虚构预订、虚假抢购等方式进行虚假营销；\n（四）虚构点击量、关注度等流量数据，以及虚构点赞、打赏等交易互动数据。网络交易经营者不得实施混淆行为，引人误认为是他人商品、服务或者与他人存在特定联系。网络交易经营者不得编造、传播虚假信息或者误导性信息，损害竞争对手的商业信誉、商品声誉。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",1,"现行有效","2021-05-01",[["cr-6700c4b6f5","福建泉州发布2026年“铁拳”行动典型案例暨2025年度消费侵权典型案例","地方市场监管局","2026-03-17","行政处罚/通报"]]],"行政强制法|第五十四条":["第五十四条 行政机关申请人民法院强制执行前，应当催告当事人履行义务。催告书送达十日后当事人仍未履行义务的，行政机关可以向所在地有管辖权的人民法院申请强制执行；执行对象是不动产的，向不动产所在地有管辖权的人民法院申请强制执行。","65080ea4ea","中华人民共和国行政强制法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3MmY3YTA2MTM=",1,"现行有效","2012-01-01",[["cr-967619ccae","昆明市市场监督管理局行政处罚决定履行催告书云市监昆罚催〔2025〕37-9-2号","昆明市市场监督管理局","2026-03-06","行政处罚决定书"]]],"反不正当竞争法|第二十条":["第二十条 对涉嫌不正当竞争行为，任何单位和个人有权向监督检查部门举报，监督检查部门接到举报后应当依法及时处理。\n监督检查部门应当向社会公开受理举报的电话、信箱或者电子邮件地址，并为举报人保密。对实名举报并提供相关事实和证据的，监督检查部门应当将处理结果及时告知举报人。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",3,"现行有效","2025-10-15",[["cr-f47ba298e9","上海发布2025年度不正当竞争典型案例","地方市场监管局","2026-02-10","行政处罚/通报"],["cr-a9e92fd6af","雷吉未经许可从事化妆品生产活动，对其商品的销售状况作虚假的商业宣传案（泸市监罚〔2025〕20号）","泸州市市场监督管理局","2025-09-29","行政处罚信息公开表"],["cr-a08a8736fb","黑龙江省市场监管局公布2024年第一批 典型案例","地方市场监管局","2024-05-14","行政处罚/通报"]]],"固体废物污染环境防治法|第一百零五条":["第一百零五条 违反本法规定，生产经营者未遵守限制商品过度包装的强制性标准的，由县级以上地方人民政府市场监督管理部门或者有关部门责令改正；拒不改正的，处二千元以上二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款。","b34ee46684","中华人民共和国固体废物污染环境防治法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3MjljNjVkODAxNzI5ZDQ1NWZhZDA0YmU=",2,"已废止","2020-09-01",[["cr-f9c2b11d86","四川巴蜀好利食品有限公司未遵守限制商品过度包装的强制性标准且拒不改正案（泸市监罚【2026】4号）","泸州市市场监督管理局","2026-01-12","行政处罚信息公开表"],["cr-c884d918d5","泸州宁品润建筑材料有限公司销售以不合格产品冒充合格产品案（泸市监罚〔2026〕5号）","泸州市市场监督管理局","2025-01-13","行政处罚信息公开表"]]],"化妆品监督管理条例|第六十一条":["第六十一条 有下列情形之一的，由负责药品监督管理的部门没收违法所得、违法生产经营的化妆品，并可以没收专门用于违法生产经营的原料、包装材料、工具、设备等物品；违法生产经营的化妆品货值金额不足1万元的，并处1万元以上3万元以下罚款；货值金额1万元以上的，并处货值金额3倍以上10倍以下罚款；情节严重的，责令停产停业、由备案部门取消备案或者由原发证部门吊销化妆品许可证件，对违法单位的法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的1倍以上2倍以下罚款，5年内禁止其从事化妆品生产经营活动：\n（一）上市销售、经营或者进口未备案的普通化妆品；\n（二）未依照本条例规定设质量安全负责人；\n（三）化妆品注册人、备案人未对受托生产企业的生产活动进行监督；\n（四）未依照本条例规定建立并执行从业人员健康管理制度；\n（五）生产经营标签不符合本条例规定的化妆品。\n生产经营的化妆品的标签存在瑕疵但不影响质量安全且不会对消费者造成误导的，由负责药品监督管理的部门责令改正；拒不改正的，处2000元以下罚款。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",1,"现行有效","2021-01-01",[["cr-becde80b38","泸州市龙马潭区吴氏美容美发中心（宋屿江）经营未备案的普通化妆品、未取得药品经营许可证经营药品案（泸市监罚〔2026〕1号）","泸州市市场监督管理局","2026-01-04","行政处罚信息公开表"]]],"药品管理法|第一百一十五条":["第一百一十五条 未取得药品生产许可证、药品经营许可证或者医疗机构制剂许可证生产、销售药品的，责令关闭，没收违法生产、销售的药品和违法所得，并处违法生产、销售的药品（包括已售出和未售出的药品，下同）货值金额十五倍以上三十倍以下的罚款；货值金额不足十万元的，按十万元计算。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",1,"现行有效","2019-12-01",[["cr-becde80b38","泸州市龙马潭区吴氏美容美发中心（宋屿江）经营未备案的普通化妆品、未取得药品经营许可证经营药品案（泸市监罚〔2026〕1号）","泸州市市场监督管理局","2026-01-04","行政处罚信息公开表"]]],"食品安全法实施条例|第七十五条":["第七十五条 食品生产经营企业等单位有食品安全法规定的违法情形，除依照食品安全法的规定给予处罚外，有下列情形之一的，对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的1倍以上10倍以下罚款：\n(一)故意实施违法行为；\n(二)违法行为性质恶劣；\n(三)违法行为造成严重后果。\n属于食品安全法第一百二十五条第二款规定情形的，不适用前款规定。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",1,"现行有效","2019-12-01",[["cr-2223a26dfb","生产经营标签不符合规定的预包装食品案（粤市监广州办罚〔2025〕1220号）","广东省市场监督管理局","2025-12-29","行政处罚决定书"]]],"产品质量法|第五条":["第五条 禁止伪造或者冒用认证标志等质量标志；禁止伪造产品的产地，伪造或者冒用他人的厂名、厂址；禁止在生产、销售的产品中掺杂、掺假，以假充真，以次充好。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",1,"现行有效","2018-12-29",[["cr-aec4762011","市场监管总局公布儿童玩具产品 质量执法五起典型案例","市场监管总局","2025-12-04","行政处罚/通报"]]],"认证认可条例|第六十六条":["第六十六条 列入目录的产品未经认证，擅自出厂、销售、进口或者在其他经营活动中使用的，责令限期改正，处5万元以上20万元以下的罚款；未经认证的违法产品货值金额不足1万元的，处货值金额2倍以下的罚款；有违法所得的，没收违法所得。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",2,"现行有效","2023-07-20",[["cr-aec4762011","市场监管总局公布儿童玩具产品 质量执法五起典型案例","市场监管总局","2025-12-04","行政处罚/通报"],["cr-63d332ac3c","行政处罚决定书（粤市监广办罚〔2023〕003号）","广东省市场监督管理局","2023-12-08","行政处罚决定书"]]],"产品质量法|第五十三条":["第五十三条 伪造产品产地的，伪造或者冒用他人厂名、厂址的，伪造或者冒用认证标志等质量标志的，责令改正，没收违法生产、销售的产品，并处违法生产、销售产品货值金额等值以下的罚款；有违法所得的，并处没收违法所得；情节严重的，吊销营业执照。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",1,"现行有效","2018-12-29",[["cr-aec4762011","市场监管总局公布儿童玩具产品 质量执法五起典型案例","市场监管总局","2025-12-04","行政处罚/通报"]]],"食品安全法|第七十一条":["第七十一条食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。生产经营者对其提供的标签、说明书的内容负责。食品和食品添加剂的标签、说明书应当清楚、明显，生产日期、保质期等事项应当显著标注，容易辨识。食品和食品添加剂与其标签、说明书的内容不符的，不得上市销售。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",2,"现行有效","2025-12-01",[["cr-ce03af7695","重庆公布五起农村假冒伪劣食品典型违法案件","市场监管总局","2025-12-03","行政处罚/通报"],["cr-d1ae688d03","福建泉州公布2025年“守护消费”案件查办 铁拳行动典型案例","地方市场监管局","2025-06-25","行政处罚/通报"]]],"食品安全法|第一百三十五条":["第一百三十五条被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产经营许可，或者从事食品生产经营管理工作、担任食品生产经营企业食品安全管理人员。因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。食品生产经营者聘用人员违反前两款规定的，由县级以上人民政府食品安全监督管理部门吊销许可证。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",2,"现行有效","2025-12-01",[["cr-ce03af7695","重庆公布五起农村假冒伪劣食品典型违法案件","市场监管总局","2025-12-03","行政处罚/通报"],["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"反不正当竞争法|第十九条":["第十九条 监督检查部门及其工作人员对调查过程中知悉的商业秘密、个人隐私和个人信息依法负有保密义务。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",3,"现行有效","2025-10-15",[["cr-60efd2cab3","四川泸州泰宇科技有限公司商业贿赂案（泸市监罚〔2025〕21号）","泸州市市场监督管理局","2025-10-15","行政处罚信息公开表"],["cr-332630bafb","遂宁市炜东企业管理服务有限公司商业贿赂案（泸市监罚〔2025〕15号）","泸州市市场监督管理局","2025-07-07","行政处罚信息公开表"],["cr-c0b5c83a2c","万泽权商业贿赂案（泸市监罚〔2025〕17号）","泸州市市场监督管理局","2025-07-07","行政处罚信息公开表"]]],"化妆品监督管理条例|第五十九条":["第五十九条 有下列情形之一的，由负责药品监督管理的部门没收违法所得、违法生产经营的化妆品和专门用于违法生产经营的原料、包装材料、工具、设备等物品；违法生产经营的化妆品货值金额不足1万元的，并处5万元以上15万元以下罚款；货值金额1万元以上的，并处货值金额15倍以上30倍以下罚款；情节严重的，责令停产停业、由备案部门取消备案或者由原发证部门吊销化妆品许可证件，10年内不予办理其提出的化妆品备案或者受理其提出的化妆品行政许可申请，对违法单位的法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的3倍以上5倍以下罚款，终身禁止其从事化妆品生产经营活动；构成犯罪的，依法追究刑事责任：\n（一）未经许可从事化妆品生产活动，或者化妆品注册人、备案人委托未取得相应化妆品生产许可的企业生产化妆品；\n（二）生产经营或者进口未经注册的特殊化妆品；","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",1,"现行有效","2021-01-01",[["cr-a9e92fd6af","雷吉未经许可从事化妆品生产活动，对其商品的销售状况作虚假的商业宣传案（泸市监罚〔2025〕20号）","泸州市市场监督管理局","2025-09-29","行政处罚信息公开表"]]],"网络反不正当竞争暂行规定|第三十四条":["第三十四条 经营者违反本规定第八条、第九条的，由市场监督管理部门依照反不正当竞争法第二十条的规定处罚。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",1,"现行有效","2024-09-01",[["cr-a9e92fd6af","雷吉未经许可从事化妆品生产活动，对其商品的销售状况作虚假的商业宣传案（泸市监罚〔2025〕20号）","泸州市市场监督管理局","2025-09-29","行政处罚信息公开表"]]],"反不正当竞争法|第八条":["第八条 经营者不得采用给予财物或者其他手段贿赂下列单位或者个人，以谋取交易机会或者竞争优势：\n（一）交易相对方的工作人员；\n（二）受交易相对方委托办理相关事务的单位或者个人；\n（三）利用职权或者影响力影响交易的单位或者个人。\n前款规定的单位和个人不得收受贿赂。\n经营者在交易活动中，可以以明示方式向交易相对方支付折扣，或者向中间人支付佣金。经营者向交易相对方支付折扣、向中间人支付佣金的，应当如实入账。接受折扣、佣金的经营者也应当如实入账。\n经营者的工作人员进行贿赂的，应当认定为经营者的行为；但是，经营者有证据证明该工作人员的行为与为经营者谋取交易机会或者竞争优势无关的除外。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",4,"现行有效","2025-10-15",[["cr-c82b901d1e","老年人药品、保健品虚假宣传典型案例","无锡市市场监督管理局","2025-09-16","行政处罚决定书"],["cr-0afecadfef","上海发布一批2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-08-25","行政处罚/通报"],["cr-a08a8736fb","黑龙江省市场监管局公布2024年第一批 典型案例","地方市场监管局","2024-05-14","行政处罚/通报"],["cr-370590f28a","上海发布一批“铁拳”行动典型案例","地方市场监管局","2024-05-09","行政处罚/通报"]]],"山东省食品小作坊小餐饮和食品摊点管理条例|第八条":["第八条 食品小作坊、小餐饮和食品摊点从事生产经营，应当符合下列要求：\n（一）食品原料、食品添加剂符合食品安全标准和国家相关规定；\n（二）具有相应的防尘、防蝇、防鼠、防虫设备或者设施；\n（三）接触食品的包装材料无毒、清洁；\n（四）用水符合国家规定的生活饮用水卫生标准;\n（五）加工、贮存、运输、装卸和销售食品的容器、工具、设备安全、无害并保持清洁，符合食品安全所需特殊要求，不得将食品与有毒、有害物品一同贮存、运输；\n（六）按照国家标准和规定使用食品添加剂;\n（七）从业人员保持个人卫生，穿戴清洁的工作衣、帽等；\n（八）使用的洗涤剂、消毒剂对人体安全、无害；\n（九）生产经营场所清洁，与污染源保持安全、无害距离；\n（十）遵守城镇容貌和环境卫生管理等法律、法规、规章。\n食品小作坊、小餐饮和食品摊点从事生产经营，不得违反《中华人民共和国食品安全法》第三十四条的相关规定。","c6737d7ed7","山东省食品小作坊小餐饮和食品摊点管理条例","https://flk.npc.gov.cn/detail2.html?NDAyOGFiY2M2MTI3Nzc5MzAxNjEyODczYzc3ZjMxYmI=",1,"现行有效","2017-06-01",[["cr-c4083ad013","山东聊城发布“守护消费”铁拳行动典型案例","地方市场监管局","2025-09-03","行政处罚/通报"]]],"产品质量法|第三十二条":["第三十二条 生产者生产产品，不得掺杂、掺假，不得以假充真、以次充好，不得以不合格产品冒充合格产品。\n第二节 销售者的产品质量责任和义务","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",1,"现行有效","2018-12-29",[["cr-0afecadfef","上海发布一批2025“守护消费”铁拳行动典型案例","地方市场监管局","2025-08-25","行政处罚/通报"]]],"反垄断法|第十五条":["第十五条 本法所称经营者，是指从事商品生产、经营或者提供服务的自然人、法人和非法人组织。\n本法所称相关市场，是指经营者在一定时期内就特定商品或者服务（以下统称商品）进行竞争的商品范围和地域范围。\n第二章 垄断协议","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",1,"现行有效","2022-08-01",[["cr-bca9913f13","市场监管总局发布当涂县首创水务有限公司滥用市场支配地位案行政处罚决定书","市场监管总局","2025-08-20","行政处罚/通报"]]],"反垄断法|第十二条":["第十二条 国务院设立反垄断委员会，负责组织、协调、指导反垄断工作，履行下列职责：\n（一）研究拟订有关竞争政策；\n（二）组织调查、评估市场总体竞争状况，发布评估报告；\n（三）制定、发布反垄断指南；\n（四）协调反垄断行政执法工作；\n（五）国务院规定的其他职责。\n国务院反垄断委员会的组成和工作规则由国务院规定。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",1,"现行有效","2022-08-01",[["cr-c8632e4462","市场监管总局发布抚州公用水务有限公司滥用市场支配地位案行政处罚决定书","市场监管总局","2025-08-20","行政处罚/通报"]]],"化妆品监督管理条例|第三十九条":["第三十九条 化妆品生产经营者应当依照有关法律、法规的规定和化妆品标签标示的要求贮存、运输化妆品，定期检查并及时处理变质或者超过使用期限的化妆品。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",1,"现行有效","2021-01-01",[["cr-1922804117","济源“铁拳行动曝光台”强化执法震慑力","地方市场监管局","2025-08-06","行政处罚/通报"]]],"化妆品监督管理条例|第三十八条":["第三十八条 化妆品经营者应当建立并执行进货查验记录制度，查验供货者的市场主体登记证明、化妆品注册或者备案情况、产品出厂检验合格证明，如实记录并保存相关凭证。记录和凭证保存期限应当符合本条例第三十一条第一款的规定。\n化妆品经营者不得自行配制化妆品。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",1,"现行有效","2021-01-01",[["cr-1922804117","济源“铁拳行动曝光台”强化执法震慑力","地方市场监管局","2025-08-06","行政处罚/通报"]]],"行政处罚法|第三十三条":["第三十三条 违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。\n当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。\n对当事人的违法行为依法不予行政处罚的，行政机关应当对当事人进行教育。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",1,"现行有效","2021-07-15",[["cr-96372a3860","经营标签不符合规定的化妆品案","无锡市市场监督管理局","2025-06-19","行政处罚决定书"]]],"价格法|第三十九条":["第三十九条 经营者不执行政府指导价、政府定价以及法定的价格干预措施、紧急措施的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款；没有违法所得的，可以处以罚款；情节严重的，责令停业整顿。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",4,"现行有效","1998-05-01",[["cr-51459aafa2","严查收费乱象 规范市场秩序 江西通报一批电动自行车充电市场价格执法 典型案例","地方市场监管局","2025-06-18","行政处罚/通报"],["cr-225434fe70","古蔺县德馨殡葬服务有限公司不执行政府指导价、政府定价案（泸市监罚〔2025〕10号）","泸州市市场监督管理局","2025-05-21","行政处罚信息公开表"],["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"],["cr-827acbe8b8","贵州省市场监督管理局行政处罚信息公示表（2019-2020年环保电价案）","贵州省市场监督管理局","2021-08-16","行政处罚决定书"]]],"价格法|第十三条":["第十三条 经营者销售、收购商品和提供服务，应当按照政府价格主管部门的规定明码标价，注明商品的品名、产地、规格、等级、计价单位、价格或者服务的项目、收费标准等有关情况。\n经营者不得在标价之外加价出售商品，不得收取任何未予标明的费用。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",1,"现行有效","1998-05-01",[["cr-51459aafa2","严查收费乱象 规范市场秩序 江西通报一批电动自行车充电市场价格执法 典型案例","地方市场监管局","2025-06-18","行政处罚/通报"]]],"价格法|第四十二条":["第四十二条 经营者违反明码标价规定的，责令改正，没收违法所得，可以并处五千元以下的罚款。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",1,"现行有效","1998-05-01",[["cr-51459aafa2","严查收费乱象 规范市场秩序 江西通报一批电动自行车充电市场价格执法 典型案例","地方市场监管局","2025-06-18","行政处罚/通报"]]],"特种设备安全法|第八十四条":["第八十四条 违反本法规定，特种设备使用单位有下列行为之一的，责令停止使用有关特种设备，处三万元以上三十万元以下罚款：\n（一）使用未取得许可生产，未经检验或者检验不合格的特种设备，或者国家明令淘汰、已经报废的特种设备的；\n（二）特种设备出现故障或者发生异常情况，未对其进行全面检查、消除事故隐患，继续使用的；\n（三）特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件，未依法履行报废义务，并办理使用登记证书注销手续的。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",2,"现行有效","2014-01-01",[["cr-028f2b4aa5","四川佳途教育咨询有限公司使用未经检验的特种设备案（泸市监罚〔2025〕14号）","泸州市市场监督管理局","2025-06-05","行政处罚信息公开表"],["cr-078b5dd03c","泸县华油天然气有限公司使用未经定期检验的特种设备案（泸市监罚〔2025〕3号）","泸州市市场监督管理局","2025-03-14","行政处罚信息公开表"]]],"价格违法行为行政处罚规定|第十六条":["第十六条 本规定第四条至第十三条规定中的违法所得，属于价格法第四十一条规定的消费者或者其他经营者多付价款的，责令经营者限期退还。难以查找多付价款的消费者或者其他经营者的，责令公告查找。\n经营者拒不按照前款规定退还消费者或者其他经营者多付的价款，以及期限届满没有退还消费者或者其他经营者多付的价款，由政府价格主管部门予以没收，消费者或者其他经营者要求退还时，由经营者依法承担民事责任。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",1,"现行有效","2010-12-04",[["cr-225434fe70","古蔺县德馨殡葬服务有限公司不执行政府指导价、政府定价案（泸市监罚〔2025〕10号）","泸州市市场监督管理局","2025-05-21","行政处罚信息公开表"]]],"行政处罚法|第三十二条":["第三十二条 当事人有下列情形之一，应当从轻或者减轻行政处罚：\n（一）主动消除或者减轻违法行为危害后果的；\n（二）受他人胁迫或者诱骗实施违法行为的；\n（三）主动供述行政机关尚未掌握的违法行为的；\n（四）配合行政机关查处违法行为有立功表现的；\n（五）法律、法规、规章规定其他应当从轻或者减轻行政处罚的。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",1,"现行有效","2021-07-15",[["cr-813a8ce035","陕西省市场监管局2025“守护消费”铁拳行动第一批暨知识产权执法十大典型案例","地方市场监管局","2025-04-30","行政处罚/通报"]]],"行政处罚法|第二十七条":["第二十七条 违法行为涉嫌犯罪的，行政机关应当及时将案件移送司法机关，依法追究刑事责任。对依法不需要追究刑事责任或者免予刑事处罚，但应当给予行政处罚的，司法机关应当及时将案件移送有关行政机关。\n行政处罚实施机关与司法机关之间应当加强协调配合，建立健全案件移送制度，加强证据材料移交、接收衔接，完善案件处理信息通报机制。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",4,"现行有效","2021-07-15",[["cr-1617148b24","无锡市市场监管局公布2025“守护消费”铁拳行动（知识产权执法保护）典型案例","无锡市市场监督管理局","2025-04-29","行政处罚决定书"],["cr-bbb49c7eb9","内蒙古公布第十一批典型案例","公安部","2024-11-25","行政处罚/通报"],["cr-1f617f4f09","福建公布2024民生领域案件查办“铁拳”行动第三批典型案例","地方市场监管局","2024-09-02","行政处罚/通报"],["cr-cf31238fb2","山东公布第四批典型案例","公安部","2024-07-29","行政处罚/通报"]]],"烟草专卖法实施条例|第六条":["第六条 从事烟草专卖品的生产、批发、零售业务，以及经营烟草专卖品进出口业务和经营外国烟草制品购销业务的，必须依照《烟草专卖法》和本条例的规定，申请领取烟草专卖许可证。\n烟草专卖许可证分为：\n（一）烟草专卖生产企业许可证；\n（二）烟草专卖批发企业许可证；\n（三）烟草专卖零售许可证。","ea3b30cd6b","中华人民共和国烟草专卖法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3ZTcwOTIzMjU=",1,"现行有效","2023-07-20",[["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"]]],"烟草专卖法实施条例|第五十七条":["第五十七条 无烟草专卖零售许可证经营烟草制品零售业务的，由工商行政管理部门或者由工商行政管理部门根据烟草专卖行政主管部门的意见，责令停止经营烟草制品零售业务，没收违法所得，处以违法经营总额20%以上50%以下的罚款。","ea3b30cd6b","中华人民共和国烟草专卖法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3ZTcwOTIzMjU=",1,"现行有效","2023-07-20",[["cr-b46ee69346","2025青海省民生领域案件查办“铁拳”行动 典型案例（第一批）","地方市场监管局","2025-04-27","行政处罚/通报"]]],"医疗器械监督管理条例|第八十一条":["第八十一条 有下列情形之一的，由负责药品监督管理的部门没收违法所得、违法生产经营的医疗器械和用于违法生产经营的工具、设备、原材料等物品；违法生产经营的医疗器械货值金额不足1万元的，并处5万元以上15万元以下罚款；货值金额1万元以上的，并处货值金额15倍以上30倍以下罚款；情节严重的，责令停产停业，10年内不受理相关责任人以及单位提出的医疗器械许可申请，对违法单位的法定代表人、主要负责人、直接负责的主管人员和其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入30%以上3倍以下罚款，终身禁止其从事医疗器械生产经营活动：\n（一）生产、经营未取得医疗器械注册证的第二类、第三类医疗器械；\n（二）未经许可从事第二类、第三类医疗器械生产活动；\n（三）未经许可从事第三类医疗器械经营活动。\n有前款第一项情形、情节严重的，由原发证部门吊销医疗器械生产许可证或者医疗器械经营许可证。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",1,"现行有效","2025-01-20",[["cr-7520f05b00","泸州市千视眼镜有限公司未经许可从事第三类医疗器械经营活动案（泸市监罚〔2025〕5号）","泸州市市场监督管理局","2025-04-09","行政处罚信息公开表"]]],"消费者权益保护法实施条例|第二十二条":["第二十二条 经营者以收取预付款方式提供商品或者服务的，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式、违约责任等事项。经营者收取预付款后，应当按照与消费者的约定提供商品或者服务，不得降低商品或者服务质量，不得任意加价。经营者未按照约定提供商品或者服务的，应当按照消费者的要求履行约定或者退还预付款。经营者出现重大经营风险，有可能影响经营者按照合同约定或者交易习惯正常提供商品或者服务的，应当停止收取预付款。经营者决定停业或者迁移服务场所的，应当提前告知消费者，并履行本条例第二十一条规定的义务。消费者依照国家有关规定或者合同约定，有权要求经营者继续履行提供商品或者服务的义务，或者要求退还未消费的预付款余额。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",1,"现行有效","2024-07-01",[["cr-7594e321d4","安徽省市场监管局公布“守护消费”铁拳行动第一批典型案例","地方市场监管局","2025-03-19","行政处罚/通报"]]],"未成年人保护法|第一百二十三条":["第一百二十三条 相关经营者违反本法第五十八条、第五十九条第一款、第六十条规定的，由文化和旅游、市场监督管理、烟草专卖、公安等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处五万元以下罚款；拒不改正或者情节严重的，责令停业整顿或者吊销营业执照、吊销相关许可证，可以并处五万元以上五十万元以下罚款。","5b8f73e98c","中华人民共和国未成年人保护法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4ZjE5N2NmMDAxOTA1ZTU2N2FmNjM1YTA=",1,"现行有效","2024-04-26",[["cr-392c667c87","重大损害风险案","无锡市市场监督管理局","2025-03-17","行政处罚决定书"]]],"计量法|第十六条":["第十六条 使用计量器具不得破坏其准确度，损害国家和消费者的利益。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",3,"现行有效","1986-07-01",[["cr-a9d9dfbda2","新疆公布5件电子计价秤计量违法典型案例","地方市场监管局","2025-02-13","行政处罚/通报"],["cr-7ca3d491b2","陕西省市场监管局2024民生领域“铁拳”行动典型案例（第三批）","地方市场监管局","2024-05-23","行政处罚/通报"],["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"计量法|第二十七条":["第二十七条 制造、销售、使用以欺骗消费者为目的的计量器具的，没收计量器具和违法所得，处以罚款；情节严重的，并对个人或者单位直接责任人员依照刑法有关规定追究刑事责任。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",1,"现行有效","1986-07-01",[["cr-a9d9dfbda2","新疆公布5件电子计价秤计量违法典型案例","地方市场监管局","2025-02-13","行政处罚/通报"]]],"化妆品监督管理条例|第六十条":["第六十条 有下列情形之一的，由负责药品监督管理的部门没收违法所得、违法生产经营的化妆品和专门用于违法生产经营的原料、包装材料、工具、设备等物品；违法生产经营的化妆品货值金额不足1万元的，并处1万元以上5万元以下罚款；货值金额1万元以上的，并处货值金额5倍以上20倍以下罚款；情节严重的，责令停产停业、由备案部门取消备案或者由原发证部门吊销化妆品许可证件，对违法单位的法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的1倍以上3倍以下罚款，10年内禁止其从事化妆品生产经营活动；构成犯罪的，依法追究刑事责任：\n（一）使用不符合强制性国家标准、技术规范的原料、直接接触化妆品的包装材料，应当备案但未备案的新原料生产化妆品，或者不按照强制性国家标准或者技术规范使用原料；\n（二）生产经营不符合强制性国家标准、技术规范或者不符合化妆品注册、备案资料载明的技术要求的化妆品；\n（三）未按照化妆品生产质量管理规范的要求组织生产；\n（四）更改化妆品使用期限；\n（五）化妆品经营者擅自配制化妆品，或者经营变质、超过使用期限的化妆品；\n（六）在负责药品监督管理的部门责令其实施召回后拒不召回，或者在负责药品监督管理的部门责令停止或者暂停生产、经营后拒不停止或者暂停生产、经营。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",1,"现行有效","2021-01-01",[["cr-cd3217da64","泸州市纳溪区薛利红办公用品经营部经营不符合化妆品注册资料载明的技术要求的化妆品以及未依照《化妆品监督管理条例》建立并执行进货查验记录制度案（泸市监罚〔2024〕46号）","泸州市市场监督管理局","2024-12-18","行政处罚信息公开表"]]],"消费者权益保护法|第五十七条":["第五十七条 经营者违反本法规定提供商品或者服务，侵害消费者合法权益，构成犯罪的，依法追究刑事责任。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",1,"现行有效","2014-03-15",[["cr-bbb49c7eb9","内蒙古公布第十一批典型案例","公安部","2024-11-25","行政处罚/通报"]]],"行政执法机关移送涉嫌犯罪案件的规定|第三条":["第三条 行政执法机关在依法查处违法行为过程中，发现违法事实涉及的金额、违法事实的情节、违法事实造成的后果等，根据刑法关于破坏社会主义市场经济秩序罪、妨害社会管理秩序罪等罪的规定和最高人民法院、最高人民检察院关于破坏社会主义市场经济秩序罪、妨害社会管理秩序罪等罪的司法解释以及最高人民检察院、公安部关于经济犯罪案件的追诉标准等规定，涉嫌构成犯罪，依法需要追究刑事责任的，必须依照本规定向公安机关移送。\n知识产权领域的违法案件，行政执法机关根据调查收集的证据和查明的案件事实，认为存在犯罪的合理嫌疑，需要公安机关采取措施进一步获取证据以判断是否达到刑事案件立案追诉标准的，应当向公安机关移送。","8252272a56","行政执法机关移送涉嫌犯罪案件的规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1ZDRkODAxNzZkNzEyYzAzNDAzZTI=",3,"现行有效","2020-08-07",[["cr-bbb49c7eb9","内蒙古公布第十一批典型案例","公安部","2024-11-25","行政处罚/通报"],["cr-1f617f4f09","福建公布2024民生领域案件查办“铁拳”行动第三批典型案例","地方市场监管局","2024-09-02","行政处罚/通报"],["cr-cf31238fb2","山东公布第四批典型案例","公安部","2024-07-29","行政处罚/通报"]]],"公平竞争审查条例|第十条":["第十条 起草单位起草的政策措施，没有法律、行政法规依据或者未经国务院批准，不得含有下列影响生产经营成本的内容：\n（一）给予特定经营者税收优惠；\n（二）给予特定经营者选择性、差异化的财政奖励或者补贴；\n（三）给予特定经营者要素获取、行政事业性收费、政府性基金、社会保险费等方面的优惠；\n（四）其他影响生产经营成本的内容。","0167885062","公平竞争审查条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MDE0ZTk5YTAxOTAyNWI4Y2RkMjQ5ZmQ=",1,"现行有效","2024-08-01",[["cr-490bddcde7","公平竞争审查微课堂丨公平竞争审查典型案例","无锡市市场监督管理局","2024-11-13","行政处罚决定书"]]],"食品安全法|第六十五条":["第六十五条食用农产品销售者应当建立食用农产品进货查验记录制度，如实记录食用农产品的名称、数量、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于六个月。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",1,"现行有效","2025-12-01",[["cr-f30fcd274a","泸州市杰蒙商贸有限公司经营五氯酚酸钠超过食品安全标准限量的食品案（泸市监罚〔2024〕37号）","泸州市市场监督管理局","2024-11-11","行政处罚信息公开表"]]],"反不正当竞争法|第六条":["第六条 国家鼓励、支持和保护一切组织和个人对不正当竞争行为进行社会监督。\n国家机关及其工作人员不得支持、包庇不正当竞争行为。\n行业组织应当加强行业自律，引导、规范本行业的经营者依法竞争，维护市场竞争秩序。\n第二章 不正当竞争行为","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",2,"现行有效","2025-10-15",[["cr-fd67c070dd","护民生 保安全 反欺诈 各地相继公布一批民生领域案件查办 “铁拳”行动典型案例","地方市场监管局","2024-11-08","行政处罚/通报"],["cr-a01f4f7f82","其他足以引人误认为是他人商品或与他人存在特定联系的混淆案","广东省市场监督管理局","2020-05-11","行政处罚决定书"]]],"特种设备安全法|第九十三条":["第九十三条 违反本法规定，特种设备检验、检测机构及其检验、检测人员有下列行为之一的，责令改正，对机构处五万元以上二十万元以下罚款，对直接负责的主管人员和其他直接责任人员处五千元以上五万元以下罚款；情节严重的，吊销机构资质和有关人员的资格：\n（一）未经核准或者超出核准范围、使用未取得相应资格的人员从事检验、检测的；\n（二）未按照安全技术规范的要求进行检验、检测的；\n（三）出具虚假的检验、检测结果和鉴定结论或者检验、检测结果和鉴定结论严重失实的；\n（四）发现特种设备存在严重事故隐患，未及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告的；\n（五）泄露检验、检测过程中知悉的商业秘密的；\n（六）从事有关特种设备的生产、经营活动的；\n（七）推荐或者监制、监销特种设备的；\n（八）利用检验工作故意刁难相关单位的。\n违反本法规定，特种设备检验、检测机构的检验、检测人员同时在两个以上检验、检测机构中执业的，处五千元以上五万元以下罚款；情节严重的，吊销其资格。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-2bec6cdda1","泸州市恒安检验服务有限公司未按照安全技术规范的要求进行检验案（泸市监罚〔2024〕42号）","泸州市市场监督管理局","2024-11-08","行政处罚信息公开表"]]],"认证认可条例|第十七条":["第十七条 认证机构应当按照认证基本规范、认证规则从事认证活动。认证基本规范、认证规则由国务院认证认可监督管理部门制定；涉及国务院有关部门职责的，国务院认证认可监督管理部门应当会同国务院有关部门制定。\n属于认证新领域，前款规定的部门尚未制定认证规则的，认证机构可以自行制定认证规则，并报国务院认证认可监督管理部门备案。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-420b03de40","四川成都公布2024“铁拳”“春雷”行动 第三批典型案例","地方市场监管局","2024-10-11","行政处罚/通报"]]],"专利代理条例|第二十七条":["第二十七条 违反本条例规定擅自开展专利代理业务的，由省、自治区、直辖市人民政府管理专利工作的部门责令停止违法行为，没收违法所得，并处违法所得1倍以上5倍以下的罚款。","9dd31a1a1b","专利代理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOThiZDAxNmY0MjU5M2JiMzA1NDI=",2,"现行有效","2018-11-06",[["cr-9f30a6046d","专利代理管理办法》第五十二条第二项“有下列案（粤市监广办罚〔2024〕008号）","广东省市场监督管理局","2024-09-26","行政处罚决定书"],["cr-282dceb232","专利代理管理办法》第五十二条第(二)项“有下列案（黔市监知罚字〔2022〕1号）","贵州省市场监督管理局","2022-03-28","行政处罚决定书"]]],"专利代理条例|第九条":["第九条 从事专利代理业务，应当向国务院专利行政部门提出申请，提交有关材料，取得专利代理机构执业许可证。国务院专利行政部门应当自受理申请之日起20日内作出是否颁发专利代理机构执业许可证的决定。\n专利代理机构合伙人、股东或者法定代表人等事项发生变化的，应当办理变更手续。","9dd31a1a1b","专利代理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOThiZDAxNmY0MjU5M2JiMzA1NDI=",1,"现行有效","2018-11-06",[["cr-9f30a6046d","专利代理管理办法》第五十二条第二项“有下列案（粤市监广办罚〔2024〕008号）","广东省市场监督管理局","2024-09-26","行政处罚决定书"]]],"商标法|第六十一条":["第六十一条 违反本法第八条规定的，由负责商标执法的部门责令限期申请注册，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",1,"即将实施","2027-01-01",[["cr-1f617f4f09","福建公布2024民生领域案件查办“铁拳”行动第三批典型案例","地方市场监管局","2024-09-02","行政处罚/通报"]]],"特种设备安全法|第八十二条":["第八十二条 违反本法规定，特种设备经营单位有下列行为之一的，责令停止经营，没收违法经营的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得：\n（一）销售、出租未取得许可生产，未经检验或者检验不合格的特种设备的；\n（二）销售、出租国家明令淘汰、已经报废的特种设备，或者未按照安全技术规范的要求进行维护保养的特种设备的。\n违反本法规定，特种设备销售单位未建立检查验收和销售记录制度，或者进口特种设备未履行提前告知义务的，责令改正，处一万元以上十万元以下罚款。\n特种设备生产单位销售、交付未经检验或者检验不合格的特种设备的，依照本条第一款规定处罚；情节严重的，吊销生产许可证。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-0b1649d8cb","销售未经监督检验的压力容器案（粤市监深办罚〔2024〕9号）","广东省市场监督管理局","2024-08-12","行政处罚决定书"]]],"特种设备安全法|第四十九条":["第四十九条 移动式压力容器、气瓶充装单位，应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事充装活动：\n（一）有与充装和管理相适应的管理人员和技术人员；\n（二）有与充装和管理相适应的充装设备、检测手段、场地厂房、器具、安全设施；\n（三）有健全的充装管理制度、责任制度、处理措施。\n充装单位应当建立充装前后的检查、记录制度，禁止对不符合安全技术规范要求的移动式压力容器和气瓶进行充装。\n气瓶充装单位应当向气体使用者提供符合安全技术规范要求的气瓶，对气体使用者进行气瓶安全使用指导，并按照安全技术规范的要求办理气瓶使用登记，及时申报定期检验。\n第三章 检验、检测","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",4,"现行有效","2014-01-01",[["cr-7960771530","行政处罚决定书（粤市监西办罚〔2024〕002号）","广东省市场监督管理局","2024-06-11","行政处罚决定书"],["cr-95fe70bcb1","青岛市市场监督管理局公布2024民生领域 案件查办“铁拳”行动典型案例（第一批）","地方市场监管局","2024-04-16","行政处罚/通报"],["cr-80ee320d89","行政处罚决定书（粤市监西办罚〔2024〕001号）","广东省市场监督管理局","2024-04-07","行政处罚决定书"],["cr-e38f2ff879","行政处罚决定书（粤市监西办罚〔2023〕006号）","广东省市场监督管理局","2023-10-24","行政处罚决定书"]]],"特种设备安全法|第八十五条":["第八十五条 违反本法规定，移动式压力容器、气瓶充装单位有下列行为之一的，责令改正，处二万元以上二十万元以下罚款；情节严重的，吊销充装许可证：\n（一）未按照规定实施充装前后的检查、记录制度的；\n（二）对不符合安全技术规范要求的移动式压力容器和气瓶进行充装的。\n违反本法规定，未经许可，擅自从事移动式压力容器或者气瓶充装活动的，予以取缔，没收违法充装的气瓶，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",4,"现行有效","2014-01-01",[["cr-7960771530","行政处罚决定书（粤市监西办罚〔2024〕002号）","广东省市场监督管理局","2024-06-11","行政处罚决定书"],["cr-95fe70bcb1","青岛市市场监督管理局公布2024民生领域 案件查办“铁拳”行动典型案例（第一批）","地方市场监管局","2024-04-16","行政处罚/通报"],["cr-80ee320d89","行政处罚决定书（粤市监西办罚〔2024〕001号）","广东省市场监督管理局","2024-04-07","行政处罚决定书"],["cr-c993ab99d2","未按照规定实施充装前后检查、记录制度案（黔市监特处〔2022〕1号）","贵州省市场监督管理局","2022-08-23","行政处罚决定书"]]],"价格法|第十四条":["第十四条 经营者不得有下列不正当价格行为：\n（一）相互串通，操纵市场价格，损害其他经营者或者消费者的合法权益；\n（二）在依法降价处理鲜活商品、季节性商品、积压商品等商品外，为了排挤竞争对手或者独占市场，以低于成本的价格倾销，扰乱正常的生产经营秩序，损害国家利益或者其他经营者的合法权益；\n（三）捏造、散布涨价信息，哄抬价格，推动商品价格过高上涨的；\n（四）利用虚假的或者使人误解的价格手段，诱骗消费者或者其他经营者与其进行交易；\n（五）提供相同商品或者服务，对具有同等交易条件的其他经营者实行价格歧视；\n（六）采取抬高等级或者压低等级等手段收购、销售商品或者提供服务，变相提高或者压低价格；\n（七）违反法律、法规的规定牟取暴利；\n（八）法律、行政法规禁止的其他不正当价格行为。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",3,"现行有效","1998-05-01",[["cr-7ca3d491b2","陕西省市场监管局2024民生领域“铁拳”行动典型案例（第三批）","地方市场监管局","2024-05-23","行政处罚/通报"],["cr-429e94272a","河北省市场监督管理局2024年第一批民生 领域“铁拳”行动典型案例","地方市场监管局","2024-04-18","行政处罚/通报"],["cr-d224dbfa3f","广东省市场监管领域防控新型冠状病毒肺炎疫情工作领导小组办公室发布第一批价格违法典型案例","广东省市场监督管理局","2020-01-29","行政处罚决定书"]]],"计量法|第二十六条":["第二十六条 使用不合格的计量器具或者破坏计量器具准确度，给国家和消费者造成损失的，责令赔偿损失，没收计量器具和违法所得，可以并处罚款。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",2,"现行有效","1986-07-01",[["cr-7ca3d491b2","陕西省市场监管局2024民生领域“铁拳”行动典型案例（第三批）","地方市场监管局","2024-05-23","行政处罚/通报"],["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"价格法|第四十条":["第四十条 经营者有本法第十四条所列行为之一的，责令改正，没收违法所得，可以并处违法所得五倍以下的罚款；没有违法所得的，予以警告，可以并处罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。有关法律对本法第十四条所列行为的处罚及处罚机关另有规定的，可以依照有关法律的规定执行。\n有本法第十四条第（一）项、第（二）项所列行为，属于是全国性的，由国务院价格主管部门认定；属于是省及省以下区域性的，由省、自治区、直辖市人民政府价格主管部门认定。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",2,"现行有效","1998-05-01",[["cr-7ca3d491b2","陕西省市场监管局2024民生领域“铁拳”行动典型案例（第三批）","地方市场监管局","2024-05-23","行政处罚/通报"],["cr-429e94272a","河北省市场监督管理局2024年第一批民生 领域“铁拳”行动典型案例","地方市场监管局","2024-04-18","行政处罚/通报"]]],"价格违法行为行政处罚规定|第七条":["第七条 经营者违反价格法第十四条的规定，利用虚假的或者使人误解的价格手段，诱骗消费者或者其他经营者与其进行交易的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",2,"现行有效","2010-12-04",[["cr-7ca3d491b2","陕西省市场监管局2024民生领域“铁拳”行动典型案例（第三批）","地方市场监管局","2024-05-23","行政处罚/通报"],["cr-429e94272a","河北省市场监督管理局2024年第一批民生 领域“铁拳”行动典型案例","地方市场监管局","2024-04-18","行政处罚/通报"]]],"商标法实施条例|第七十八条":["第七十八条 计算商标法第六十条规定的违法经营额，可以考虑下列因素：\n(一)侵权商品的销售价格；\n(二)未销售侵权商品的标价；\n(三)已查清侵权商品实际销售的平均价格；\n(四)被侵权商品的市场中间价格；\n(五)侵权人因侵权所产生的营业收入；\n(六)其他能够合理计算侵权商品价值的因素。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",1,"现行有效","2014-04-29",[["cr-c777844d03","山东省青岛市市场监督管理局公布 2024民生领域案件查办“铁拳”行动典型案例（第二批）","地方市场监管局","2024-05-22","行政处罚/通报"]]],"药品管理法|第二十四条":["第二十四条 在中国境内上市的药品，应当经国务院药品监督管理部门批准，取得药品注册证书；但是，未实施审批管理的中药材和中药饮片除外。实施审批管理的中药材、中药饮片品种目录由国务院药品监督管理部门会同国务院中医药主管部门制定。\n申请药品注册，应当提供真实、充分、可靠的数据、资料和样品，证明药品的安全性、有效性和质量可控性。\n国务院药品监督管理部门在审批药品时，对化学原料药一并审评审批，对相关辅料、直接接触药品的包装材料和容器一并审评，对药品的质量标准、生产工艺、标签和说明书一并核准。\n本法所称辅料，是指生产药品和调配处方时所用的赋形剂和附加剂。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",1,"现行有效","2019-12-01",[["cr-fcbf44700d","四川成都公布2024“铁拳”“春雷”行动 第二批典型案例","地方市场监管局","2024-05-21","行政处罚/通报"]]],"计量法实施细则|第四十六条":["第四十六条 使用不合格计量器具或者破坏计量器具准确度和伪造数据，给国家和消费者造成损失的，责令其赔偿损失，没收计量器具和全部违法所得，可并处2000元以下的罚款。","86bedb2509","中华人民共和国计量法实施细则","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MGUwYTQ0MTAxODExZTQ1YzBlYzE0YmE=",1,"现行有效","2022-05-01",[["cr-2b2d88dfea","河北省市场监督管理局公布 2024年第二批民生领域“铁拳”行动典型案例","地方市场监管局","2024-05-15","行政处罚/通报"]]],"上海市反不正当竞争条例|第十一条":["第十一条 公用企业或者其他依法具有独占地位的经营者，不得采取下列限制竞争的行为：\n（一）限定消费者购买、使用其提供的或者其指定的经营者提供的商品，排斥经过法定机构检验、符合技术标准要求的其他经营者的同类商品；\n（二）强制消费者购买其提供的或者其指定的经营者提供的不必要的商品或者配件；\n（三）对抵制上述各项行为的消费者拒绝、中断、拖延、削减提供必要的商品或者滥收费用。","50e260bb66","上海市反不正当竞争条例","https://flk.npc.gov.cn/detail2.html?NDAyOGFiY2M2MTI3Nzc5MzAxNjEyODViODQzMTFhZDg=",1,"现行有效","",[["cr-370590f28a","上海发布一批“铁拳”行动典型案例","地方市场监管局","2024-05-09","行政处罚/通报"]]],"认证认可条例|第二十一条":["第二十一条 认证机构以及与认证有关的检查机构、实验室从事认证以及与认证有关的检查、检测活动，应当完成认证基本规范、认证规则规定的程序，确保认证、检查、检测的完整、客观、真实，不得增加、减少、遗漏程序。\n认证机构以及与认证有关的检查机构、实验室应当对认证、检查、检测过程作出完整记录，归档留存。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-f0d716a72c","广州市市场监督管理局公布2024民生领域 案件查办“铁拳”行动第一批典型案例","地方市场监管局","2024-04-30","行政处罚/通报"]]],"认证认可条例|第五十九条":["第五十九条 认证机构有下列情形之一的，责令改正，处5万元以上20万元以下的罚款，有违法所得的，没收违法所得；情节严重的，责令停业整顿，直至撤销批准文件，并予公布：\n（一）超出批准范围从事认证活动的；\n（二）增加、减少、遗漏认证基本规范、认证规则规定的程序的；\n（三）未对其认证的产品、服务、管理体系实施有效的跟踪调查，或者发现其认证的产品、服务、管理体系不能持续符合认证要求，不及时暂停其使用或者撤销认证证书并予公布的；\n（四）聘用未经认可机构注册的人员从事认证活动的。\n与认证有关的检查机构、实验室增加、减少、遗漏认证基本规范、认证规则规定的程序的，依照前款规定处罚。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-f0d716a72c","广州市市场监督管理局公布2024民生领域 案件查办“铁拳”行动第一批典型案例","地方市场监管局","2024-04-30","行政处罚/通报"]]],"认证认可条例|第二十条":["第二十条 认证机构应当公开认证基本规范、认证规则、收费标准等信息。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-f0d716a72c","广州市市场监督管理局公布2024民生领域 案件查办“铁拳”行动第一批典型案例","地方市场监管局","2024-04-30","行政处罚/通报"]]],"认证认可条例|第六十条":["第六十条 认证机构有下列情形之一的，责令限期改正；逾期未改正的，处2万元以上10万元以下的罚款：\n（一）以委托人未参加认证咨询或者认证培训等为理由，拒绝提供本认证机构业务范围内的认证服务，或者向委托人提出与认证活动无关的要求或者限制条件的；\n（二）自行制定的认证标志的式样、文字和名称，与国家推行的认证标志相同或者近似，或者妨碍社会管理，或者有损社会道德风尚的；\n（三）未公开认证基本规范、认证规则、收费标准等信息的；\n（四）未对认证过程作出完整记录，归档留存的；\n（五）未及时向其认证的委托人出具认证证书的。\n与认证有关的检查机构、实验室未对与认证有关的检查、检测过程作出完整记录，归档留存的，依照前款规定处罚。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-f0d716a72c","广州市市场监督管理局公布2024民生领域 案件查办“铁拳”行动第一批典型案例","地方市场监管局","2024-04-30","行政处罚/通报"]]],"计量法|第二十五条":["第二十五条 属于强制检定范围的计量器具，未按照规定申请检定或者检定不合格继续使用的，责令停止使用，可以并处罚款。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",1,"现行有效","1986-07-01",[["cr-f4e6a2bb90","合肥公布2024民生领域案件查办“铁拳”行动 第三批典型案例","地方市场监管局","2024-04-29","行政处罚/通报"]]],"计量法实施细则|第四十三条":["第四十三条 属于强制检定范围的计量器具，未按照规定申请检定和属于非强制检定范围的计量器具未自行定期检定或者送其他计量检定机构定期检定的，以及经检定不合格继续使用的，责令其停止使用，可并处1000元以下的罚款。","86bedb2509","中华人民共和国计量法实施细则","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MGUwYTQ0MTAxODExZTQ1YzBlYzE0YmE=",1,"现行有效","2022-05-01",[["cr-f4e6a2bb90","合肥公布2024民生领域案件查办“铁拳”行动 第三批典型案例","地方市场监管局","2024-04-29","行政处罚/通报"]]],"计量法|第九条":["第九条 县级以上人民政府计量行政部门对社会公用计量标准器具，部门和企业、事业单位使用的最高计量标准器具，以及用于贸易结算、安全防护、医疗卫生、环境监测方面的列入强制检定目录的工作计量器具，实行强制检定。未按照规定申请检定或者检定不合格的，不得使用。实行强制检定的工作计量器具的目录和管理办法，由国务院制定。对前款规定以外的其他计量标准器具和工作计量器具，使用单位应当自行定期检定或者送其他计量检定机构检定。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",1,"现行有效","1986-07-01",[["cr-f4e6a2bb90","合肥公布2024民生领域案件查办“铁拳”行动 第三批典型案例","地方市场监管局","2024-04-29","行政处罚/通报"]]],"计量法实施细则|第二十二条":["第二十二条 任何单位和个人不准在工作岗位上使用无检定合格印、证或者超过检定周期以及经检定不合格的计量器具。在教学示范中使用计量器具不受此限。\n第六章 计量监督","86bedb2509","中华人民共和国计量法实施细则","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MGUwYTQ0MTAxODExZTQ1YzBlYzE0YmE=",1,"现行有效","2022-05-01",[["cr-f4e6a2bb90","合肥公布2024民生领域案件查办“铁拳”行动 第三批典型案例","地方市场监管局","2024-04-29","行政处罚/通报"]]],"认证认可条例|第九条":["第九条 取得认证机构资质，应当经国务院认证认可监督管理部门批准，并在批准范围内从事认证活动。\n未经批准，任何单位和个人不得从事认证活动。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",1,"现行有效","2023-07-20",[["cr-84f7df0ed4","上海公布2024“铁拳”行动第一批典型案例","地方市场监管局","2024-04-22","行政处罚/通报"]]],"消费者权益保护法|第五十六条":["第五十六条 经营者有下列情形之一，除承担相应的民事责任外，其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由工商行政管理部门或者其他有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得一倍以上十倍以下的罚款，没有违法所得的，处以五十万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照：\n（一）提供的商品或者服务不符合保障人身、财产安全要求的；\n（二）在商品中掺杂、掺假，以假充真，以次充好，或者以不合格商品冒充合格商品的；\n（三）生产国家明令淘汰的商品或者销售失效、变质的商品的；\n（四）伪造商品的产地，伪造或者冒用他人的厂名、厂址，篡改生产日期，伪造或者冒用认证标志等质量标志的；\n（五）销售的商品应当检验、检疫而未检验、检疫或者伪造检验、检疫结果的；\n（六）对商品或者服务作虚假或者引人误解的宣传的；\n（七）拒绝或者拖延有关行政部门责令对缺陷商品或者服务采取停止销售、警示、召回、无害化处理、销毁、停止生产或者服务等措施的；\n（八）对消费者提出的修理、重作、更换、退货、补足商品数量、退还货款和服务费用或者赔偿损失的要求，故意拖延或者无理拒绝的；\n（九）侵害消费者人格尊严、侵犯消费者人身自由或者侵害消费者个人信息依法得到保护的权利的；\n（十）法律、法规规定的对损害消费者权益应当予以处罚的其他情形。\n经营者有前款规定情形的，除依照法律、法规规定予以处罚外，处罚机关应当记入信用档案，向社会公布。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",1,"现行有效","2014-03-15",[["cr-429e94272a","河北省市场监督管理局2024年第一批民生 领域“铁拳”行动典型案例","地方市场监管局","2024-04-18","行政处罚/通报"]]],"特种设备安全法|第五十三条":["第五十三条 特种设备检验、检测机构及其检验、检测人员应当客观、公正、及时地出具检验、检测报告，并对检验、检测结果和鉴定结论负责。\n特种设备检验、检测机构及其检验、检测人员在检验、检测中发现特种设备存在严重事故隐患时，应当及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告。\n负责特种设备安全监督管理的部门应当组织对特种设备检验、检测机构的检验、检测结果和鉴定结论进行监督抽查，但应当防止重复抽查。监督抽查结果应当向社会公布。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-2d1f09f351","出具虚假检验结果案（粤市监西办罚〔2023〕003号）","广东省市场监督管理局","2023-10-24","行政处罚决定书"]]],"特种设备安全法|第五十二条":["第五十二条 特种设备检验、检测工作应当遵守法律、行政法规的规定，并按照安全技术规范的要求进行。\n特种设备检验、检测机构及其检验、检测人员应当依法为特种设备生产、经营、使用单位提供安全、可靠、便捷、诚信的检验、检测服务。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-2d1f09f351","出具虚假检验结果案（粤市监西办罚〔2023〕003号）","广东省市场监督管理局","2023-10-24","行政处罚决定书"]]],"行政处罚法|第六十七条":["第六十七条 作出罚款决定的行政机关应当与收缴罚款的机构分离。\n除依照本法第六十八条、第六十九条的规定当场收缴的罚款外，作出行政处罚决定的行政机关及其执法人员不得自行收缴罚款。\n当事人应当自收到行政处罚决定书之日起十五日内，到指定的银行或者通过电子支付系统缴纳罚款。银行应当收受罚款，并将罚款直接上缴国库。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",1,"现行有效","2021-07-15",[["cr-c993ab99d2","未按照规定实施充装前后检查、记录制度案（黔市监特处〔2022〕1号）","贵州省市场监督管理局","2022-08-23","行政处罚决定书"]]],"行政处罚法|第四十六条":["第四十六条 证据包括：\n（一）书证；\n（二）物证；\n（三）视听资料；\n（四）电子数据；\n（五）证人证言；\n（六）当事人的陈述；\n（七）鉴定意见；\n（八）勘验笔录、现场笔录。\n证据必须经查证属实，方可作为认定案件事实的根据。\n以非法手段取得的证据，不得作为认定案件事实的根据。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",1,"现行有效","2021-07-15",[["cr-282dceb232","专利代理管理办法》第五十二条第(二)项“有下列案（黔市监知罚字〔2022〕1号）","贵州省市场监督管理局","2022-03-28","行政处罚决定书"]]],"行政处罚法|第五十一条":["第五十一条 违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。法律另有规定的，从其规定。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",1,"现行有效","2021-07-15",[["cr-282dceb232","专利代理管理办法》第五十二条第(二)项“有下列案（黔市监知罚字〔2022〕1号）","贵州省市场监督管理局","2022-03-28","行政处罚决定书"]]],"行政强制法|第四十五条":["第四十五条 行政机关依法作出金钱给付义务的行政决定，当事人逾期不履行的，行政机关可以依法加处罚款或者滞纳金。加处罚款或者滞纳金的标准应当告知当事人。\n加处罚款或者滞纳金的数额不得超出金钱给付义务的数额。","65080ea4ea","中华人民共和国行政强制法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3MmY3YTA2MTM=",1,"现行有效","2012-01-01",[["cr-282dceb232","专利代理管理办法》第五十二条第(二)项“有下列案（黔市监知罚字〔2022〕1号）","贵州省市场监督管理局","2022-03-28","行政处罚决定书"]]],"反不正当竞争法|第十条":["第十条 经营者不得实施下列侵犯商业秘密的行为：\n（一）以盗窃、贿赂、欺诈、胁迫、电子侵入或者其他不正当手段获取权利人的商业秘密；\n（二）披露、使用或者允许他人使用以前项手段获取的权利人的商业秘密；\n（三）违反保密义务或者违反权利人有关保守商业秘密的要求，披露、使用或者允许他人使用其所掌握的商业秘密；\n（四）教唆、引诱、帮助他人违反保密义务或者违反权利人有关保守商业秘密的要求，获取、披露、使用或者允许他人使用权利人的商业秘密。\n经营者以外的其他自然人、法人和非法人组织实施前款所列违法行为的，视为侵犯商业秘密。\n第三人明知或者应知商业秘密权利人的员工、前员工或者其他单位、个人实施本条第一款所列违法行为，仍获取、披露、使用或者允许他人使用该商业秘密的，视为侵犯商业秘密。\n本法所称的商业秘密，是指不为公众所知悉、具有商业价值并经权利人采取相应保密措施的技术信息、经营信息等商业信息。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",1,"现行有效","2025-10-15",[["cr-1eec15e28b","不正当有奖销售案","广东省市场监督管理局","2021-08-06","行政处罚决定书"]]],"反不正当竞争法|第二十二条":["第二十二条 经营者违反本法规定，给他人造成损害的，应当依法承担民事责任。\n经营者的合法权益受到不正当竞争行为损害的，可以向人民法院提起诉讼。\n因不正当竞争行为受到损害的经营者的赔偿数额，按照其因被侵权所受到的实际损失或者侵权人因侵权所获得的利益确定。经营者故意实施侵犯商业秘密行为，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下确定赔偿数额。赔偿数额还应当包括经营者为制止侵权行为所支付的合理开支。\n经营者违反本法第七条、第十条规定，权利人因被侵权所受到的实际损失、侵权人因侵权所获得的利益难以确定的，由人民法院根据侵权行为的情节判决给予权利人五百万元以下的赔偿。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",1,"现行有效","2025-10-15",[["cr-1eec15e28b","不正当有奖销售案","广东省市场监督管理局","2021-08-06","行政处罚决定书"]]],"产品质量法|第三十五条":["第三十五条 销售者不得销售国家明令淘汰并停止销售的产品和失效、变质的产品。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",1,"现行有效","2018-12-29",[["cr-d224dbfa3f","广东省市场监管领域防控新型冠状病毒肺炎疫情工作领导小组办公室发布第一批价格违法典型案例","广东省市场监督管理局","2020-01-29","行政处罚决定书"]]],"特种设备安全法|第五十五条":["第五十五条 特种设备检验、检测机构及其检验、检测人员对检验、检测过程中知悉的商业秘密，负有保密义务。\n特种设备检验、检测机构及其检验、检测人员不得从事有关特种设备的生产、经营活动，不得推荐或者监制、监销特种设备。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",1,"现行有效","2014-01-01",[["cr-30e1cf2f8b","贵州省市场监督管理局行政处罚决定书（黔市监特罚〔2019〕1号）","贵州省市场监督管理局","2019-07-16","行政处罚决定书"]]],"江苏省知识产权促进和保护条例|第四十五条":["第四十五条 从事专利代理业务应当取得国家规定的资质，并依法登记注册。\n专利代理机构接受委托后，不得就同一专利申请或者专利权的事务接受有利益冲突的其他当事人的委托。专利代理机构指派的专利代理师本人及其近亲属不得与其承办的专利代理业务有利益冲突。专利代理师应当根据专利代理机构的指派承办专利代理业务，不得自行接受委托。\n专利代理机构和专利代理师对其在执业过程中了解的发明创造的内容，除专利申请已经公布或者公告的以外，负有保守秘密的义务。","358ef5b512","江苏省知识产权促进和保护条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3ZTliMWVjODAxN2VmYjVlNzYzNjY4Zjg=",1,"现行有效","2022-04-26",[["cr-a0923add7d","未经许可代理专利申请（锡市监处罚〔2026〕4号）","无锡市市场监督管理局","","行政处罚信息公开表"]]],"江苏省知识产权促进和保护条例|第六十四条":["第六十四条 违反本条例第四十五条第一款规定，未取得国家规定的资质从事专利代理业务的，责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款。\n违反本条例第四十五条第二款、第三款规定，专利代理机构就同一专利申请或者专利权的事务接受有利益冲突的其他当事人的委托，指派专利代理师承办与其本人或者其近亲属有利益冲突的专利代理业务，或者泄露委托人的发明创造内容的，责令限期改正，予以警告，可以处十万元以下的罚款；情节严重或者逾期未改正的，提请国务院专利行政部门依法处理。\n违反本条例第四十五条第二款、第三款规定，专利代理师自行接受委托办理专利代理业务，或者泄露委托人的发明创造内容的，责令限期改正，予以警告，可以处五万元以下的罚款；情节严重或者逾期未改正的，提请国务院专利行政部门依法处理。\n专利侵权纠纷经行政裁决、司法判决后，侵权人再次侵犯同一专利权的，责令侵权人停止侵权，没收违法所得，并可以处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处二十万元以下的罚款。\n本条规定的行政处罚，由省、设区的市知识产权部门具体实施。","358ef5b512","江苏省知识产权促进和保护条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3ZTliMWVjODAxN2VmYjVlNzYzNjY4Zjg=",1,"现行有效","2022-04-26",[["cr-a0923add7d","未经许可代理专利申请（锡市监处罚〔2026〕4号）","无锡市市场监督管理局","","行政处罚信息公开表"]]],"专利法|第十一条":["第十一条 发明和实用新型专利权被授予后，除本法另有规定的以外，任何单位或者个人未经专利权人许可，都不得实施其专利，即不得为生产经营目的制造、使用、许诺销售、销售、进口其专利产品，或者使用其专利方法以及使用、许诺销售、销售、进口依照该专利方法直接获得的产品。\n外观设计专利权被授予后，任何单位或者个人未经专利权人许可，都不得实施其专利，即不得为生产经营目的制造、许诺销售、销售、进口其外观设计专利产品。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法实施细则|第七十九条":["第七十九条 专利法第四十二条第二款规定的由申请人引起的不合理延迟包括以下情形：\n（一）未在指定期限内答复国务院专利行政部门发出的通知；\n（二）申请延迟审查；\n（三）因本细则第四十五条规定情形引起的延迟；\n（四）其他由申请人引起的不合理延迟。","84bdd82592","中华人民共和国专利法实施细则","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4ZDczNmRhZTAxOGRjNTE4MmYzMDZjMTQ=",0,"现行有效","2024-01-20",[]],"个人信息保护法|第六十六条":["第六十六条 违反本法规定处理个人信息，或者处理个人信息未履行本法规定的个人信息保护义务的，由履行个人信息保护职责的部门责令改正，给予警告，没收违法所得，对违法处理个人信息的应用程序，责令暂停或者终止提供服务；拒不改正的，并处一百万元以下罚款；对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。有前款规定的违法行为，情节严重的，由省级以上履行个人信息保护职责的部门责令改正，没收违法所得，并处五千万元以下或者上一年度营业额百分之五以下罚款，并可以责令暂停相关业务或者停业整顿、通报有关主管部门吊销相关业务许可或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处十万元以上一百万元以下罚款，并可以决定禁止其在一定期限内担任相关企业的董事、监事、高级管理人员和个人信息保护负责人。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第十七条":["第十七条 个人信息处理者在处理个人信息前，应当以显著方式、清晰易懂的语言真实、准确、完整地向个人告知下列事项：\n（一）个人信息处理者的名称或者姓名和联系方式；\n（二）个人信息的处理目的、处理方式，处理的个人信息种类、保存期限；\n（三）个人行使本法规定权利的方式和程序；\n（四）法律、行政法规规定应当告知的其他事项。前款规定事项发生变更的，应当将变更部分告知个人。个人信息处理者通过制定个人信息处理规则的方式告知第一款规定事项的，处理规则应当公开，并且便于查阅和保存。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第五十一条":["第五十一条 个人信息处理者应当根据个人信息的处理目的、处理方式、个人信息的种类以及对个人权益的影响、可能存在的安全风险等，采取下列措施确保个人信息处理活动符合法律、行政法规的规定，并防止未经授权的访问以及个人信息泄露、篡改、丢失：\n（一）制定内部管理制度和操作规程；\n（二）对个人信息实行分类管理；\n（三）采取相应的加密、去标识化等安全技术措施；\n（四）合理确定个人信息处理的操作权限，并定期对从业人员进行安全教育和培训；\n（五）制定并组织实施个人信息安全事件应急预案；\n（六）法律、行政法规规定的其他措施。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"网络安全法|第二十一条":["第二十一条 国家实行网络安全等级保护制度。网络运营者应当按照网络安全等级保护制度的要求，履行下列安全保护义务，保障网络免受干扰、破坏或者未经授权的访问，防止网络数据泄露或者被窃取、篡改：\n（一）制定内部安全管理制度和操作规程，确定网络安全负责人，落实网络安全保护责任；\n（二）采取防范计算机病毒和网络攻击、网络侵入等危害网络安全行为的技术措施；\n（三）采取监测、记录网络运行状态、网络安全事件的技术措施，并按照规定留存相关的网络日志不少于六个月；\n（四）采取数据分类、重要数据备份和加密等措施；\n（五）法律、行政法规规定的其他义务。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"数据安全法|第二十七条":["第二十七条 开展数据处理活动应当依照法律、法规的规定，建立健全全流程数据安全管理制度，组织开展数据安全教育培训，采取相应的技术措施和其他必要措施，保障数据安全。利用互联网等信息网络开展数据处理活动，应当在网络安全等级保护制度的基础上，履行上述数据安全保护义务。重要数据的处理者应当明确数据安全负责人和管理机构，落实数据安全保护责任。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第三十六条":["第三十六条 中华人民共和国主管机关根据有关法律和中华人民共和国缔结或者参加的国际条约、协定，或者按照平等互惠原则，处理外国司法或者执法机构关于提供数据的请求。非经中华人民共和国主管机关批准，境内的组织、个人不得向外国司法或者执法机构提供存储于中华人民共和国境内的数据。\n第五章 政务数据安全与开放","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"生成式人工智能服务管理暂行办法|第十二条":["第十二条 提供者应当按照《互联网信息服务深度合成管理规定》对图片、视频等生成内容进行标识。","a1109ed222","生成式人工智能服务管理暂行办法","https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm",0,"现行有效","2023-08-15",[]],"生成式人工智能服务管理暂行办法|第十七条":["第十七条 提供具有舆论属性或者社会动员能力的生成式人工智能服务的，应当按照国家有关规定开展安全评估，并按照《互联网信息服务算法推荐管理规定》履行算法备案和变更、注销备案手续。","a1109ed222","生成式人工智能服务管理暂行办法","https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm",0,"现行有效","2023-08-15",[]],"电子商务法|第八十三条":["第八十三条 电子商务平台经营者违反本法第三十八条规定，对平台内经营者侵害消费者合法权益行为未采取必要措施，或者对平台内经营者未尽到资质资格审核义务，或者对消费者未尽到安全保障义务的，由市场监督管理部门责令限期改正，可以处五万元以上五十万元以下的罚款；情节严重的，责令停业整顿，并处五十万元以上二百万元以下的罚款。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"广告法|第九条":["第九条 广告不得有下列情形：\n（一）使用或者变相使用中华人民共和国的国旗、国歌、国徽，军旗、军歌、军徽；\n（二）使用或者变相使用国家机关、国家机关工作人员的名义或者形象；\n（三）使用“国家级”、“最高级”、“最佳”等用语；\n（四）损害国家的尊严或者利益，泄露国家秘密；\n（五）妨碍社会安定，损害社会公共利益；\n（六）危害人身、财产安全，泄露个人隐私；\n（七）妨碍社会公共秩序或者违背社会良好风尚；\n（八）含有淫秽、色情、赌博、迷信、恐怖、暴力的内容；\n（九）含有民族、种族、宗教、性别歧视的内容；\n（十）妨碍环境、自然资源或者文化遗产保护；\n（十一）法律、行政法规规定禁止的其他情形。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"消费者权益保护法|第二十九条":["第二十九条 经营者收集、使用消费者个人信息，应当遵循合法、正当、必要的原则，明示收集、使用信息的目的、方式和范围，并经消费者同意。经营者收集、使用消费者个人信息，应当公开其收集、使用规则，不得违反法律、法规的规定和双方的约定收集、使用信息。\n经营者及其工作人员对收集的消费者个人信息必须严格保密，不得泄露、出售或者非法向他人提供。经营者应当采取技术措施和其他必要措施，确保信息安全，防止消费者个人信息泄露、丢失。在发生或者可能发生信息泄露、丢失的情况时，应当立即采取补救措施。\n经营者未经消费者同意或者请求，或者消费者明确表示拒绝的，不得向其发送商业性信息。\n第四章 国家对消费者合法权益的保护","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"食品安全法|第一百三十六条":["第一百三十六条食品经营者履行了本法规定的进货查验等义务，有充分证据证明其不知道所采购的食品不符合食品安全标准，并能如实说明其进货来源的，可以免予处罚，但应当依法没收其不符合食品安全标准的食品；造成人身、财产或者其他损害的，依法承担赔偿责任。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"行政处罚法|第五条":["第五条 行政处罚遵循公正、公开的原则。\n设定和实施行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。\n对违法行为给予行政处罚的规定必须公布；未经公布的，不得作为行政处罚的依据。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第六条":["第六条 实施行政处罚，纠正违法行为，应当坚持处罚与教育相结合，教育公民、法人或者其他组织自觉守法。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第八条":["第八条 公民、法人或者其他组织因违法行为受到行政处罚，其违法行为对他人造成损害的，应当依法承担民事责任。\n违法行为构成犯罪，应当依法追究刑事责任的，不得以行政处罚代替刑事处罚。\n第二章 行政处罚的种类和设定","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第九条":["第九条 行政处罚的种类：\n（一）警告、通报批评；\n（二）罚款、没收违法所得、没收非法财物；\n（三）暂扣许可证件、降低资质等级、吊销许可证件；\n（四）限制开展生产经营活动、责令停产停业、责令关闭、限制从业；\n（五）行政拘留；\n（六）法律、行政法规规定的其他行政处罚。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第十一条":["第十一条 行政法规可以设定除限制人身自由以外的行政处罚。\n法律对违法行为已经作出行政处罚规定，行政法规需要作出具体规定的，必须在法律规定的给予行政处罚的行为、种类和幅度的范围内规定。\n法律对违法行为未作出行政处罚规定，行政法规为实施法律，可以补充设定行政处罚。拟补充设定行政处罚的，应当通过听证会、论证会等形式广泛听取意见，并向制定机关作出书面说明。行政法规报送备案时，应当说明补充设定行政处罚的情况。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第十二条":["第十二条 地方性法规可以设定除限制人身自由、吊销营业执照以外的行政处罚。\n法律、行政法规对违法行为已经作出行政处罚规定，地方性法规需要作出具体规定的，必须在法律、行政法规规定的给予行政处罚的行为、种类和幅度的范围内规定。\n法律、行政法规对违法行为未作出行政处罚规定，地方性法规为实施法律、行政法规，可以补充设定行政处罚。拟补充设定行政处罚的，应当通过听证会、论证会等形式广泛听取意见，并向制定机关作出书面说明。地方性法规报送备案时，应当说明补充设定行政处罚的情况。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第十三条":["第十三条 国务院部门规章可以在法律、行政法规规定的给予行政处罚的行为、种类和幅度的范围内作出具体规定。\n尚未制定法律、行政法规的，国务院部门规章对违反行政管理秩序的行为，可以设定警告、通报批评或者一定数额罚款的行政处罚。罚款的限额由国务院规定。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"行政处罚法|第二十条":["第二十条 行政机关依照法律、法规、规章的规定，可以在其法定权限内书面委托符合本法第二十一条规定条件的组织实施行政处罚。行政机关不得委托其他组织或者个人实施行政处罚。\n委托书应当载明委托的具体事项、权限、期限等内容。委托行政机关和受委托组织应当将委托书向社会公布。\n委托行政机关对受委托组织实施行政处罚的行为应当负责监督，并对该行为的后果承担法律责任。\n受委托组织在委托范围内，以委托行政机关名义实施行政处罚；不得再委托其他组织或者个人实施行政处罚。","5811c28513","中华人民共和国行政处罚法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NzAzYWRkMjAxNzczNzNkZjZhNDNlMzM=",0,"现行有效","2021-07-15",[]],"食品安全法|第四条":["第四条食品生产经营者对其生产经营食品的安全负责。食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责，接受社会监督，承担社会责任。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"食品安全法|第九条":["第九条食品行业协会应当加强行业自律，按照章程建立健全行业规范和奖惩机制，提供食品安全信息、技术等服务，引导\n和督促食品生产经营者依法生产经营，推动行业诚信建设，宣传、普及食品安全知识。消费者协会和其他消费者组织对违反本法规定，损害消费者合法权益的行为，依法进行社会监督。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"食品安全法|第十四条":["第十四条国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。国务院卫生行政部门会同国务院食品安全监督管理等部门，制定、实施国家食品安全风险监测计划。国务院食品安全监督管理部门和其他有关部门获知有关食品安全风险信息后，应当立即核实并向国务院卫生行政部门通报。对有关部门通报的食品安全风险信息以及医疗机构报告的食源性疾病等有关疾病信息，国务院卫生行政部门应当会同国务院有关部门分析研究，认为必要的，及时调整国家食品安全风险监测计划。省、自治区、直辖市人民政府卫生行政部门会同同级食品安全监督管理等部门，根据国家食品安全风险监测计划，结合本行政区域的具体情况，制定、调整本行政区域的食品安全风险监测方案，报国务院卫生行政部门备案并实施。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"食品安全法|第十五条":["第十五条承担食品安全风险监测工作的技术机构应当根据食品安全风险监测计划和监测方案开展监测工作，保证监测数据真实、准确，并按照食品安全风险监测计划和监测方案的要求报送监测数据和分析结果。\n食品安全风险监测工作人员有权进入相关食用农产品种植养殖、食品生产经营场所采集样品、收集相关数据。采集样品应当按照市场价格支付费用。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"食品安全法|第十六条":["第十六条食品安全风险监测结果表明可能存在食品安全隐患的，县级以上人民政府卫生行政部门应当及时将相关信息通报同级食品安全监督管理等部门，并报告本级人民政府和上级人民政府卫生行政部门。食品安全监督管理等部门应当组织开展进一步调查。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"食品安全法|第一百二十三条":["第一百二十三条违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品货值金额不足一万元的，并处十万元以上十五万元以下罚款；货值金额一万元以上的，并处货值金额十五倍以上三十倍以下罚款；情节严重的，吊销许可证，并可以由公安机关对其直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留：\n（一）用非食品原料生产食品、在食品中添加食品添加剂以外的化学物质和其他可能危害人体健康的物质，或者用回收食品\n作为原料生产食品，或者经营上述食品；\n（二）生产经营营养成分不符合食品安全标准的专供婴幼儿和其他特定人群的主辅食品；\n（三）经营病死、毒死或者死因不明的禽、畜、兽、水产动物肉类，或者生产经营其制品；\n（四）经营未按规定进行检疫或者检疫不合格的肉类，或者生产经营未经检验或者检验不合格的肉类制品；\n（五）生产经营国家为防病等特殊需要明令禁止生产经营的\n食品；\n（六）生产经营添加药品的食品。明知从事前款规定的违法行为，仍为其提供生产经营场所或者其他条件的，由县级以上人民政府食品安全监督管理部门责令停止违法行为，没收违法所得，并处十万元以上二十万元以下罚款；使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。违法使用剧毒、高毒农药的，除依照有关法律、法规规定给予处罚外，可以由公安机关依照第一款规定给予拘留。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"产品质量法|第三条":["第三条 生产者、销售者应当建立健全内部产品质量管理制度，严格实施岗位质量规范、质量责任以及相应的考核办法。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"产品质量法|第十条":["第十条 任何单位和个人有权对违反本法规定的行为，向市场监督管理部门或者其他有关部门检举。\n市场监督管理部门和有关部门应当为检举人保密，并按照省、自治区、直辖市人民政府的规定给予奖励。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"产品质量法|第十一条":["第十一条 任何单位和个人不得排斥非本地区或者非本系统企业生产的质量合格产品进入本地区、本系统。\n第二章 产品质量的监督","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"产品质量法|第十七条":["第十七条 依照本法规定进行监督抽查的产品质量不合格的，由实施监督抽查的市场监督管理部门责令其生产者、销售者限期改正。逾期不改正的，由省级以上人民政府市场监督管理部门予以公告；公告后经复查仍不合格的，责令停业，限期整顿；整顿期满后经复查产品质量仍不合格的，吊销营业执照。\n监督抽查的产品有严重质量问题的，依照本法第五章的有关规定处罚。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"产品质量法|第二十一条":["第二十一条 产品质量检验机构、认证机构必须依法按照有关标准，客观、公正地出具检验结果或者认证证明。\n产品质量认证机构应当依照国家规定对准许使用认证标志的产品进行认证后的跟踪检查；对不符合认证标准而使用认证标志的，要求其改正；情节严重的，取消其使用认证标志的资格。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"产品质量法|第四十条":["第四十条 售出的产品有下列情形之一的，销售者应当负责修理、更换、退货；给购买产品的消费者造成损失的，销售者应当赔偿损失：\n（一）不具备产品应当具备的使用性能而事先未作说明的；\n（二）不符合在产品或者其包装上注明采用的产品标准的；\n（三）不符合以产品说明、实物样品等方式表明的质量状况的。\n销售者依照前款规定负责修理、更换、退货、赔偿损失后，属于生产者的责任或者属于向销售者提供产品的其他销售者（以下简称供货者）的责任的，销售者有权向生产者、供货者追偿。\n销售者未按照第一款规定给予修理、更换、退货或者赔偿损失的，由市场监督管理部门责令改正。\n生产者之间，销售者之间，生产者与销售者之间订立的买卖合同、承揽合同有不同约定的，合同当事人按照合同约定执行。","796a06c075","中华人民共和国产品质量法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjEzNWY0NjAxNmYxZDZkZmQ3NjE0ZDM=",0,"现行有效","2018-12-29",[]],"反不正当竞争法|第二十四条":["第二十四条 有关单位违反本法第八条规定贿赂他人或者收受贿赂的，由监督检查部门没收违法所得，处十万元以上一百万元以下的罚款；情节严重的，处一百万元以上五百万元以下的罚款，可以并处吊销营业执照。\n经营者的法定代表人、主要负责人和直接责任人员对实施贿赂负有个人责任，以及有关个人收受贿赂的，由监督检查部门没收违法所得，处一百万元以下的罚款。","7ef65778c1","中华人民共和国反不正当竞争法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NzE1NTJiNDAxOTdiMTAxNmVmYzU0Mzc=",0,"现行有效","2025-10-15",[]],"专利法|第七条":["第七条 对发明人或者设计人的非职务发明创造专利申请，任何单位或者个人不得压制。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法|第十条":["第十条 专利申请权和专利权可以转让。\n中国单位或者个人向外国人、外国企业或者外国其他组织转让专利申请权或者专利权的，应当依照有关法律、行政法规的规定办理手续。\n转让专利申请权或者专利权的，当事人应当订立书面合同，并向国务院专利行政部门登记，由国务院专利行政部门予以公告。专利申请权或者专利权的转让自登记之日起生效。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法|第十二条":["第十二条 任何单位或者个人实施他人专利的，应当与专利权人订立实施许可合同，向专利权人支付专利使用费。被许可人无权允许合同规定以外的任何单位或者个人实施该专利。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法|第十四条":["第十四条 专利申请权或者专利权的共有人对权利的行使有约定的，从其约定。没有约定的，共有人可以单独实施或者以普通许可方式许可他人实施该专利；许可他人实施该专利的，收取的使用费应当在共有人之间分配。\n除前款规定的情形外，行使共有的专利申请权或者专利权应当取得全体共有人的同意。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法|第六十八条":["第六十八条 假冒专利的，除依法承担民事责任外，由负责专利执法的部门责令改正并予公告，没收违法所得，可以处违法所得五倍以下的罚款；没有违法所得或者违法所得在五万元以下的，可以处二十五万元以下的罚款；构成犯罪的，依法追究刑事责任。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"专利法|第七十九条":["第七十九条 管理专利工作的部门不得参与向社会推荐专利产品等经营活动。\n管理专利工作的部门违反前款规定的，由其上级机关或者监察机关责令改正，消除影响，有违法收入的予以没收；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。","cdbdf984b7","中华人民共和国专利法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NTJiN2Q0MzAxNzVlNDY1MWNiZDE1NDc=",0,"现行有效","2021-06-01",[]],"商标法|第三条":["第三条 商标工作应当贯彻党和国家知识产权战略部署，提升商标保护、运用、管理和服务水平。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"商标法|第九条":["第九条 申请注册和使用商标，应当遵循诚信原则，不得滥用权利损害国家利益、社会公共利益或者他人合法权益。\n商标使用人应当对其使用商标的商品质量负责。各级负责商标管理工作、商标执法的部门应当依法加强商标管理和执法，制止欺骗消费者的行为。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"商标法|第十一条":["第十一条 外国人、外国企业或者外国其他组织在中国申请商标注册的，应当按其所属国和中华人民共和国签订的协议或者共同参加的国际条约办理，或者按对等原则办理。\n在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请商标注册和办理其他商标事宜的，应当委托依法设立的商标代理机构办理。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"商标法|第十五条":["第十五条 下列标志不得作为商标注册和使用：\n（一）同中国共产党的名称、党旗、党徽、勋章或者重要理论成就、历史事件相关的标志性要素等相同或者近似的；\n（二）同中华人民共和国的国家名称、国旗、国徽、国歌、军旗、军徽、军歌、勋章等相同或者近似的，以及同中央和国家机关的名称、标志、所在地特定地点的名称或者标志性建筑物的名称、图形相同的；\n（三）同外国的国家名称、国旗、国徽、军旗等相同或者近似的，但经该国政府同意的除外；\n（四）同政府间国际组织的名称、旗帜、徽记等相同或者近似的，但经该组织同意或者不易误导公众的除外；\n（五）与表明实施控制、予以保证的官方标志、检验印记相同或者近似的，但经授权的除外；\n（六）同“红十字”、“红新月”的名称、标志相同或者近似的；\n（七）带有民族歧视性的；\n（八）带有欺骗性，容易使公众对商品的质量、工艺、原料等特点或者产地产生误认的；\n（九）违背公序良俗或者有其他不良影响的。\n国家公园标志、奥林匹克标志、特殊标志等标志作为商标注册和使用的，依照本法和有关法律、行政法规的规定执行。\n（一）仅有本商品的通用名称、图形、型号的；\n（二）仅直接表示商品的质量、主要原料、功能、用途、重量、数量及其他特点的；\n（三）其他缺乏显著特征的。\n前款所列标志经过使用取得显著特征，并便于识别的，可以作为商标注册。\n不得以欺骗或者其他不正当手段申请商标注册。\n前款所称地理标志，是指标示某商品来源于某地区，该商品的特定质量、信誉或者其他特征，主要由该地区的自然因素或者人文因素所决定的标志。\n第三章 商标注册的申请\n商标注册申请等有关文件，应当以书面形式提出。以电子数据交换等方式能够有形地表现所载内容，并可以随时调取查用的数据电文，视为书面形式。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"商标法|第三十条":["第三十条 商标在中国政府主办的或者承认的国际展览会展出的商品上首次使用的，自该商品展出之日起六个月内，该商标的注册申请人可以享有优先权。\n依照前款要求优先权的，应当在提出商标注册申请的时候提出书面声明，并且在三个月内提交展出其商品的展览会名称、在展出商品上使用该商标的证据、展出日期等证明文件；未提出书面声明或者逾期未提交证明文件的，视为未要求优先权。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"商标法|第六十四条":["第六十四条 生产经营者不得将“驰名商标”字样用于商品、商品包装或者容器上，或者用于广告宣传、展览以及其他商业活动中。\n违反前款规定的，由负责商标执法的部门责令改正，处十万元以下的罚款。","f1960fc506","中华人民共和国商标法","https://flk.npc.gov.cn/detail2.html?OTViYjc0N2RiNTRlNDE5MTg0ZWZmMDY1NDY1MTU4MjY=",0,"即将实施","2027-01-01",[]],"特种设备安全法|第三条":["第三条 特种设备安全工作应当坚持安全第一、预防为主、节能环保、综合治理的原则。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第七条":["第七条 特种设备生产、经营、使用单位应当遵守本法和其他有关法律、法规，建立、健全特种设备安全和节能责任制度，加强特种设备安全和节能管理，确保特种设备生产、经营、使用安全，符合节能要求。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第八条":["第八条 特种设备生产、经营、使用、检验、检测应当遵守有关特种设备安全技术规范及相关标准。\n特种设备安全技术规范由国务院负责特种设备安全监督管理的部门制定。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第九条":["第九条 特种设备行业协会应当加强行业自律，推进行业诚信体系建设，提高特种设备安全管理水平。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第十一条":["第十一条 负责特种设备安全监督管理的部门应当加强特种设备安全宣传教育，普及特种设备安全知识，增强社会公众的特种设备安全意识。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第七十四条":["第七十四条 违反本法规定，未经许可从事特种设备生产活动的，责令停止生产，没收违法制造的特种设备，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得；已经实施安装、改造、修理的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造、修理。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第七十五条":["第七十五条 违反本法规定，特种设备的设计文件未经鉴定，擅自用于制造的，责令改正，没收违法制造的特种设备，处五万元以上五十万元以下罚款。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第七十六条":["第七十六条 违反本法规定，未进行型式试验的，责令限期改正；逾期未改正的，处三万元以上三十万元以下罚款。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"价格法|第三条":["第三条 国家实行并逐步完善宏观经济调控下主要由市场形成价格的机制。价格的制定应当符合价值规律，大多数商品和服务价格实行市场调节价，极少数商品和服务价格实行政府指导价或者政府定价。\n市场调节价，是指由经营者自主制定，通过市场竞争形成的价格。\n本法所称经营者是指从事生产、经营商品或者提供有偿服务的法人、其他组织和个人。\n政府指导价，是指依照本法规定，由政府价格主管部门或者其他有关部门，按照定价权限和范围规定基准价及其浮动幅度，指导经营者制定的价格。\n政府定价，是指依照本法规定，由政府价格主管部门或者其他有关部门，按照定价权限和范围制定的价格。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",0,"现行有效","1998-05-01",[]],"价格法|第九条":["第九条 经营者应当努力改进生产经营管理，降低生产经营成本，为消费者提供价格合理的商品和服务，并在市场竞争中获取合法利润。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",0,"现行有效","1998-05-01",[]],"价格法|第十条":["第十条 经营者应当根据其经营条件建立、健全内部价格管理制度，准确记录与核定商品和服务的生产经营成本，不得弄虚作假。","df117a9914","中华人民共和国价格法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY1ZTA1ODAxZWY=",0,"现行有效","1998-05-01",[]],"广告法|第三条":["第三条 广告应当真实、合法，以健康的表现形式表达广告内容，符合社会主义精神文明建设和弘扬中华民族优秀传统文化的要求。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"广告法|第四条":["第四条 广告不得含有虚假或者引人误解的内容，不得欺骗、误导消费者。广告主应当对广告内容的真实性负责。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"广告法|第五条":["第五条 广告主、广告经营者、广告发布者从事广告活动，应当遵守法律、法规，诚实信用，公平竞争。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"广告法|第八条":["第八条 广告中对商品的性能、功能、产地、用途、质量、成分、价格、生产者、有效期限、允诺等或者对服务的内容、提供者、形式、质量、价格、允诺等有表示的，应当准确、清楚、明白。广告中表明推销的商品或者服务附带赠送的，应当明示所附带赠送商品或者服务的品种、规格、数量、期限和方式。法律、行政法规规定广告中应当明示的内容，应当显著、清晰表示。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"广告法|第五十七条":["第五十七条 有下列行为之一的，由工商行政管理部门责令停止发布广告，对广告主处二十万元以上一百万元以下的罚款，情节严重的，并可以吊销营业执照，由广告审查机关撤销广告审查批准文件、一年内不受理其广告审查申请；对广告经营者、广告发布者，由工商行政管理部门没收广告费用，处二十万元以上一百万元以下的罚款，情节严重的，并可以吊销营业执照、吊销广告发布登记证件：\n（一）发布有本法第九条、第十条规定的禁止情形的广告的；\n（二）违反本法第十五条规定发布处方药广告、药品类易制毒化学品广告、戒毒治疗的医疗器械和治疗方法广告的；\n（三）违反本法第二十条规定，发布声称全部或者部分替代母乳的婴儿乳制品、饮料和其他食品广告的；\n（四）违反本法第二十二条规定发布烟草广告的；\n（五）违反本法第三十七条规定，利用广告推销禁止生产、销售的产品或者提供的服务，或者禁止发布广告的商品或者服务的；\n（六）违反本法第四十条第一款规定，在针对未成年人的大众传播媒介上发布医疗、药品、保健食品、医疗器械、化妆品、酒类、美容广告，以及不利于未成年人身心健康的网络游戏广告的。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"企业信息公示暂行条例|第三条":["第三条 企业信息公示应当真实、及时。公示的企业信息涉及国家秘密、国家安全或者社会公共利益的，应当报请主管的保密行政管理部门或者国家安全机关批准。县级以上地方人民政府有关部门公示的企业信息涉及企业商业秘密或者个人隐私的，应当报请上级主管部门批准。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",0,"现行有效","2024-05-01",[]],"企业信息公示暂行条例|第九条":["第九条 企业年度报告内容包括：\n（一）企业通信地址、邮政编码、联系电话、电子邮箱等信息；\n（二）企业开业、歇业、清算等存续状态信息；\n（三）企业投资设立企业、购买股权信息；\n（四）企业为有限责任公司或者股份有限公司的，其股东或者发起人认缴和实缴的出资额、出资时间、出资方式等信息；\n（五）有限责任公司股东股权转让等股权变更信息；\n（六）企业网站以及从事网络经营的网店的名称、网址等信息；\n（七）企业从业人数、资产总额、负债总额、对外提供保证担保、所有者权益合计、营业总收入、主营业务收入、利润总额、净利润、纳税总额信息。\n前款第一项至第六项规定的信息应当向社会公示，第七项规定的信息由企业选择是否向社会公示。\n经企业同意，公民、法人或者其他组织可以查询企业选择不公示的信息。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",0,"现行有效","2024-05-01",[]],"企业信息公示暂行条例|第十条":["第十条 企业应当自下列信息形成之日起20个工作日内通过国家企业信用信息公示系统向社会公示：\n（一）有限责任公司股东或者股份有限公司发起人认缴和实缴的出资额、出资时间、出资方式等信息；\n（二）有限责任公司股东股权转让等股权变更信息；\n（三）行政许可取得、变更、延续信息；\n（四）知识产权出质登记信息；\n（五）受到行政处罚的信息；\n（六）其他依法应当公示的信息。\n市场监督管理部门发现企业未依照前款规定履行公示义务的，应当责令其限期履行。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",0,"现行有效","2024-05-01",[]],"企业信息公示暂行条例|第十二条":["第十二条 政府部门发现其公示的信息不准确的，应当及时更正。公民、法人或者其他组织有证据证明政府部门公示的信息不准确的，有权要求该政府部门予以更正。\n企业发现其公示的信息不准确的，应当及时更正；但是，企业年度报告公示信息的更正应当在每年6月30日之前完成。更正前后的信息应当同时公示。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",0,"现行有效","2024-05-01",[]],"企业信息公示暂行条例|第二十一条":["第二十一条 政府部门未依照本条例规定履行职责的，由监察机关、上一级政府部门责令改正；情节严重的，对负有责任的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","19e5532fc5","企业信息公示暂行条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZmNjNTAxOWNkMThmYzZlOTU1N2Q=",0,"现行有效","2024-05-01",[]],"价格违法行为行政处罚规定|第四条":["第四条 经营者违反价格法第十四条的规定，有下列行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处10万元以上100万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照：\n(一)除依法降价处理鲜活商品、季节性商品、积压商品等商品外，为了排挤竞争对手或者独占市场，以低于成本的价格倾销，扰乱正常的生产经营秩序，损害国家利益或者其他经营者的合法权益的；\n(二)提供相同商品或者服务，对具有同等交易条件的其他经营者实行价格歧视的。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"价格违法行为行政处罚规定|第五条":["第五条 经营者违反价格法第十四条的规定，相互串通，操纵市场价格，造成商品价格较大幅度上涨的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处10万元以上100万元以下的罚款，情节较重的处100万元以上500万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。\n除前款规定情形外，经营者相互串通，操纵市场价格，损害其他经营者或者消费者合法权益的，依照本规定第四条的规定处罚。\n行业协会或者其他单位组织经营者相互串通，操纵市场价格的，对经营者依照前两款的规定处罚；对行业协会或者其他单位，可以处50万元以下的罚款，情节严重的，由登记管理机关依法撤销登记、吊销执照。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"价格违法行为行政处罚规定|第六条":["第六条 经营者违反价格法第十四条的规定，有下列推动商品价格过快、过高上涨行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款，情节较重的处50万元以上300万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照：\n(一)捏造、散布涨价信息，扰乱市场价格秩序的；\n(二)除生产自用外，超出正常的存储数量或者存储周期，大量囤积市场供应紧张、价格发生异常波动的商品，经价格主管部门告诫仍继续囤积的；\n(三)利用其他手段哄抬价格，推动商品价格过快、过高上涨的。\n行业协会或者为商品交易提供服务的单位有前款规定的违法行为的，可以处50万元以下的罚款；情节严重的，由登记管理机关依法撤销登记、吊销执照。\n前两款规定以外的其他单位散布虚假涨价信息，扰乱市场价格秩序，依法应当由其他主管机关查处的，价格主管部门可以提出依法处罚的建议，有关主管机关应当依法处罚。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"价格违法行为行政处罚规定|第十五条":["第十五条 政府价格主管部门进行价格监督检查时，发现经营者的违法行为同时具有下列三种情形的，可以依照价格法第三十四条第(三)项的规定责令其暂停相关营业：\n(一)违法行为情节复杂或者情节严重，经查明后可能给予较重处罚的；\n(二)不暂停相关营业，违法行为将继续的；\n(三)不暂停相关营业，可能影响违法事实的认定，采取其他措施又不足以保证查明的。\n政府价格主管部门进行价格监督检查时，执法人员不得少于2人，并应当向经营者或者有关人员出示证件。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"价格违法行为行政处罚规定|第十七条":["第十七条 经营者有《中华人民共和国行政处罚法》第二十七条所列情形的，应当依法从轻或者减轻处罚。\n经营者有下列情形之一的，应当从重处罚：\n(一)价格违法行为严重或者社会影响较大的；\n(二)屡查屡犯的；\n(三)伪造、涂改或者转移、销毁证据的；\n(四)转移与价格违法行为有关的资金或者商品的；\n(五)经营者拒不按照本规定第十六条第一款规定退还消费者或者其他经营者多付价款的；\n(六)应予从重处罚的其他价格违法行为。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"价格违法行为行政处罚规定|第二十条":["第二十条 经营者对政府价格主管部门作出的处罚决定不服的，应当先依法申请行政复议；对行政复议决定不服的，可以依法向人民法院提起诉讼。","eb10ee4e71","价格违法行为行政处罚规定","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTAzY2RlNjExN2I=",0,"现行有效","2010-12-04",[]],"认证认可条例|第七条":["第七条 国家鼓励平等互利地开展认证认可国际互认活动。认证认可国际互认活动不得损害国家安全和社会公共利益。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第十条":["第十条 取得认证机构资质，应当符合下列条件：\n（一）取得法人资格；\n（二）有固定的场所和必要的设施；\n（三）有符合认证认可要求的管理制度；\n（四）注册资本不得少于人民币300万元；\n（五）有10名以上相应领域的专职认证人员。\n从事产品认证活动的认证机构，还应当具备与从事相关产品认证活动相适应的检测、检查等技术能力。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第十一条":["第十一条 认证机构资质的申请和批准程序：\n（一）认证机构资质的申请人，应当向国务院认证认可监督管理部门提出书面申请，并提交符合本条例第十条规定条件的证明文件；\n（二）国务院认证认可监督管理部门自受理认证机构资质申请之日起45日内，应当作出是否批准的决定。涉及国务院有关部门职责的，应当征求国务院有关部门的意见。决定批准的，向申请人出具批准文件，决定不予批准的，应当书面通知申请人，并说明理由。\n国务院认证认可监督管理部门应当公布依法取得认证机构资质的企业名录。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第十三条":["第十三条 认证机构不得与行政机关存在利益关系。\n认证机构不得接受任何可能对认证活动的客观公正产生影响的资助；不得从事任何可能对认证活动的客观公正产生影响的产品开发、营销等活动。\n认证机构不得与认证委托人存在资产、管理方面的利益关系。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第五十六条":["第五十六条 未经批准擅自从事认证活动的，予以取缔，处10万元以上50万元以下的罚款，有违法所得的，没收违法所得。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第五十七条":["第五十七条 境外认证机构未经登记在中华人民共和国境内设立代表机构的，予以取缔，处5万元以上20万元以下的罚款。\n经登记设立的境外认证机构代表机构在中华人民共和国境内从事认证活动的，责令改正，处10万元以上50万元以下的罚款，有违法所得的，没收违法所得；情节严重的，撤销批准文件，并予公布。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"认证认可条例|第五十八条":["第五十八条 认证机构接受可能对认证活动的客观公正产生影响的资助，或者从事可能对认证活动的客观公正产生影响的产品开发、营销等活动，或者与认证委托人存在资产、管理方面的利益关系的，责令停业整顿；情节严重的，撤销批准文件，并予公布；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。","621c673850","中华人民共和国认证认可条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4YTIyMTMyZjAxOGE2ZTM3YTdiNjIzMWQ=",0,"现行有效","2023-07-20",[]],"消费者权益保护法|第三条":["第三条 经营者为消费者提供其生产、销售的商品或者提供服务，应当遵守本法；本法未作规定的，应当遵守其他有关法律、法规。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"消费者权益保护法|第四条":["第四条 经营者与消费者进行交易，应当遵循自愿、平等、公平、诚实信用的原则。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"消费者权益保护法|第十七条":["第十七条 经营者应当听取消费者对其提供的商品或者服务的意见，接受消费者的监督。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"消费者权益保护法|第十八条":["第十八条 经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求。对可能危及人身、财产安全的商品和服务，应当向消费者作出真实的说明和明确的警示，并说明和标明正确使用商品或者接受服务的方法以及防止危害发生的方法。\n宾馆、商场、餐馆、银行、机场、车站、港口、影剧院等经营场所的经营者，应当对消费者尽到安全保障义务。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"消费者权益保护法|第十九条":["第十九条 经营者发现其提供的商品或者服务存在缺陷，有危及人身、财产安全危险的，应当立即向有关行政部门报告和告知消费者，并采取停止销售、警示、召回、无害化处理、销毁、停止生产或者服务等措施。采取召回措施的，经营者应当承担消费者因商品被召回支出的必要费用。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"消费者权益保护法|第五十八条":["第五十八条 经营者违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付的，先承担民事赔偿责任。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"计量法|第十条":["第十条 计量检定必须按照国家计量检定系统表进行。国家计量检定系统表由国务院计量行政部门制定。计量检定必须执行计量检定规程。国家计量检定规程由国务院计量行政部门制定。没有国家计量检定规程的，由国务院有关主管部门和省、自治区、直辖市人民政府计量行政部门分别制定部门计量检定规程和地方计量检定规程。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第十二条":["第十二条 制造、修理计量器具的企业、事业单位，必须具有与所制造、修理的计量器具相适应的设施、人员和检定仪器设备。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第十三条":["第十三条 制造计量器具的企业、事业单位生产本单位未生产过的计量器具新产品，必须经省级以上人民政府计量行政部门对其样品的计量性能考核合格，方可投入生产。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第十四条":["第十四条 任何单位和个人不得违反规定制造、销售和进口非法定计量单位的计量器具。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第十五条":["第十五条 制造、修理计量器具的企业、事业单位必须对制造、修理的计量器具进行检定，保证产品计量性能合格，并对合格产品出具产品合格证。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第二十三条":["第二十三条 制造、销售未经考核合格的计量器具新产品的，责令停止制造、销售该种新产品，没收违法所得，可以并处罚款。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"计量法|第二十四条":["第二十四条 制造、修理、销售的计量器具不合格的，没收违法所得，可以并处罚款。","b4799d8f86","中华人民共和国计量法","https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202208/t20220819_2796227.html",0,"现行有效","1986-07-01",[]],"市场主体登记管理条例|第三条":["第三条 市场主体应当依照本条例办理登记。未经登记，不得以市场主体名义从事经营活动。法律、行政法规规定无需办理登记的除外。\n市场主体登记包括设立登记、变更登记和注销登记。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第四条":["第四条 市场主体登记管理应当遵循依法合规、规范统一、公开透明、便捷高效的原则。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第八条":["第八条 市场主体的一般登记事项包括：\n（一）名称；\n（二）主体类型；\n（三）经营范围；\n（四）住所或者主要经营场所；\n（五）注册资本或者出资额；\n（六）法定代表人、执行事务合伙人或者负责人姓名。\n除前款规定外，还应当根据市场主体类型登记下列事项：\n（一）有限责任公司股东、股份有限公司发起人、非公司企业法人出资人的姓名或者名称；\n（二）个人独资企业的投资人姓名及居所；\n（三）合伙企业的合伙人名称或者姓名、住所、承担责任方式；\n（四）个体工商户的经营者姓名、住所、经营场所；\n（五）法律、行政法规规定的其他事项。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第九条":["第九条 市场主体的下列事项应当向登记机关办理备案：\n（一）章程或者合伙协议；\n（二）经营期限或者合伙期限；\n（三）有限责任公司股东或者股份有限公司发起人认缴的出资数额，合伙企业合伙人认缴或者实际缴付的出资数额、缴付期限和出资方式；\n（四）公司董事、监事、高级管理人员；\n（五）农民专业合作社（联合社）成员；\n（六）参加经营的个体工商户家庭成员姓名；\n（七）市场主体登记联络员、外商投资企业法律文件送达接受人；\n（八）公司、合伙企业等市场主体受益所有人相关信息；\n（九）法律、行政法规规定的其他事项。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第十二条":["第十二条 有下列情形之一的，不得担任公司、非公司企业法人的法定代表人：\n（一）无民事行为能力或者限制民事行为能力；\n（二）因贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序被判处刑罚，执行期满未逾5年，或者因犯罪被剥夺政治权利，执行期满未逾5年；\n（三）担任破产清算的公司、非公司企业法人的法定代表人、董事或者厂长、经理，对破产负有个人责任的，自破产清算完结之日起未逾3年；\n（四）担任因违法被吊销营业执照、责令关闭的公司、非公司企业法人的法定代表人，并负有个人责任的，自被吊销营业执照之日起未逾3年；\n（五）个人所负数额较大的债务到期未清偿；\n（六）法律、行政法规规定的其他情形。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第十三条":["第十三条 除法律、行政法规或者国务院决定另有规定外，市场主体的注册资本或者出资额实行认缴登记制，以人民币表示。\n出资方式应当符合法律、行政法规的规定。公司股东、非公司企业法人出资人、农民专业合作社（联合社）成员不得以劳务、信用、自然人姓名、商誉、特许经营权或者设定担保的财产等作价出资。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第三十三条":["第三十三条 市场主体未发生债权债务或者已将债权债务清偿完结，未发生或者已结清清偿费用、职工工资、社会保险费用、法定补偿金、应缴纳税款（滞纳金、罚款），并由全体投资人书面承诺对上述情况的真实性承担法律责任的，可以按照简易程序办理注销登记。\n市场主体应当将承诺书及注销登记申请通过国家企业信用信息公示系统公示，公示期为20日。在公示期内无相关部门、债权人及其他利害关系人提出异议的，市场主体可以于公示期届满之日起20日内向登记机关申请注销登记。\n个体工商户按照简易程序办理注销登记的，无需公示，由登记机关将个体工商户的注销登记申请推送至税务等有关部门，有关部门在10日内没有提出异议的，可以直接办理注销登记。\n市场主体注销依法须经批准的，或者市场主体被吊销营业执照、责令关闭、撤销，或者被列入经营异常名录的，不适用简易注销程序。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"市场主体登记管理条例|第四十三条":["第四十三条 未经设立登记从事经营活动的，由登记机关责令改正，没收违法所得；拒不改正的，处1万元以上10万元以下的罚款；情节严重的，依法责令关闭停业，并处10万元以上50万元以下的罚款。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"反垄断法|第五条":["第五条 国家建立健全公平竞争审查制度。\n行政机关和法律、法规授权的具有管理公共事务职能的组织在制定涉及市场主体经济活动的规定时，应当进行公平竞争审查。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第七条":["第七条 具有市场支配地位的经营者，不得滥用市场支配地位，排除、限制竞争。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第八条":["第八条 国有经济占控制地位的关系国民经济命脉和国家安全的行业以及依法实行专营专卖的行业，国家对其经营者的合法经营活动予以保护，并对经营者的经营行为及其商品和服务的价格依法实施监管和调控，维护消费者利益，促进技术进步。\n前款规定行业的经营者应当依法经营，诚实守信，严格自律，接受社会公众的监督，不得利用其控制地位或者专营专卖地位损害消费者利益。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第九条":["第九条 经营者不得利用数据和算法、技术、资本优势以及平台规则等从事本法禁止的垄断行为。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第十条":["第十条 行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，排除、限制竞争。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第五十六条":["第五十六条 经营者违反本法规定，达成并实施垄断协议的，由反垄断执法机构责令停止违法行为，没收违法所得，并处上一年度销售额百分之一以上百分之十以下的罚款，上一年度没有销售额的，处五百万元以下的罚款；尚未实施所达成的垄断协议的，可以处三百万元以下的罚款。经营者的法定代表人、主要负责人和直接责任人员对达成垄断协议负有个人责任的，可以处一百万元以下的罚款。\n经营者组织其他经营者达成垄断协议或者为其他经营者达成垄断协议提供实质性帮助的，适用前款规定。\n经营者主动向反垄断执法机构报告达成垄断协议的有关情况并提供重要证据的，反垄断执法机构可以酌情减轻或者免除对该经营者的处罚。\n行业协会违反本法规定，组织本行业的经营者达成垄断协议的，由反垄断执法机构责令改正，可以处三百万元以下的罚款；情节严重的，社会团体登记管理机关可以依法撤销登记。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"反垄断法|第五十八条":["第五十八条 经营者违反本法规定实施集中，且具有或者可能具有排除、限制竞争效果的，由国务院反垄断执法机构责令停止实施集中、限期处分股份或者资产、限期转让营业以及采取其他必要措施恢复到集中前的状态，处上一年度销售额百分之十以下的罚款；不具有排除、限制竞争效果的，处五百万元以下的罚款。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]],"化妆品监督管理条例|第六条":["第六条 化妆品注册人、备案人对化妆品的质量安全和功效宣称负责。\n化妆品生产经营者应当依照法律、法规、强制性国家标准、技术规范从事生产经营活动，加强管理，诚信自律，保证化妆品质量安全。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",0,"现行有效","2021-01-01",[]],"化妆品监督管理条例|第七条":["第七条 化妆品行业协会应当加强行业自律，督促引导化妆品生产经营者依法从事生产经营活动，推动行业诚信建设。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",0,"现行有效","2021-01-01",[]],"化妆品监督管理条例|第十二条":["第十二条 申请化妆品新原料注册或者进行化妆品新原料备案，应当提交下列资料：\n（一）注册申请人、备案人的名称、地址、联系方式；\n（二）新原料研制报告；\n（三）新原料的制备工艺、稳定性及其质量控制标准等研究资料；\n（四）新原料安全评估资料。\n注册申请人、备案人应当对所提交资料的真实性、科学性负责。\n化妆品新原料备案人通过国务院药品监督管理部门在线政务服务平台提交本条例规定的备案资料后即完成备案。\n经注册、备案的化妆品新原料纳入已使用的化妆品原料目录前，仍然按照化妆品新原料进行管理。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",0,"现行有效","2021-01-01",[]],"化妆品监督管理条例|第十五条":["第十五条 禁止用于化妆品生产的原料目录由国务院药品监督管理部门制定、公布。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",0,"现行有效","2021-01-01",[]],"化妆品监督管理条例|第十七条":["第十七条 特殊化妆品经国务院药品监督管理部门注册后方可生产、进口。国产普通化妆品应当在上市销售前向备案人所在地省、自治区、直辖市人民政府药品监督管理部门备案。进口普通化妆品应当在进口前向国务院药品监督管理部门备案。","4c8680c41a","化妆品监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3NmQ1Y2JjZTAxNzZkNzNjZDJlYTAzY2U=",0,"现行有效","2021-01-01",[]],"消费者权益保护法实施条例|第七条":["第七条 消费者在购买商品、使用商品或者接受服务时，依法享有人身和财产安全不受损害的权利。经营者向消费者提供商品或者服务（包括以奖励、赠送、试用等形式向消费者免费提供商品或者服务），应当保证商品或者服务符合保障人身、财产安全的要求。免费提供的商品或者服务存在瑕疵但不违反法律强制性规定且不影响正常使用性能的，经营者应当在提供商品或者服务前如实告知消费者。经营者应当保证其经营场所及设施符合保障人身、财产安全的要求，采取必要的安全防护措施，并设置相应的警示标识。消费者在经营场所遇到危险或者受到侵害时，经营者应当给予及时、必要的救助。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",0,"现行有效","2024-07-01",[]],"消费者权益保护法实施条例|第八条":["第八条 消费者认为经营者提供的商品或者服务可能存在缺陷，有危及人身、财产安全危险的，可以向经营者或者有关行政部门反映情况或者提出建议。经营者发现其提供的商品或者服务可能存在缺陷，有危及人身、财产安全危险的，应当依照消费者权益保护法第十九条的规定及时采取相关措施。采取召回措施的，生产或者进口商品的经营者应当制定召回计划，发布召回信息，明确告知消费者享有的相关权利，保存完整的召回记录，并承担消费者因商品被召回所支出的必要费用。商品销售、租赁、修理、零部件生产供应、受委托生产等相关经营者应当依法履行召回相关协助和配合义务。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",0,"现行有效","2024-07-01",[]],"消费者权益保护法实施条例|第九条":["第九条 经营者应当采用通俗易懂的方式，真实、全面地向消费者提供商品或者服务相关信息，不得通过虚构经营者资质、资格或者所获荣誉，虚构商品或者服务交易信息、经营数据，篡改、编造、隐匿用户评价等方式，进行虚假或者引人误解的宣传，欺骗、误导消费者。经营者不得在消费者不知情的情况下，对同一商品或者服务在同等交易条件下设置不同的价格或者收费标准。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",0,"现行有效","2024-07-01",[]],"消费者权益保护法实施条例|第十条":["第十条 经营者应当按照国家有关规定，以显著方式标明商品的品名、价格和计价单位或者服务的项目、内容、价格和计价方法等信息，做到价签价目齐全、内容真实准确、标识清晰醒目。经营者采取自动展期、自动续费等方式提供服务的，应当在消费者接受服务前和自动展期、自动续费等日期前，以显著方式提请消费者注意。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",0,"现行有效","2024-07-01",[]],"消费者权益保护法实施条例|第十二条":["第十二条 经营者以商业宣传、产品推荐、实物展示或者通知、声明、店堂告示等方式提供商品或者服务，对商品或者服务的数量、质量、价格、售后服务、责任承担等作出承诺的，应当向购买商品或者接受服务的消费者履行其所承诺的内容。","8d61b24350","中华人民共和国消费者权益保护法实施条例","https://www.gov.cn/zhengce/content/202403/content_6940158.htm",0,"现行有效","2024-07-01",[]],"食品安全法实施条例|第二条":["第二条 食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，建立健全食品安全管理制度，采取有效措施预防和控制食品安全风险，保证食品安全。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第七条":["第七条 食品安全风险监测结果表明存在食品安全隐患，食品安全监督管理等部门经进一步调查确认有必要通知相关食品生产经营者的，应当及时通知。\n接到通知的食品生产经营者应当立即进行自查，发现食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当依照食品安全法第六十三条的规定停止生产、经营，实施食品召回，并报告相关情况。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第十二条":["第十二条 保健食品、特殊医学用途配方食品、婴幼儿配方食品等特殊食品不属于地方特色食品，不得对其制定食品安全地方标准。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第十四条":["第十四条 食品生产企业不得制定低于食品安全国家标准或者地方标准要求的企业标准。食品生产企业制定食品安全指标严于食品安全国家标准或者地方标准的企业标准的，应当报省、自治区、直辖市人民政府卫生行政部门备案。\n食品生产企业制定企业标准的，应当公开，供公众免费查阅。\n第四章 食品生产经营","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第十五条":["第十五条 食品生产经营许可的有效期为5年。\n食品生产经营者的生产经营条件发生变化，不再符合食品生产经营要求的，食品生产经营者应当立即采取整改措施；需要重新办理许可手续的，应当依法办理。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第六十七条":["第六十七条 有下列情形之一的，属于食品安全法第一百二十三条至第一百二十六条、第一百三十二条以及本条例第七十二条、第七十三条规定的情节严重情形：\n(一)违法行为涉及的产品货值金额2万元以上或者违法行为持续时间3个月以上；\n(二)造成食源性疾病并出现死亡病例，或者造成30人以上食源性疾病但未出现死亡病例；\n(三)故意提供虚假信息或者隐瞒真实情况；\n(四)拒绝、逃避监督检查；\n(五)因违反食品安全法律、法规受到行政处罚后1年内又实施同一性质的食品安全违法行为，或者因违反食品安全法律、法规受到刑事处罚后又实施食品安全违法行为；\n(六)其他情节严重的情形。\n对情节严重的违法行为处以罚款时，应当依法从重从严。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第七十二条":["第七十二条 从事对温度、湿度等有特殊要求的食品贮存业务的非食品生产经营者，食品集中交易市场的开办者、食品展销会的举办者，未按照规定备案或者报告的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处1万元以上5万元以下罚款；情节严重的，责令停产停业，并处5万元以上20万元以下罚款。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"食品安全法实施条例|第七十三条":["第七十三条 利用会议、讲座、健康咨询等方式对食品进行虚假宣传的，由县级以上人民政府食品安全监督管理部门责令消除影响，有违法所得的，没收违法所得；情节严重的，依照食品安全法第一百四十条第五款的规定进行处罚；属于单位违法的，还应当依照本条例第七十五条的规定对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员给予处罚。","7497d7f461","中华人民共和国食品安全法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MGRiNjQ3MDA3OTg=",0,"现行有效","2019-12-01",[]],"医疗器械监督管理条例|第六条":["第六条 国家对医疗器械按照风险程度实行分类管理。\n第一类是风险程度低，实行常规管理可以保证其安全、有效的医疗器械。\n第二类是具有中度风险，需要严格控制管理以保证其安全、有效的医疗器械。\n第三类是具有较高风险，需要采取特别措施严格控制管理以保证其安全、有效的医疗器械。\n评价医疗器械风险程度，应当考虑医疗器械的预期目的、结构特征、使用方法等因素。\n国务院药品监督管理部门负责制定医疗器械的分类规则和分类目录，并根据医疗器械生产、经营、使用情况，及时对医疗器械的风险变化进行分析、评价，对分类规则和分类目录进行调整。制定、调整分类规则和分类目录，应当充分听取医疗器械注册人、备案人、生产经营企业以及使用单位、行业组织的意见，并参考国际医疗器械分类实践。医疗器械分类规则和分类目录应当向社会公布。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第七条":["第七条 医疗器械产品应当符合医疗器械强制性国家标准；尚无强制性国家标准的，应当符合医疗器械强制性行业标准。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第八条":["第八条 国家制定医疗器械产业规划和政策，将医疗器械创新纳入发展重点，对创新医疗器械予以优先审评审批，支持创新医疗器械临床推广和使用，推动医疗器械产业高质量发展。国务院药品监督管理部门应当配合国务院有关部门，贯彻实施国家医疗器械产业规划和引导政策。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第十一条":["第十一条 医疗器械行业组织应当加强行业自律，推进诚信体系建设，督促企业依法开展生产经营活动，引导企业诚实守信。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第十三条":["第十三条 第一类医疗器械实行产品备案管理，第二类、第三类医疗器械实行产品注册管理。\n医疗器械注册人、备案人应当加强医疗器械全生命周期质量管理，对研制、生产、经营、使用全过程中医疗器械的安全性、有效性依法承担责任。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第六十六条":["第六十六条 有下列情形之一的，医疗器械注册人、备案人应当主动开展已上市医疗器械再评价：\n（一）根据科学研究的发展，对医疗器械的安全、有效有认识上的改变；\n（二）医疗器械不良事件监测、评估结果表明医疗器械可能存在缺陷；\n（三）国务院药品监督管理部门规定的其他情形。\n省级以上人民政府药品监督管理部门根据医疗器械不良事件监测、评估等情况，对已上市医疗器械开展再评价。再评价结果表明已上市医疗器械不能保证安全、有效的，应当注销医疗器械注册证或者取消备案。\n医疗器械注册人、备案人、受托生产企业、经营企业未依照本条规定实施召回或者停止生产、经营的，负责药品监督管理的部门可以责令其召回或者停止生产、经营。\n第六章 监督检查","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"医疗器械监督管理条例|第七十二条":["第七十二条 医疗器械生产经营过程中存在产品质量安全隐患，未及时采取措施消除的，负责药品监督管理的部门可以采取告诫、责任约谈、责令限期整改等措施。\n对人体造成伤害或者有证据证明可能危害人体健康的医疗器械，负责药品监督管理的部门可以采取责令暂停生产、进口、经营、使用的紧急控制措施，并发布安全警示信息。","b4d63949e6","医疗器械监督管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZhMTAxOWMyZDBmY2M2YjRiMjc=",0,"现行有效","2025-01-20",[]],"明码标价和禁止价格欺诈规定|第三条":["第三条 经营者应当遵循公开、公平、诚实信用的原则，不得利用价格手段侵犯消费者和其他经营者的合法权益、扰乱市场价格秩序。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第四条":["第四条 卖场、商场、市场、网络交易平台经营者等交易场所提供者（以下简称交易场所提供者）应当依法配合市场监督管理部门对场所内（平台内）经营者开展价格监督管理工作。交易场所提供者发现场所内（平台内）经营者有违反本规定行为的，应当依法采取必要处置措施，保存有关信息记录，依法承担相应义务和责任。交易场所提供者应当尊重场所内（平台内）经营者的经营自主权，不得强制或者变相强制场所内（平台内）经营者参与价格促销活动。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第五条":["第五条 经营者销售、收购商品和提供服务时，应当按照市场监督管理部门的规定明码标价。明码标价应当根据商品和服务、行业、区域等特点，做到真实准确、货签对位、标识醒目。设区的市级以上市场监督管理部门可以根据特定行业、特定区域的交易习惯等特点，结合价格监督管理实际，规定可以不实行明码标价的商品和服务、行业、交易场所。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第六条":["第六条 经营者应当以显著方式进行明码标价，明确标示价格所对应的商品或者服务。经营者根据不同交易条件实行不同价格的，应当标明交易条件以及与其对应的价格。商品或者服务的价格发生变动时，经营者应当及时调整相应标价。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第七条":["第七条 经营者销售商品应当标示商品的品名、价格和计价单位。同一品牌或者种类的商品，因颜色、形状、规格、产地、等级等特征不同而实行不同价格的，经营者应当针对不同的价格分别标示品名，以示区别。经营者提供服务应当标示服务项目、服务内容和价格或者计价方法。经营者可以根据实际经营情况，自行增加标示与价格有关的质地、服务标准、结算方法等其他信息。设区的市级以上市场监督管理部门对于特定商品和服务，可以增加规定明码标价应当标示的内容。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第二十四条":["第二十四条 交易场所提供者违反本规定第四条第二款、第三款，法律、行政法规有规定的，依照其规定；法律、行政法规没有规定的，由县级以上市场监督管理部门责令改正，可以处三万元以下罚款；情节严重的，处三万元以上十万元以下罚款。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"明码标价和禁止价格欺诈规定|第二十五条":["第二十五条 交易场所提供者提供的标价模板不符合本规定的，由县级以上市场监督管理部门责令改正，可以处三万元以下罚款；情节严重的，处三万元以上十万元以下罚款。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"网络交易监督管理办法|第三条":["第三条网络交易经营者从事经营活动，应当遵循自愿、平等、公平、诚信原则，遵守法律、法规、规章和商业道德、公序良俗，公平参与市场竞争，认真履行法定义务，积极承担主体责任，接受社会各界监督。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第八条":["第八条网络交易经营者不得违反法律、法规、国务院决定的规定，从事无证无照经营。除《中华人民共和国电子商务法》第十条规定的不需要进行登记的情形外，网络交易经营者应当依法办理市场主体登记。个人通过网络从事保洁、洗涤、缝纫、理发、搬家、配制钥匙、管道疏通、家电家具修理修配等依法无须取得许可的便民劳务活动，依照《中华人民共和国电子商务法》第十条的规定不需要进行登记。个人从事网络交易活动，年交易额累计不超过10万元的，依照《中华人民共和国电子商务法》第十条的规定不需要进行登记。同一经营者在同一平台或者不同平台开设多家网店的，各网店交易额合并计算。个人从事的零星小额交易须依法取得行政许可的，应当依法办理市场主体登记。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第九条":["第九条仅通过网络开展经营活动的平台内经营者申请登记为个体工商户的，可以将网络经营场所登记为经营场所，将经常居住地登记为住所，其住所所在地的县、自治县、不设区的市、市辖区市场监督管理部门为其登记机关。同一经营者有两个以上网络经营场所的，应当一并登记。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第十一条":["第十一条网络交易经营者销售的商品或者提供的服务应当符合保障人身、财产安全的要求和环境保护要求，不得销售或者提供法律、行政法规禁止交易，损害国家利益和社会公共利益，违背公序良俗的商品或者服务。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第十二条":["第十二条网络交易经营者应当在其网站首页或者从事经营活动的主页面显著位置，持续公示经营者主体信息或者该信息的链接标识。鼓励网络交易经营者链接到国家市场监督管理总局电子营业执照亮照系统，公示其营业执照信息。已经办理市场主体登记的网络交易经营者应当如实公示下列营业执照信息以及与其经营业务有关的行政许可等信息，或者该信息的链接标识：\n（一）企业应当公示其营业执照登载的统一社会信用代码、名称、企业类型、法定代表人（负责人）、住所、注册资本（出资额）等信息；\n（二）个体工商户应当公示其营业执照登载的统一社会信用代码、名称、经营者姓名、经营场所、组成形式等信息；\n（三）农民专业合作社、农民专业合作社联合社应当公示其营业执照登载的统一社会信用代码、名称、法定代表人、住所、成员出资总额等信息。依照《中华人民共和国电子商务法》第十条规定不需要进行登记的经营者应当根据自身实际经营活动类型，如实公示以下自我声明以及实际经营地址、联系方式等信息，或者该信息的链接标识：\n（一）“个人销售自产农副产品，依法不需要办理市场主体登记”；\n（二）“个人销售家庭手工业产品，依法不需要办理市场主体登记”；\n（三）“个人利用自己的技能从事依法无须取得许可的便民劳务活动，依法不需要办理市场主体登记”；\n（四）“个人从事零星小额交易活动，依法不需要办理市场主体登记”。网络交易经营者公示的信息发生变更的，应当在十个工作日内完成更新公示。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第四十条":["第四十条网络交易平台经营者违反本办法第十条，拒不为入驻的平台内经营者出具网络经营场所相关材料的，由市场监督管理部门责令限期改正；逾期不改正的，处一万元以上三万元以下罚款。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第四十五条":["第四十五条网络交易经营者违反本办法第二十条，法律、行政法规有规定的，依照其规定；法律、行政法规没有规定的，由市场监督管理部门责令限期改正；逾期不改正的，处一万元以下罚款。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"网络交易监督管理办法|第四十六条":["第四十六条网络交易经营者违反本办法第二十二条的，由市场监督管理部门责令限期改正；逾期不改正的，处五千元以上三万元以下罚款。","767f9b1fd8","网络交易监督管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2025/art_4b47c79b8d994a42bba4835997688faa.html",0,"现行有效","2021-05-01",[]],"药品管理法|第三条":["第三条 药品管理应当以人民健康为中心，坚持风险管理、全程管控、社会共治的原则，建立科学、严格的监督管理制度，全面提升药品质量，保障药品的安全、有效、可及。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第七条":["第七条 从事药品研制、生产、经营、使用活动，应当遵守法律、法规、规章、标准和规范，保证全过程信息真实、准确、完整和可追溯。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第十二条":["第十二条 国家建立健全药品追溯制度。国务院药品监督管理部门应当制定统一的药品追溯标准和规范，推进药品追溯信息互通互享，实现药品可追溯。\n国家建立药物警戒制度，对药品不良反应及其他与用药有关的有害反应进行监测、识别、评估和控制。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第十四条":["第十四条 药品行业协会应当加强行业自律，建立健全行业规范，推动行业诚信体系建设，引导和督促会员依法开展药品生产经营等活动。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第十七条":["第十七条 从事药品研制活动，应当遵守药物非临床研究质量管理规范、药物临床试验质量管理规范，保证药品研制全过程持续符合法定要求。\n药物非临床研究质量管理规范、药物临床试验质量管理规范由国务院药品监督管理部门会同国务院有关部门制定。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第四十六条":["第四十六条 直接接触药品的包装材料和容器，应当符合药用要求，符合保障人体健康、安全的标准。\n对不合格的直接接触药品的包装材料和容器，由药品监督管理部门责令停止使用。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"药品管理法|第一百一十六条":["第一百一十六条 生产、销售假药的，没收违法生产、销售的药品和违法所得，责令停产停业整顿，吊销药品批准证明文件，并处违法生产、销售的药品货值金额十五倍以上三十倍以下的罚款；货值金额不足十万元的，按十万元计算；情节严重的，吊销药品生产许可证、药品经营许可证或者医疗机构制剂许可证，十年内不受理其相应申请；药品上市许可持有人为境外企业的，十年内禁止其药品进口。","e138f45e65","中华人民共和国药品管理法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0NjI0MmQ2MTI3ZWQ=",0,"现行有效","2019-12-01",[]],"商标法实施条例|第三条":["第三条 商标持有人依照商标法第十三条规定请求驰名商标保护的，应当提交其商标构成驰名商标的证据材料。商标局、商标评审委员会应当依照商标法第十四条的规定，根据审查、处理案件的需要以及当事人提交的证据材料，对其商标驰名情况作出认定。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第五条":["第五条 当事人委托商标代理机构申请商标注册或者办理其他商标事宜，应当提交代理委托书。代理委托书应当载明代理内容及权限；外国人或者外国企业的代理委托书还应当载明委托人的国籍。\n外国人或者外国企业的代理委托书及与其有关的证明文件的公证、认证手续，按照对等原则办理。\n商标法第十八条所称外国人或者外国企业，是指在中国没有经常居所或者营业所的外国人或者外国企业。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第六条":["第六条 申请商标注册或者办理其他商标事宜，应当使用中文。\n依照商标法和本条例规定提交的各种证件、证明文件和证据材料是外文的，应当附送中文译文；未附送的，视为未提交该证件、证明文件或者证据材料。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第七条":["第七条 商标局、商标评审委员会工作人员有下列情形之一的，应当回避，当事人或者利害关系人可以要求其回避：\n(一)是当事人或者当事人、代理人的近亲属的；\n(二)与当事人、代理人有其他关系，可能影响公正的；\n(三)与申请商标注册或者办理其他商标事宜有利害关系的。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第八条":["第八条 以商标法第二十二条规定的数据电文方式提交商标注册申请等有关文件，应当按照商标局或者商标评审委员会的规定通过互联网提交。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第七十一条":["第七十一条 违反商标法第四十三条第二款规定的，由工商行政管理部门责令限期改正；逾期不改正的，责令停止销售，拒不停止销售的，处10万元以下的罚款。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第七十二条":["第七十二条 商标持有人依照商标法第十三条规定请求驰名商标保护的，可以向工商行政管理部门提出请求。经商标局依照商标法第十四条规定认定为驰名商标的，由工商行政管理部门责令停止违反商标法第十三条规定使用商标的行为，收缴、销毁违法使用的商标标识；商标标识与商品难以分离的，一并收缴、销毁。\n第八章 注册商标专用权的保护","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"商标法实施条例|第八十条":["第八十条 销售不知道是侵犯注册商标专用权的商品，能证明该商品是自己合法取得并说明提供者的，由工商行政管理部门责令停止销售，并将案件情况通报侵权商品提供者所在地工商行政管理部门。","ff0536ea95","中华人民共和国商标法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNlOTc4NDAxNmY0MjRmZjNhZDA0ZTk=",0,"现行有效","2014-04-29",[]],"电子商务法|第四条":["第四条 国家平等对待线上线下商务活动，促进线上线下融合发展，各级人民政府和有关部门不得采取歧视性的政策措施，不得滥用行政权力排除、限制市场竞争。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第五条":["第五条 电子商务经营者从事经营活动，应当遵循自愿、平等、公平、诚信的原则，遵守法律和商业道德，公平参与市场竞争，履行消费者权益保护、环境保护、知识产权保护、网络安全与个人信息保护等方面的义务，承担产品和服务质量责任，接受政府和社会的监督。第67页,共1715页","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第十条":["第十条 电子商务经营者应当依法办理市场主体登记。但是，个人销售自产农副产品、家庭手工业产品，个人利用自己的技能从事依法无须取得许可的便民劳务活动和零星小额交易活动，以及依照法律、行政法规不需要进行登记的除外。第68页,共1715页","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第十一条":["第十一条 电子商务经营者应当依法履行纳税义务，并依法享受税收优惠。依照前条规定不需要办理市场主体登记的电子商务经营者在首次纳税义务发生后，应当依照税收征收管理法律、行政法规的规定申请办理税务登记，并如实申报纳税。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第十二条":["第十二条 电子商务经营者从事经营活动，依法需要取得相关行政许可的，应当依法取得行政许可。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第七十六条":["第七十六条 电子商务经营者违反本法规定，有下列行为之一的，由市场监督管理部门责令限期改正，可以处一万元以下的罚款，对其中的电子商务平台经营者，依照本法第八十一条第一款的规定处罚：\n（一）未在首页显著位置公示营业执照信息、行政许可信息、属于不需要办理市场主体登记情形等信息，或者上述信息的链接标识的；\n（二）未在首页显著位置持续公示终止电子商务的有关信息的；\n（三）未明示用户信息查询、更正、删除以及用户注销的方式、程序，或者对用户信息查询、更正、删除以及用户注销设置不合理条件的。电子商务平台经营者对违反前款规定的平台内经营者未采取必要措施的，由市场监督管理部门责令限期改正，可以处二万元以上十万元以下的罚款。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第七十七条":["第七十七条 电子商务经营者违反本法第十八条第一款规定提供搜索结果，或者违反本法第十九条规定搭售商品、服务的，由市场监督管理部门责令限期改正，没收违法所得，可以并处五万元以上二十万元以下的罚款；情节严重的，并处二十万元以上五十万元以下的罚款。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"电子商务法|第七十八条":["第七十八条 电子商务经营者违反本法第二十一条规定，未向消费者明示押金退还的方式、程序，对押金退还设置不合理条件，或者不及时退还押金的，由有关主管部门责令限期改正，可以处五万元以上二十万元以下的罚款；情节严重的，处二十万元以上五十万元以下的罚款。","1b06ceabbc","中华人民共和国电子商务法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2019-01-01",[]],"个人信息保护法|第二条":["第二条 自然人的个人信息受法律保护，任何组织、个人不得侵害自然人的个人信息权益。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第五条":["第五条 处理个人信息应当遵循合法、正当、必要和诚信原则，不得通过误导、欺诈、胁迫等方式处理个人信息。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第六条":["第六条 处理个人信息应当具有明确、合理的目的，并应当与处理目的直接相关，采取对个人权益影响最小的方式。收集个人信息，应当限于实现处理目的的最小范围，不得过度收集个人信息。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第七条":["第七条 处理个人信息应当遵循公开、透明原则，公开个人信息处理规则，明示处理的目的、方式和范围。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第八条":["第八条 处理个人信息应当保证个人信息的质量，避免因个人信息不准确、不完整对个人权益造成不利影响。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"个人信息保护法|第六十八条":["第六十八条 国家机关不履行本法规定的个人信息保护义务的，由其上级机关或者履行个人信息保护职责的部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分。履行个人信息保护职责的部门的工作人员玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予处分。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"标准化法|第三条":["第三条 标准化工作的任务是制定标准、组织实施标准以及对标准的制定、实施进行监督。\n县级以上人民政府应当将标准化工作纳入本级国民经济和社会发展规划，将标准化工作经费纳入本级预算。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第四条":["第四条 制定标准应当在科学技术研究成果和社会实践经验的基础上，深入调查论证，广泛征求意见，保证标准的科学性、规范性、时效性，提高标准质量。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第十条":["第十条 对保障人身健康和生命财产安全、国家安全、生态环境安全以及满足经济社会管理基本需要的技术要求，应当制定强制性国家标准。\n国务院有关行政主管部门依据职责负责强制性国家标准的项目提出、组织起草、征求意见和技术审查。国务院标准化行政主管部门负责强制性国家标准的立项、编号和对外通报。国务院标准化行政主管部门应当对拟制定的强制性国家标准是否符合前款规定进行立项审查，对符合前款规定的予以立项。\n省、自治区、直辖市人民政府标准化行政主管部门可以向国务院标准化行政主管部门提出强制性国家标准的立项建议，由国务院标准化行政主管部门会同国务院有关行政主管部门决定。社会团体、企业事业组织以及公民可以向国务院标准化行政主管部门提出强制性国家标准的立项建议，国务院标准化行政主管部门认为需要立项的，会同国务院有关行政主管部门决定。\n强制性国家标准由国务院批准发布或者授权批准发布。\n法律、行政法规和国务院决定对强制性标准的制定另有规定的，从其规定。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第十四条":["第十四条 对保障人身健康和生命财产安全、国家安全、生态环境安全以及经济社会发展所急需的标准项目，制定标准的行政主管部门应当优先立项并及时完成。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第十五条":["第十五条 制定强制性标准、推荐性标准，应当在立项时对有关行政主管部门、企业、社会团体、消费者和教育、科研机构等方面的实际需求进行调查，对制定标准的必要性、可行性进行论证评估；在制定过程中，应当按照便捷有效的原则采取多种方式征求意见，组织对标准相关事项进行调查分析、实验、论证，并做到有关标准之间的协调配套。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第三十八条":["第三十八条 企业未依照本法规定公开其执行的标准的，由标准化行政主管部门责令限期改正；逾期不改正的，在标准信息公共服务平台上公示。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第三十九条":["第三十九条 国务院有关行政主管部门、设区的市级以上地方人民政府标准化行政主管部门制定的标准不符合本法第二十一条第一款、第二十二条第一款规定的，应当及时改正；拒不改正的，由国务院标准化行政主管部门公告废止相关标准；对负有责任的领导人员和直接责任人员依法给予处分。\n社会团体、企业制定的标准不符合本法第二十一条第一款、第二十二条第一款规定的，由标准化行政主管部门责令限期改正；逾期不改正的，由省级以上人民政府标准化行政主管部门废止相关标准，并在标准信息公共服务平台上公示。\n违反本法第二十二条第二款规定，利用标准实施排除、限制市场竞争行为的，依照《中华人民共和国反垄断法》等法律、行政法规的规定处理。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法|第四十二条":["第四十二条 社会团体、企业未依照本法规定对团体标准或者企业标准进行编号的，由标准化行政主管部门责令限期改正；逾期不改正的，由省级以上人民政府标准化行政主管部门撤销相关标准编号，并在标准信息公共服务平台上公示。","b5beafbd3e","中华人民共和国标准化法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY4NzY0MzBhOTE=",0,"现行有效","2018-01-01",[]],"标准化法实施条例|第二条":["第二条 对下列需要统一的技术要求，应当制定标准：\n（一）工业产品的品种、规格、质量、等级或者安全、卫生要求；\n（二）工业产品的设计、生产、试验、检验、包装、储存、运输、使用的方法或者生产、储存、运输过程中的安全、卫生要求；\n（三）有关环境保护的各项技术要求和检验方法；\n（四）建设工程的勘察、设计、施工、验收的技术要求和方法；\n（五）有关工业生产、工程建设和环境保护的技术术语、符号、代号、制图方法、互换配合要求；\n（六）农业（含林业、牧业、渔业，下同）产品（含种子、种苗、种畜、种禽，下同）的品种、规格、质量、等级、检验、包装、储存、运输以及生产技术、管理技术的要求；\n（七）信息、能源、资源、交通运输的技术要求。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第三条":["第三条 国家有计划地发展标准化事业。标准化工作应当纳入各级国民经济和社会发展计划。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第十一条":["第十一条 对需要在全国范围内统一的下列技术要求，应当制定国家标准（含标准样品的制作）：\n（一）互换配合、通用技术语言要求；\n（二）保障人体健康和人身、财产安全的技术要求；\n（三）基本原料、燃料、材料的技术要求；\n（四）通用基础件的技术要求；\n（五）通用的试验、检验方法；\n（六）通用的管理技术要求；\n（七）工程建设的重要技术要求；\n（八）国家需要控制的其他重要产品的技术要求。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第十七条":["第十七条 企业生产的产品没有国家标准、行业标准和地方标准的，应当制定相应的企业标准，作为组织生产的依据。企业标准由企业组织制定（农业企业标准制定办法另定），并按省、自治区、直辖市人民政府的规定备案。\n对已有国家标准、行业标准或者地方标准的，鼓励企业制定严于国家标准、行业标准或者地方标准要求的企业标准，在企业内部适用。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第十九条":["第十九条 制定标准应当发挥行业协会、科学技术研究机构和学术团体的作用。\n制定国家标准、行业标准和地方标准的部门应当组织由用户、生产单位、行业协会、科学技术研究机构、学术团体及有关部门的专家组成标准化技术委员会，负责标准草拟和参加标准草案的技术审查工作。未组成标准化技术委员会的，可以由标准化技术归口单位负责标准草拟和参加标准草案的技术审查工作。\n制定企业标准应当充分听取使用单位、科学技术研究机构的意见。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第三十二条":["第三十二条 违反《标准化法》和本条例有关规定，有下列情形之一的，由标准化行政主管部门或有关行政主管部门在各自的职权范围内责令限期改进，并可通报批评：\n（一）企业未按规定制定标准作为组织生产依据的；\n（二）企业未按规定要求将产品标准上报备案的；\n（三）企业的产品未按规定附有标识或与其标识不符的；\n（四）企业研制新产品、改进产品、进行技术改造，不符合标准化要求的；\n（五）科研、设计、生产中违反有关强制性标准规定的。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第三十三条":["第三十三条 生产不符合强制性标准的产品的，应当责令其停止生产，并没收产品，监督销毁或作必要技术处理；处以该批产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。\n销售不符合强制性标准的商品的，应当责令其停止销售，并限期追回已售出的商品，监督销毁或作必要技术处理；没收违法所得；处以该批商品货值金额百分之十至百分之二十的罚款；对有关责任者处以五千元以下罚款。\n进口不符合强制性标准的产品的，应当封存并没收该产品，监督销毁或作必要技术处理；处以进口产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。\n本条规定的责令停止生产，由有关行政主管部门决定；其他行政处罚由市场监督管理部门决定。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"标准化法实施条例|第三十五条":["第三十五条 当事人对没收产品、没收违法所得和罚款的处罚不服的，可以在接到处罚通知之日起十五日内，向作出处罚决定的机关的上一级机关申请复议；对复议决定不服的，可以在接到复议决定之日起十五日内，向人民法院起诉。当事人也可以在接到处罚通知之日起十五日内，直接向人民法院起诉。当事人逾期不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。","bcd1408c62","中华人民共和国标准化法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzQ2ZjliYjAxOWNkMTkwZjY4MTZjODQ=",0,"现行有效","2024-05-01",[]],"药品管理法实施条例|第二条":["第二条 从事药品研制、生产、经营、使用和监督管理活动，应当坚持以人民健康为中心，遵循科学规律和伦理原则，全面防控风险。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第六条":["第六条 从事药品研制活动，应当遵守药物非临床研究质量管理规范、药物临床试验质量管理规范，保证记录和数据真实、准确、完整和可追溯。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第七条":["第七条 以申请药品注册为目的开展药物非临床安全性评价研究活动的，应当由经过资格认定的药物非临床安全性评价研究机构实施。申请药物非临床安全性评价研究机构资格认定应当向国务院药品监督管理部门提出申请，提交证明其符合药物非临床研究质量管理规范的资料。国务院药品监督管理部门应当组织开展审查，并自受理申请之日起20个工作日内作出决定。对符合规定条件的，准予许可并发给资格证书；对不符合规定条件的，不予许可并书面说明理由。\n药物非临床安全性评价研究机构资格证书有效期为5年。有效期届满，需要继续实施药物非临床安全性评价研究的，应当申请重新核发资格证书。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第八条":["第八条 药物临床试验申办者应当选择具备相应能力的药物临床试验机构和研究者，并履行受试者保护、临床试验用药品管理、临床试验数据管理、风险管理等责任。\n临床试验用药品的制备，应当符合药品生产质量管理规范的有关要求。\n药物临床试验申办者、药物临床试验机构不得向受试者收取与临床试验有关的费用。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第九条":["第九条 依照药品管理法第十九条第一款规定批准开展的药物临床试验变更申办者的，应当向国务院药品监督管理部门提出申请。国务院药品监督管理部门应当自受理申请之日起20个工作日内进行审查并作出决定。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第七十九条":["第七十九条 有下列情形之一的，由县级以上地方人民政府药品监督管理部门责令限期改正，没收违法生产、销售的药品和违法所得，并处违法生产、销售的药品货值金额10倍以上20倍以下的罚款，违法生产、批发的药品货值金额不足10万元的，按10万元计算，违法零售的药品货值金额不足1万元的，按1万元计算；情节严重的，还应当责令停产停业整顿直至由原发证部门吊销药品生产许可证、药品经营许可证：\n（一）药品上市许可持有人违反本条例第三十六条规定销售取得药品批准证明文件前生产的商业规模批次产品；\n（二）中药饮片生产企业委托炮制中药饮片或者中药配方颗粒生产企业委托生产中药配方颗粒；\n（三）药品经营企业经营中药配方颗粒、医疗机构制剂；\n（四）违反本条例第四十六条规定通过网络销售药品。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第八十条":["第八十条 有下列情形之一的，由省级人民政府药品监督管理部门责令限期改正，给予警告；逾期不改正的，处10万元以上50万元以下的罚款：\n（一）中药饮片生产企业、中药配方颗粒生产企业跨省级行政区域销售中药饮片、中药配方颗粒未依照本条例第三十九条第三款、第四十条第四款规定备案；\n（二）中药配方颗粒生产企业生产中药配方颗粒未依照本条例第四十条第一款规定备案。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"药品管理法实施条例|第八十一条":["第八十一条 医疗机构未经批准使用其他医疗机构配制的制剂的，依照药品管理法第一百二十九条、第一百三十九条规定予以处罚。\n医疗机构有下列情形之一的，由县级以上地方人民政府药品监督管理部门责令限期改正；逾期不改正的，处1万元以上10万元以下的罚款：\n（一）未按照规定制定并实施药品进货检查验收、保管、使用等管理制度；\n（二）发现购进、使用的药品存在质量问题，未按照规定采取措施或者报告。","fa7ac3e44a","中华人民共和国药品管理法实施条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5YzIzMGZmMjAxOWMyYjYzZmFlYzQwYmY=",0,"现行有效","2026-05-15",[]],"互联网广告管理办法|第三条":["第三条 互联网广告应当真实、合法，坚持正确导向，以健康的表现形式表达广告内容，符合社会主义精神文明建设和弘扬中华优秀传统文化的要求。利用互联网从事广告活动，应当遵守法律、法规，诚实信用，公平竞争。国家鼓励、支持开展互联网公益广告宣传活动，传播社会主义核心价值观和中华优秀传统文化，倡导文明风尚。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第四条":["第四条 利用互联网为广告主或者广告主委托的广告经营者发布广告的自然人、法人或者其他组织，适用广告法和本办法关于广告发布者的规定。利用互联网提供信息服务的自然人、法人或者其他组织，适用广告法和本办法关于互联网信息服务提供者的规定；从事互联网广告设计、制作、代理、发布等活动的，应当适用广告法和本办法关于广告经营者、广告发布者等主体的规定。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第六条":["第六条 法律、行政法规规定禁止生产、销售的产品或者提供的服务，以及禁止发布广告的商品或者服务，任何单位或者个人不得利用互联网设计、制作、代理、发布广告。禁止利用互联网发布烟草（含电子烟）广告。禁止利用互联网发布处方药广告，法律、行政法规另有规定的，依照其规定。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第七条":["第七条 发布医疗、药品、医疗器械、农药、兽药、保健食品、特殊医学用途配方食品广告等法律、行政法规规定应当进行审查的广告，应当在发布前由广告审查机关对广告内容进行审查；未经审查，不得发布。对须经审查的互联网广告，应当严格按照审查通过的内容发布，不得剪辑、拼接、修改。已经审查通过的广告内容需要改动的，应当重新申请广告审查。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第八条":["第八条 禁止以介绍健康、养生知识等形式，变相发布医疗、药品、医疗器械、保健食品、特殊医学用途配方食品广告。介绍健康、养生知识的，不得在同一页面或者同时出现相关医疗、药品、医疗器械、保健食品、特殊医学用途配方食品的商品经营者或者服务提供者地址、联系方式、购物链接等内容。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第二十六条":["第二十六条 违反本办法第十条规定，以弹出等形式发布互联网广告，未显著标明关闭标志，确保一键关闭的，依照广告法第六十二条第二款规定予以处罚。广告发布者实施前款规定行为的，由县级以上市场监督管理部门责令改正，拒不改正的，处五千元以上三万元以下的罚款。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第二十七条":["第二十七条 违反本办法第十一条规定，欺骗、误导用户点击、浏览广告的，法律、行政法规有规定的，依照其规定；法律、行政法规没有规定的，由县级以上市场监督管理部门责令改正，对广告主、广告经营者、广告发布者处五千元以上三万元以下的罚款。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"互联网广告管理办法|第二十八条":["第二十八条 违反本办法第十四条第一款、第十五条、第十八条规定，广告经营者、广告发布者未按规定建立、健全广告业务管理制度的，或者未对广告内容进行核对的，依据广告法第六十条第一款规定予以处罚。违反本办法第十三条第四款、第十五条、第十八条规定，广告主未按规定建立广告档案，或者未对广告内容进行核对的，由县级以上市场监督管理部门责令改正，可以处五万元以下的罚款。广告主、广告经营者、广告发布者能够证明其已履行相关责任、采取措施防止链接的广告内容被篡改，并提供违法广告活动主体的真实名称、地址和有效联系方式的，可以依法从轻、减轻或者不予行政处罚。违反本办法第十四条第三款，广告经营者、广告发布者拒不配合市场监督管理部门开展的互联网广告行业调查，或者提供虚假资料的，由县级以上市场监督管理部门责令改正，可以处一万元以上三万元以下的罚款。","957898566a","互联网广告管理办法","https://www.gov.cn/gongbao/2023/issue_10506/202306/content_6885261.html",0,"现行有效","2023-05-01",[]],"数据安全法|第四条":["第四条 维护数据安全，应当坚持总体国家安全观，建立健全数据安全治理体系，提高数据安全保障能力。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第八条":["第八条 开展数据处理活动，应当遵守法律、法规，尊重社会公德和伦理，遵守商业道德和职业道德，诚实守信，履行数据安全保护义务，承担社会责任，不得危害国家安全、公共利益，不得损害个人、组织的合法权益。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第十二条":["第十二条 任何个人、组织都有权对违反本法规定的行为向有关主管部门投诉、举报。收到投诉、举报的部门应当及时依法处理。有关主管部门应当对投诉、举报人的相关信息予以保密，保护投诉、举报人的合法权益。\n第二章 数据安全与发展","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第十四条":["第十四条 国家实施大数据战略，推进数据基础设施建设，鼓励和支持数据在各行业、各领域的创新应用。\n省级以上人民政府应当将数字经济发展纳入本级国民经济和社会发展规划，并根据需要制定数字经济发展规划。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第十五条":["第十五条 国家支持开发利用数据提升公共服务的智能化水平。提供智能化公共服务，应当充分考虑老年人、残疾人的需求，避免对老年人、残疾人的日常生活造成障碍。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第四十五条":["第四十五条 开展数据处理活动的组织、个人不履行本法第二十七条、第二十九条、第三十条规定的数据安全保护义务的，由有关主管部门责令改正，给予警告，可以并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员可以处一万元以上十万元以下罚款；拒不改正或者造成大量数据泄露等严重后果的，处五十万元以上二百万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下罚款。违反国家核心数据管理制度，危害国家主权、安全和发展利益的，由有关主管部门处二百万元以上一千万元以下罚款，并根据情况责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照；构成犯罪的，依法追究刑事责任。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第四十六条":["第四十六条 违反本法第三十一条规定，向境外提供重要数据的，由有关主管部门责令改正，给予警告，可以并处十万元以上一百万元以下罚款，对直接负责的主管人员和其他直接责任人员可以处一万元以上十万元以下罚款；情节严重的，处一百万元以上一千万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处十万元以上一百万元以下罚款。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"数据安全法|第四十七条":["第四十七条 从事数据交易中介服务的机构未履行本法第三十三条规定的义务的，由有关主管部门责令改正，没收违法所得，处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足十万元的，处十万元以上一百万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。","a50ea6442e","中华人民共和国数据安全法","http://www.npc.gov.cn/npc/c2/c30834/202106/t20210610_311888.html",0,"现行有效","2021-09-01",[]],"网络安全法|第九条":["第九条 网络运营者开展经营和服务活动，必须遵守法律、行政法规，尊重社会公德，遵守商业道德，诚实信用，履行网络安全保护义务，接受政府和社会的监督，承担社会责任。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第十条":["第十条 建设、运营网络或者通过网络提供服务，应当依照法律、行政法规的规定和国家标准的强制性要求，采取技术措施和其他必要措施，保障网络安全、稳定运行，有效应对网络安全事件，防范网络违法犯罪活动，维护网络数据的完整性、保密性和可用性。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第十二条":["第十二条 国家保护公民、法人和其他组织依法使用网络的权利，促进网络接入普及，提升网络服务水平，为社会提供安全、便利的网络服务，保障网络信息依法有序自由流动。任何个人和组织使用网络应当遵守宪法法律，遵守公共秩序，尊重社会公德，不得危害网络安全，不得利用网络从事危害国家安全、荣誉和利益，煽动颠覆国家政权、推翻社会主义制度，煽动分裂国家、破坏国家统一，宣扬恐怖主义、极端主义，宣扬民族仇恨、民族歧视，传播暴力、淫秽色情信息，编造、传播虚假信息扰乱经济秩序和社会秩序，以及侵害他人名誉、隐私、知识产权和其他合法权益等活动。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第十四条":["第十四条 任何个人和组织有权对危害网络安全的行为向网信、电信、公安等部门举报。收到举报的部门应当及时依法作出处理；不属于本部门职责的，应当及时移送有权处理的部门。有关部门应当对举报人的相关信息予以保密，保护举报人的合法权益。\n第二章 网络安全支持与促进","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第五十九条":["第五十九条 网络运营者不履行本法第二十一条、第二十五条规定的网络安全保护义务的，由有关主管部门责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处一万元以上十万元以下罚款，对直接负责的主管人员处五千元以上五万元以下罚款。关键信息基础设施的运营者不履行本法第三十三条、第三十四条、第三十六条、第三十八条规定的网络安全保护义务的，由有关主管部门责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处十万元以上一百万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第六十条":["第六十条 违反本法第二十二条第一款、第二款和第四十八条第一款规定，有下列行为之一的，由有关主管部门责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处五万元以上五十万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款：\n（一）设置恶意程序的；\n（二）对其产品、服务存在的安全缺陷、漏洞等风险未立即采取补救措施，或者未按照规定及时告知用户并向有关主管部门报告的；\n（三）擅自终止为其产品、服务提供安全维护的。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络安全法|第六十一条":["第六十一条 网络运营者违反本法第二十四条第一款规定，未要求用户提供真实身份信息，或者对不提供真实身份信息的用户提供相关服务的，由有关主管部门责令改正；拒不改正或者情节严重的，处五万元以上五十万元以下罚款，并可以由有关主管部门责令暂停相关业务、停业整顿、关闭网站、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"网络反不正当竞争暂行规定|第二条":["第二条 鼓励和支持经营者依法开展经营活动，公平参与市场竞争。经营者通过互联网等信息网络（以下简称网络）从事生产经营活动，应当遵循自愿、平等、公平、诚信的原则，遵守法律法规规章，遵守商业道德。经营者不得实施网络不正当竞争行为，扰乱市场竞争秩序，影响市场公平交易，损害其他经营者或者消费者的合法权益。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"网络反不正当竞争暂行规定|第三条":["第三条 国家市场监督管理总局负责监督指导全国网络反不正当竞争工作，组织查处全国范围内有重大影响的网络不正当竞争案件。县级以上地方市场监督管理部门依法对网络不正当竞争行为进行查处。市场监督管理部门在查处违法行为过程中，应当坚持依法行政，保证严格、规范、公正、文明执法。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"网络反不正当竞争暂行规定|第五条":["第五条 国家鼓励、支持和保护一切组织和个人对网络不正当竞争行为进行社会监督。对涉嫌网络不正当竞争行为，任何单位和个人有权依法向市场监督管理部门举报，市场监督管理部门接到举报后应当及时处理。行业组织应当加强行业自律，引导、规范会员依法合规竞争。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"网络反不正当竞争暂行规定|第六条":["第六条 平台经营者应当加强对平台内竞争行为的规范管理，发现平台内经营者采取不正当竞争方式，违法销售商品、提供服务，或者侵害消费者合法权益的行为，应当及时采取必要的处置措施，保存有关记录，并按规定向平台经营者住所地县级以上市场监督管理部门报告。记录保存时间自作出处置措施之日起计算，不少于三年。\n第二章 网络不正当竞争行为","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"网络反不正当竞争暂行规定|第八条":["第八条 经营者不得采取下列方式，对商品生产经营主体以及商品性能、功能、质量、来源、曾获荣誉、资格资质等作虚假或者引人误解的商业宣传，欺骗、误导消费者或者相关公众：\n（一）通过网站、客户端、小程序、公众号等进行展示、演示、说明、解释、推介或者文字标注；\n（二）通过直播、平台推荐、网络文案等方式，实施商业营销活动；\n（三）通过热搜、热评、热转、榜单等方式，实施商业营销活动；\n（四）其他虚假或者引人误解的商业宣传。经营者不得帮助其他经营者实施前款虚假或者引人误解的商业宣传行为。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"网络食品安全违法行为查处办法|第四条":["第四条 网络食品交易第三方平台提供者和入网食品生产经营者应当履行法律、法规和规章规定的食品安全义务。\n网络食品交易第三方平台提供者和入网食品生产经营者应当对网络食品安全信息的真实性负责。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第五条":["第五条 网络食品交易第三方平台提供者和入网食品生产经营者应当配合食品药品监督管理部门对网络食品安全违法行为的查处，按照食品药品监督管理部门的要求提供网络食品交易相关数据和信息。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第八条":["第八条 网络食品交易第三方平台提供者应当在通信主管部门批准后30个工作日内，向所在地省级食品药品监督管理部门备案，取得备案号。\n通过自建网站交易的食品生产经营者应当在通信主管部门批准后30个工作日内，向所在地市、县级食品药品监督管理部门备案，取得备案号。\n省级和市、县级食品药品监督管理部门应当自完成备案后7个工作日内向社会公开相关备案信息。\n备案信息包括域名、IP地址、电信业务经营许可证、企业名称、法定代表人或者负责人姓名、备案号等。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第九条":["第九条 网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者应当具备数据备份、故障恢复等技术条件，保障网络食品交易数据和资料的可靠性与安全性。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第十条":["第十条 网络食品交易第三方平台提供者应当建立入网食品生产经营者审查登记、食品安全自查、食品安全违法行为制止及报告、严重违法行为平台服务停止、食品安全投诉举报处理等制度，并在网络平台上公开。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第十五条":["第十五条 网络食品交易第三方平台提供者发现入网食品生产经营者有下列严重违法行为之一的，应当停止向其提供网络交易平台服务：\n（一）入网食品生产经营者因涉嫌食品安全犯罪被立案侦查或者提起公诉的；\n（二）入网食品生产经营者因食品安全相关犯罪被人民法院判处刑罚的；\n（三）入网食品生产经营者因食品安全违法行为被公安机关拘留或者给予其他治安管理处罚的；\n（四）入网食品生产经营者被食品药品监督管理部门依法作出吊销许可证、责令停产停业等处罚的。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第二十九条":["第二十九条 违反本办法第八条规定，网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者未履行相应备案义务的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络食品安全违法行为查处办法|第三十条":["第三十条 违反本办法第九条规定，网络食品交易第三方平台提供者和通过自建网站交易的食品生产经营者不具备数据备份、故障恢复等技术条件，不能保障网络食品交易数据和资料的可靠性与安全性的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处3万元罚款。","05b145c68c","网络食品安全违法行为查处办法","https://www.gov.cn/gongbao/content/2017/content_5174527.htm",0,"现行有效","2016-10-01",[]],"网络餐饮服务食品安全监督管理办法|第四条":["第四条 入网餐饮服务提供者应当具有实体经营门店并依法取得食品经营许可证，并按照食品经营许可证载明的主体业态、经营项目从事经营活动，不得超范围经营。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第五条":["第五条 网络餐饮服务第三方平台提供者应当在通信主管部门批准后30个工作日内，向所在地省级食品药品监督管理部门备案。自建网站餐饮服务提供者应当在通信主管部门备案后30个工作日内，向所在地县级食品药品监督管理部门备案。备案内容包括域名、IP地址、电信业务经营许可证或者备案号、企业名称、地址、法定代表人或者负责人姓名等。网络餐饮服务第三方平台提供者设立从事网络餐饮服务分支机构的，应当在设立后30个工作日内，向所在地县级食品药品监督管理部门备案。备案内容包括分支机构名称、地址、法定代表人或者负责人姓名等。食品药品监督管理部门应当及时向社会公开相关备案信息。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第六条":["第六条 网络餐饮服务第三方平台提供者应当建立并执行入网餐饮服务提供者审查登记、食品安全违法行为制止及报告、严重违法行为平台服务停止、食品安全事故处置等制度，并在网络平台上公开相关制度。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第七条":["第七条 网络餐饮服务第三方平台提供者应当设置专门的食品安全管理机构，配备专职食品安全管理人员，每年对食品安全管理人员进行培训和考核。培训和考核记录保存期限不得少于两年。经考核不具备食品安全管理能力的，不得上岗。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第八条":["第八条 网络餐饮服务第三方平台提供者应当对入网餐饮服务提供者的食品经营许可证进行审查，登记入网餐饮服务提供者的名称、地址、法定代表人或者负责人及联系方式等信息，保证入网餐饮服务提供者食品经营许可证载明的经营场所等许可信息真实。网络餐饮服务第三方平台提供者应当与入网餐饮服务提供者签订食品安全协议，明确食品安全责任。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第二十八条":["第二十八条 违反本办法第五条规定，网络餐饮服务第三方平台提供者以及分支机构或者自建网站餐饮服务提供者未履行相应备案义务的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第二十九条":["第二十九条 违反本办法第六条规定，网络餐饮服务第三方平台提供者未按要求建立、执行并公开相关制度的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"网络餐饮服务食品安全监督管理办法|第三十条":["第三十条 违反本办法第七条规定，网络餐饮服务第三方平台提供者未设置专门的食品安全管理机构，配备专职食品安全管理人员，或者未按要求对食品安全管理人员进行培训、考核并保存记录的，由县级以上地方食品药品监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。","71102a6add","网络餐饮服务食品安全监督管理办法","https://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2532108.html",0,"现行有效","2018-01-01",[]],"公平竞争审查条例|第二条":["第二条 起草涉及经营者经济活动的法律、行政法规、地方性法规、规章、规范性文件以及具体政策措施（以下统称政策措施），行政机关和法律、法规授权的具有管理公共事务职能的组织（以下统称起草单位）应当依照本条例规定开展公平竞争审查。","0167885062","公平竞争审查条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MDE0ZTk5YTAxOTAyNWI4Y2RkMjQ5ZmQ=",0,"现行有效","2024-08-01",[]],"公平竞争审查条例|第八条":["第八条 起草单位起草的政策措施，不得含有下列限制或者变相限制市场准入和退出的内容：\n（一）对市场准入负面清单以外的行业、领域、业务等违法设置审批程序；\n（二）违法设置或者授予特许经营权；\n（三）限定经营、购买或者使用特定经营者提供的商品或者服务（以下统称商品）；\n（四）设置不合理或者歧视性的准入、退出条件；\n（五）其他限制或者变相限制市场准入和退出的内容。","0167885062","公平竞争审查条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MDE0ZTk5YTAxOTAyNWI4Y2RkMjQ5ZmQ=",0,"现行有效","2024-08-01",[]],"公平竞争审查条例|第九条":["第九条 起草单位起草的政策措施，不得含有下列限制商品、要素自由流动的内容：\n（一）限制外地或者进口商品、要素进入本地市场，或者阻碍本地经营者迁出，商品、要素输出；\n（二）排斥、限制、强制或者变相强制外地经营者在本地投资经营或者设立分支机构；\n（三）排斥、限制或者变相限制外地经营者参加本地政府采购、招标投标；\n（四）对外地或者进口商品、要素设置歧视性收费项目、收费标准、价格或者补贴；\n（五）在资质标准、监管执法等方面对外地经营者在本地投资经营设置歧视性要求；\n（六）其他限制商品、要素自由流动的内容。","0167885062","公平竞争审查条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MDE0ZTk5YTAxOTAyNWI4Y2RkMjQ5ZmQ=",0,"现行有效","2024-08-01",[]],"公平竞争审查条例|第十一条":["第十一条 起草单位起草的政策措施，不得含有下列影响生产经营行为的内容：\n（一）强制或者变相强制经营者实施垄断行为，或者为经营者实施垄断行为提供便利条件；\n（二）超越法定权限制定政府指导价、政府定价，为特定经营者提供优惠价格；\n（三）违法干预实行市场调节价的商品、要素的价格水平；\n（四）其他影响生产经营行为的内容。","0167885062","公平竞争审查条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MDE0ZTk5YTAxOTAyNWI4Y2RkMjQ5ZmQ=",0,"现行有效","2024-08-01",[]],"反食品浪费法|第六条":["第六条 机关、人民团体、国有企业事业单位应当按照国家有关规定，细化完善公务接待、会议、培训等公务活动用餐规范，加强管理，带头厉行节约，反对浪费。\n公务活动需要安排用餐的，应当根据实际情况，节俭安排用餐数量、形式，不得超过规定的标准。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第七条":["第七条 餐饮服务经营者应当采取下列措施，防止食品浪费：\n（一）建立健全食品采购、储存、加工管理制度，加强服务人员职业培训，将珍惜粮食、反对浪费纳入培训内容；\n（二）主动对消费者进行防止食品浪费提示提醒，在醒目位置张贴或者摆放反食品浪费标识，或者由服务人员提示说明，引导消费者按需适量点餐；\n（三）提升餐饮供给质量，按照标准规范制作食品，合理确定数量、分量，提供小份餐等不同规格选择；\n（四）提供团体用餐服务的，应当将防止食品浪费理念纳入菜单设计，按照用餐人数合理配置菜品、主食；\n（五）提供自助餐服务的，应当主动告知消费规则和防止食品浪费要求，提供不同规格餐具，提醒消费者适量取餐。\n餐饮服务经营者不得诱导、误导消费者超量点餐。\n餐饮服务经营者可以通过在菜单上标注食品分量、规格、建议消费人数等方式充实菜单信息，为消费者提供点餐提示，根据消费者需要提供公勺公筷和打包服务。\n餐饮服务经营者可以对参与“光盘行动”的消费者给予奖励；也可以对造成明显浪费的消费者收取处理厨余垃圾的相应费用，收费标准应当明示。\n餐饮服务经营者可以运用信息化手段分析用餐需求，通过建设中央厨房、配送中心等措施，对食品采购、运输、储存、加工等进行科学管理。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第八条":["第八条 设有食堂的单位应当建立健全食堂用餐管理制度，制定、实施防止食品浪费措施，加强宣传教育，增强反食品浪费意识。\n单位食堂应当加强食品采购、储存、加工动态管理，根据用餐人数采购、做餐、配餐，提高原材料利用率和烹饪水平，按照健康、经济、规范的原则提供饮食，注重饮食平衡。\n单位食堂应当改进供餐方式，在醒目位置张贴或者摆放反食品浪费标识，引导用餐人员适量点餐、取餐；对有浪费行为的，应当及时予以提醒、纠正。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第九条":["第九条 学校应当对用餐人员数量、结构进行监测、分析和评估，加强学校食堂餐饮服务管理；选择校外供餐单位的，应当建立健全引进和退出机制，择优选择。\n学校食堂、校外供餐单位应当加强精细化管理，按需供餐，改进供餐方式，科学营养配餐，丰富不同规格配餐和口味选择，定期听取用餐人员意见，保证菜品、主食质量。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第十条":["第十条 餐饮外卖平台应当以显著方式提示消费者适量点餐。餐饮服务经营者通过餐饮外卖平台提供服务的，应当在平台页面上向消费者提供食品分量、规格或者建议消费人数等信息。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第二十八条":["第二十八条 违反本法规定，餐饮服务经营者未主动对消费者进行防止食品浪费提示提醒的，由县级以上地方人民政府市场监督管理部门或者县级以上地方人民政府指定的部门责令改正，给予警告。\n违反本法规定，餐饮服务经营者诱导、误导消费者超量点餐造成明显浪费的，由县级以上地方人民政府市场监督管理部门或者县级以上地方人民政府指定的部门责令改正，给予警告；拒不改正的，处一千元以上一万元以下罚款。\n违反本法规定，食品生产经营者在食品生产经营过程中造成严重食品浪费的，由县级以上地方人民政府市场监督管理部门或者县级以上地方人民政府指定的部门责令改正，拒不改正的，处五千元以上五万元以下罚款。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第二十九条":["第二十九条 违反本法规定，设有食堂的单位未制定或者未实施防止食品浪费措施的，由县级以上地方人民政府指定的部门责令改正，给予警告。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"反食品浪费法|第三十条":["第三十条 违反本法规定，广播电台、电视台、网络音视频服务提供者制作、发布、传播宣扬量大多吃、暴饮暴食等浪费食品的节目或者音视频信息的，由广播电视、网信等部门按照各自职责责令改正，给予警告；拒不改正或者情节严重的，处一万元以上十万元以下罚款，并可以责令暂停相关业务、停业整顿，对直接负责的主管人员和其他直接责任人员依法追究法律责任。","4ace9e21b9","中华人民共和国反食品浪费法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3OTE5MDRjNjAxNzkyMDVhYjhjZDAyY2M%3D",0,"现行有效","2021-04-29",[]],"零售商品称重计量监督管理办法|第三条":["第三条 零售商品经销者销售商品时，必须使用合格的计量器具，其最大允许误差应当优于或等于所销售商品的负偏差。","631f120cc7","零售商品称重计量监督管理办法","",0,"现行有效","2004-09-01",[]],"零售商品称重计量监督管理办法|第四条":["第四条 零售商品经销者使用称重计量器具当场称重商品，必须按照称重计量器具的实际示值结算，保证商品量计量合格。","631f120cc7","零售商品称重计量监督管理办法","",0,"现行有效","2004-09-01",[]],"零售商品称重计量监督管理办法|第五条":["第五条 零售商品经销者使用称重计量器具每次当场称重商品，在本办法附表1、附表2称重范围内，经核称商品的实际重量值与结算重量值之差不得超过该表规定的负偏差。","631f120cc7","零售商品称重计量监督管理办法","",0,"现行有效","2004-09-01",[]],"零售商品称重计量监督管理办法|第八条":["第八条 被核称商品的含水量及含水量计算应当符合国家标准、行业标准的有关规定。","631f120cc7","零售商品称重计量监督管理办法","",0,"现行有效","2004-09-01",[]],"零售商品称重计量监督管理办法|第九条":["第九条 零售商品经销者不得拒绝市场监督管理部门依法对销售商品的计量监督检查。","631f120cc7","零售商品称重计量监督管理办法","",0,"现行有效","2004-09-01",[]],"食品经营许可和备案管理办法|第三条":["第三条 食品经营许可和备案应当遵循依法、公开、公平、公正、便民、高效的原则。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第五条":["第五条 仅销售预包装食品的，应当报所在地县级以上地方市场监督管理部门备案。仅销售预包装食品的食品经营者在办理备案后，增加其他应当取得食品经营许可的食品经营项目的，应当依法取得食品经营许可；取得食品经营许可之日起备案自行失效。食品经营者已经取得食品经营许可，增加预包装食品销售的，不需要另行备案。已经取得食品生产许可的食品生产者在其生产加工场所或者通过网络销售其生产的预包装食品的，不需要另行备案。医疗机构、药品零售企业销售特殊医学用途配方食品中的特定全营养配方食品不需要备案，但是向医疗机构、药品零售企业销售特定全营养配方食品的经营企业，应当取得食品经营许可或者进行备案。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第六条":["第六条 食品展销会的举办者应当在展销会举办前十五个工作日内，向所在地县级市场监督管理部门报告食品经营区域布局、经营项目、经营期限、食品安全管理制度以及入场食品经营者主体信息核验情况等。法律、法规、规章或者县级以上地方人民政府有规定的，依照其规定。食品展销会的举办者应当依法承担食品安全管理责任，核验并留存入场食品经营者的许可证或者备案情况等信息，明确入场食品经营者的食品安全义务和责任并督促落实，定期对其经营环境、条件进行检查，发现有食品安全违法行为的，应当及时制止并立即报告所在地县级市场监督管理部门。本条规定的展销会包括交易会、博览会、庙会等。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第七条":["第七条 食品经营者在不同经营场所从事食品经营活动的，应当依法分别取得食品经营许可或者进行备案。通过自动设备从事食品经营活动或者仅从事食品经营管理活动的，取得一个经营场所的食品经营许可或者进行备案后，即可在本省级行政区域内的其他经营场所开展已取得许可或者备案范围内的经营活动。利用自动设备跨省经营的，应当分别向经营者所在地和自动设备放置地点所在地省级市场监督管理部门报告。跨省从事食品经营管理活动的，应当分别向经营者所在地和从事经营管理活动所在地省级市场监督管理部门报告。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第十条":["第十条 申请食品经营许可，应当先行取得营业执照等合法主体资格。企业法人、合伙企业、个人独资企业、个体工商户等，以营业执照载明的主体作为申请人。机关、事业单位、社会团体、民办非企业单位、企业等申办食堂，以机关或者事业单位法人登记证、社会团体登记证或者营业执照等载明的主体作为申请人。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第五十二条":["第五十二条 未取得食品经营许可从事食品经营活动的，由县级以上地方市场监督管理部门依照《中华人民共和国食品安全法》第一百二十二条的规定给予处罚。食品经营者地址迁移，不在原许可的经营场所从事食品经营活动，未按照规定重新申请食品经营许可的，或者食品经营许可有效期届满，未按照规定申请办理延续手续，仍继续从事食品经营活动的，由县级以上地方市场监督管理部门依照《中华人民共和国食品安全法》第一百二十二条的规定给予处罚。食品经营许可证载明的主体业态、经营项目等许可事项发生变化，食品经营者未按照规定申请变更的，由县级以上地方市场监督管理部门依照《中华人民共和国食品安全法》第一百二十二条的规定给予处罚。但是，有下列情形之一，依照《中华人民共和国行政处罚法》第三十二条、第三十三条的规定从轻、减轻或者不予行政处罚：\n（一）主体业态、经营项目发生变化，但食品安全风险等级未升高的；\n（二）增加经营项目类型，但增加的经营项目所需的经营条件被已经取得许可的经营项目涵盖的；\n（三）违法行为轻微，未对消费者人身健康和生命安全等造成危害后果的；\n（四）法律、法规、规章规定的其他情形。食品经营许可证载明的除许可事项以外的其他事项发生变化，食品经营者未按照规定申请变更的，由县级以上地方市场监督管理部门责令限期改正；逾期不改的，处一千元以上一万元以下罚款。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第五十四条":["第五十四条 被许可人以欺骗、贿赂等不正当手段取得食品经营许可的，由原发证的市场监督管理部门撤销许可，处一万元以上三万元以下罚款；造成危害后果的，处三万元以上二十万元以下罚款。被许可人在三年内不得再次申请食品经营许可。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"食品经营许可和备案管理办法|第五十六条":["第五十六条 违反本办法第七条第二款、第三款或者第十六条规定的，由县级以上地方市场监督管理部门责令限期改正；逾期不改的，处一千元以上一万元以下罚款。","a27bf81e47","食品经营许可和备案管理办法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_91a91c26ae464a2f898952d5b84f62c6.html",0,"现行有效","2023-12-01",[]],"禁止传销条例|第四条":["第四条 工商行政管理部门、公安机关应当依照本条例的规定，在各自的职责范围内查处传销行为。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第五条":["第五条 工商行政管理部门、公安机关依法查处传销行为，应当坚持教育与处罚相结合的原则，教育公民、法人或者其他组织自觉守法。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第六条":["第六条 任何单位和个人有权向工商行政管理部门、公安机关举报传销行为。工商行政管理部门、公安机关接到举报后，应当立即调查核实，依法查处，并为举报人保密；经调查属实的，依照国家有关规定对举报人给予奖励。\n第二章 传销行为的种类与查处机关","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第十一条":["第十一条 商务、教育、民政、财政、劳动保障、电信、税务等有关部门和单位，应当依照各自职责和有关法律、行政法规的规定配合工商行政管理部门、公安机关查处传销行为。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第十二条":["第十二条 农村村民委员会、城市居民委员会等基层组织，应当在当地人民政府指导下，协助有关部门查处传销行为。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第十四条":["第十四条 县级以上工商行政管理部门对涉嫌传销行为进行查处时，可以采取下列措施：\n(一)责令停止相关活动；\n(二)向涉嫌传销的组织者、经营者和个人调查、了解有关情况；\n(三)进入涉嫌传销的经营场所和培训、集会等活动场所，实施现场检查；\n(四)查阅、复制、查封、扣押涉嫌传销的有关合同、票据、账簿等资料；\n(五)查封、扣押涉嫌专门用于传销的产品(商品)、工具、设备、原材料等财物；\n(六)查封涉嫌传销的经营场所；\n(七)查询涉嫌传销的组织者或者经营者的账户及与存款有关的会计凭证、账簿、对账单等；\n(八)对有证据证明转移或者隐匿违法资金的，可以申请司法机关予以冻结。\n工商行政管理部门采取前款规定的措施，应当向县级以上工商行政管理部门主要负责人书面或者口头报告并经批准。遇有紧急情况需要当场采取前款规定措施的，应当在事后立即报告并补办相关手续；其中，实施前款规定的查封、扣押，以及第(七)项、第(八)项规定的措施，应当事先经县级以上工商行政管理部门主要负责人书面批准。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第二十四条":["第二十四条 有本条例第七条规定的行为，组织策划传销的，由工商行政管理部门没收非法财物，没收违法所得，处50万元以上200万元以下的罚款；构成犯罪的，依法追究刑事责任。\n有本条例第七条规定的行为，介绍、诱骗、胁迫他人参加传销的，由工商行政管理部门责令停止违法行为，没收非法财物，没收违法所得，处10万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。\n有本条例第七条规定的行为，参加传销的，由工商行政管理部门责令停止违法行为，可以处2000元以下的罚款。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"禁止传销条例|第二十五条":["第二十五条 工商行政管理部门依照本条例第二十四条的规定进行处罚时，可以依照有关法律、行政法规的规定，责令停业整顿或者吊销营业执照。","a8569ef322","禁止传销条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE2ZjNjYmIzYzAxNmY0MTI3MGRjMjFhMTI=",0,"现行有效","2005-08-23",[]],"民法通则|第九十九条":["第九十九条 公民享有姓名权，有权决定、使用和依照规定改变自己的姓名，禁止他人干涉、盗用、假冒。\n法人、个体工商户、个人合伙享有名称权。企业法人、个体工商户、个人合伙有权使用、依法转让自己的名称。","4f93807541","中华人民共和国民法通则","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY2NzQ3MTA0MTU=",0,"已废止","2009-08-27",[]],"婚姻法|第二十二条":["第二十二条 子女可以随父姓，可以随母姓。","b919af67e9","中华人民共和国婚姻法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY2MGYwODAyN2I=",0,"已废止","2001-04-28",[]],"民法通则|第一百三十四条":["第一百三十四条 承担民事责任的方式主要有：\n（一）停止侵害；\n（二）排除妨碍；\n（三）消除危险；\n（四）返还财产；\n（五）恢复原状；\n（六）修理、重作、更换；\n（七）赔偿损失；\n（八）支付违约金；\n（九）消除影响、恢复名誉；\n（十）赔礼道歉。\n以上承担民事责任的方式，可以单独适用，也可以合并适用。\n人民法院审理民事案件，除适用上述规定外，还可以予以训诫、责令具结悔过、收缴进行非法活动的财物和非法所得，并可以依照法律规定处以罚款、拘留。\n第七章 诉讼时效","4f93807541","中华人民共和国民法通则","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY2NzQ3MTA0MTU=",0,"已废止","2009-08-27",[]],"网络安全法|第六十四条":["第六十四条 网络运营者、网络产品或者服务的提供者违反本法第二十二条第三款、第四十一条至第四十三条规定，侵害个人信息依法得到保护的权利的，由有关主管部门责令改正，可以根据情节单处或者并处警告、没收违法所\n得、处违法所得一倍以上十倍以下罚款，没有违法所得的，处一百万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款；情节严重的，并可以责令暂停相关业务、停业整顿、关闭网站、吊销相关业务许可证或者吊销营业执照。违反本法第四十四条规定，窃取或者以其他非法方式获取、非法出售或者非法向他人提供个人信息，尚不构成犯罪的，由公安机关没收违法所得，并处违法所得一倍以上十倍以下罚款，没有违法所得的，处一百万元以下罚款。","cfe758ae15","中华人民共和国网络安全法","http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296285.html",0,"现行有效","2017-06-01",[]],"消费者权益保护法|第五十五条":["第五十五条 经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。\n经营者明知商品或者服务存在缺陷，仍然向消费者提供，造成消费者或者其他受害人死亡或者健康严重损害的，受害人有权要求经营者依照本法第四十九条、第五十一条等法律规定赔偿损失，并有权要求所受损失二倍以下的惩罚性赔偿。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"互联网信息服务深度合成管理规定|第十七条":["第十七条深度合成服务提供者应当建立健全辟谣机制，发现深度合成信息服务使用者利用深度合成技术制作、复制、发布、传播虚假信息的，应当及时采取相应的辟谣措施，并将相关信息报网信等部门备案。","a37cd2de4d","互联网信息服务深度合成管理规定","https://www.cac.gov.cn/2022-12/11/c_1672221949354811.htm",0,"现行有效","2023-01-10",[]],"互联网信息服务深度合成管理规定|第十六条":["第十六条互联网应用商店服务提供者应当对深度合成服务提供者提供的深度合成应用程序履行安全管理责任，依法依约核验深度合成应用程序的安全评估、备案等情况；对违反国家有关规定的，应当及时采取不予上架、暂停上架或者下架等处置措施。","a37cd2de4d","互联网信息服务深度合成管理规定","https://www.cac.gov.cn/2022-12/11/c_1672221949354811.htm",0,"现行有效","2023-01-10",[]],"消费者权益保护法|第二十五条":["第二十五条 经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：\n（一）消费者定作的；\n（二）鲜活易腐的；\n（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；\n（四）交付的报纸、期刊。\n除前款所列商品外，其他根据商品性质并经消费者在购买时确认不宜退货的商品，不适用无理由退货。\n消费者退货的商品应当完好。经营者应当自收到退回商品之日起七日内返还消费者支付的商品价款。退回商品的运费由消费者承担；经营者和消费者另有约定的，按照约定。","e34b290428","中华人民共和国消费者权益保护法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NjcwNjA2ZWY=",0,"现行有效","2014-03-15",[]],"上海市检验检测条例|第二十三条":["第二十三条 检验检测机构应当依据相关标准、技术规范或者约定的方法进行检验检测，并出具检验检测报告。检验检测报告应当注明样品获取方式、检验检测依据，以及检验检测数据、结果等信息。\n任何单位和个人不得指使、利诱、胁迫检验检测机构和人员出具虚假检验检测报告。","3e698d7e0b","上海市检验检测条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5NGE1Y2YyOTAxOTU1ZmRjNWYwOTdhNTA=",0,"现行有效","2025-01-01",[]],"江苏省食品小作坊和食品摊贩管理条例|第十条":["第十条 食品小作坊实行登记管理。食品小作坊从事食品生产加工活动，应当依法取得营业执照，并向所在地县级市场监督管理部门申请食品小作坊登记证。申领登记证应当符合下列要求：\n（一）具有与生产加工的食品品种、规模相适应的固定场所和设备、设施；\n（二）具有合理的设备布局和工艺流程；\n（三）具有食品安全管理人员和保证食品安全的管理制度。\n登记证具体申领办法由设区的市、县（市）人民政府确定。","1326fc2f80","江苏省食品小作坊和食品摊贩管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE5MjdmMGU3YjAxOTY3YjdkY2MzNTQ4OTM=",0,"现行有效","2025-03-27",[]],"特种设备安全法|第二十七条":["第二十七条 特种设备销售单位销售的特种设备，应当符合安全技术规范及相关标准的要求，其设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件应当齐全。\n特种设备销售单位应当建立特种设备检查验收和销售记录制度。\n禁止销售未取得许可生产的特种设备，未经检验和检验不合格的特种设备，或者国家明令淘汰和已经报废的特种设备。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"特种设备安全法|第四十五条":["第四十五条 电梯的维护保养应当由电梯制造单位或者依照本法取得许可的安装、改造、修理单位进行。\n电梯的维护保养单位应当在维护保养中严格执行安全技术规范的要求，保证其维护保养的电梯的安全性能，并负责落实现场安全防护措施，保证施工安全。\n电梯的维护保养单位应当对其维护保养的电梯的安全性能负责；接到故障通知后，应当立即赶赴现场，并采取必要的应急救援措施。","a4f71e2850","中华人民共和国特种设备安全法","https://flk.npc.gov.cn/detail2.html?MmM5MDlmZGQ2NzhiZjE3OTAxNjc4YmY3NGVkZTA2Yzc=",0,"现行有效","2014-01-01",[]],"专利法实施细则|第一百零一条":["第一百零一条 下列行为属于专利法第六十八条规定的假冒专利的行为：\n（一）在未被授予专利权的产品或者其包装上标注专利标识，专利权被宣告无效后或者终止后继续在产品或者其包装上标注专利标识，或者未经许可在产品或者产品包装上标注他人的专利号；\n（二）销售第（一）项所述产品；\n（三）在产品说明书等材料中将未被授予专利权的技术或者设计称为专利技术或者专利设计，将专利申请称为专利，或者未经许可使用他人的专利号，使公众将所涉及的技术或者设计误认为是专利技术或者专利设计；\n（四）伪造或者变造专利证书、专利文件或者专利申请文件；\n（五）其他使公众混淆，将未被授予专利权的技术或者设计误认为是专利技术或者专利设计的行为。\n专利权终止前依法在专利产品、依照专利方法直接获得的产品或者其包装上标注专利标识，在专利权终止后许诺销售、销售该产品的，不属于假冒专利行为。\n销售不知道是假冒专利的产品，并且能够证明该产品合法来源的，由县级以上负责专利执法的部门责令停止销售。","84bdd82592","中华人民共和国专利法实施细则","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4ZDczNmRhZTAxOGRjNTE4MmYzMDZjMTQ=",0,"现行有效","2024-01-20",[]],"广告法|第二十七条":["第二十七条 农作物种子、林木种子、草种子、种畜禽、水产苗种和种养殖广告关于品种名称、生产性能、生长量或者产量、品质、抗性、特殊使用价值、经济价值、适宜种植或者养殖的范围和条件等方面的表述应当真实、清楚、明白，并不得含有下列内容：\n（一）作科学上无法验证的断言；\n（二）表示功效的断言或者保证；\n（三）对经济效益进行分析、预测或者作保证性承诺；\n（四）利用科研单位、学术机构、技术推广机构、行业协会或者专业人士、用户的名义或者形象作推荐、证明。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"市场主体登记管理条例|第二十四条":["第二十四条 市场主体变更登记事项，应当自作出变更决议、决定或者法定变更事项发生之日起30日内向登记机关申请变更登记。\n市场主体变更登记事项属于依法须经批准的，申请人应当在批准文件有效期内向登记机关申请变更登记。","42739e92a2","中华人民共和国市场主体登记管理条例","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE3YjYzYjY3OTAxN2I3YjIwODU5NTM2MDc=",0,"现行有效","2022-03-01",[]],"规范促销行为暂行规定|第二十条":["第二十条 经营者开展价格促销活动有附加条件的，应当显著标明条件。经营者开展限时减价、折价等价格促销活动的，应当显著标明期限。","2cfee9845b","规范促销行为暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_cae53a080be2401e8f91c6d6291539f8.html",0,"现行有效","2020-12-01",[]],"个人信息保护法|第五十四条":["第五十四条 个人信息处理者应当定期对其处理个人信息遵守法律、行政法规的情况进行合规审计。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"明码标价和禁止价格欺诈规定|第十七条":["第十七条 经营者没有合理理由，不得在折价、减价前临时显著提高标示价格并作为折价、减价计算基准。经营者不得采用无依据或者无从比较的价格，作为折价、减价的计算基准或者被比较价格。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"广告法|第二条":["第二条 在中华人民共和国境内，商品经营者或者服务提供者通过一定媒介和形式直接或者间接地介绍自己所推销的商品或者服务的商业广告活动，适用本法。本法所称广告主，是指为推销商品或者服务，自行或者委托他人设计、制作、发布广告的自然人、法人或者其他组织。本法所称广告经营者，是指接受委托提供广告设计、制作、代理服务的自然人、法人或者其他组织。本法所称广告发布者，是指为广告主或者广告主委托的广告经营者发布广告的自然人、法人或者其他组织。本法所称广告代言人，是指广告主以外的，在广告中以自己的名义或者形象对商品、服务作推荐、证明的自然人、法人或者其他组织。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"明码标价和禁止价格欺诈规定|第十九条":["第十九条 经营者不得实施下列价格欺诈行为：\n（一）谎称商品和服务价格为政府定价或者政府指导价；\n（二）以低价诱骗消费者或者其他经营者，以高价进行结算；\n（三）通过虚假折价、减价或者价格比较等方式销售商品或者提供服务；\n（四）销售商品或者提供服务时，使用欺骗性、误导性的语言、文字、数字、图片或者视频等标示价格以及其他价格信息；\n（五）无正当理由拒绝履行或者不完全履行价格承诺；\n（六）不标示或者显著弱化标示对消费者或者其他经营者不利的价格条件，诱骗消费者或者其他经营者与其进行交易；\n（七）通过积分、礼券、兑换券、代金券等折抵价款时，拒不按约定折抵价款；\n（八）其他价格欺诈行为。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"民法典|第一百四十八条":["第一百四十八条 一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。","c7b5e743c6","中华人民共和国民法典","https://flk.npc.gov.cn/detail2.html?ZmY4MDgwODE3MjlkMWVmZTAxNzI5ZDUwYjVjNTAwYmY=",0,"现行有效","2021-01-01",[]],"明码标价和禁止价格欺诈规定|第十六条":["第十六条 经营者在销售商品或者提供服务时进行价格比较的，标明的被比较价格信息应当真实准确。经营者未标明被比较价格的详细信息的，被比较价格应当不高于该经营者在同一经营场所进行价格比较前七日内的最低成交价格；前七日内没有交易的，应当不高于本次价格比较前最后一次交易价格。与厂商建议零售价进行价格比较的，应当明确标示被比较价格为厂商建议零售价。厂商建议零售价发生变动时，应当立即更新。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"食品安全法|第一百四十八条":["第一百四十八条消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制，先行赔付，不得推诿；属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金；增加赔偿的金额不足一千元的，为一千元。但是，食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"未成年人网络保护条例|第三十七条":["第三十七条个人信息处理者处理未成年人敏感个人信息的，应当具有特定的目的和充分的必要性，采取严格保护措施；在事前进行个人信息保护影响评估并对处理情况进行记录；依法告知处理敏感个人信息的必要性以及对个人权益的影响并取得单独同意。前款规定的个人信息保护影响评估报告和处理情况记录应当至少保存三年。","54238ce411","未成年人网络保护条例","https://www.gov.cn/gongbao/2023/issue_10806/202311/content_6913813.html",0,"现行有效","2024-01-01",[]],"个人信息保护合规审计管理办法|第四条":["第四条 在中华人民共和国境内从事食品销售和餐饮服务活动，应当依法取得食品经营许可。下列情形不需要取得食品经营许可：\n（一）销售食用农产品；\n（二）仅销售预包装食品；\n（三）医疗机构、药品零售企业销售特殊医学用途配方食品中的特定全营养配方食品；\n（四）已经取得食品生产许可的食品生产者，在其生产加工场所或者通过网络销售其生产的食品；\n（五）法律、法规规定的其他不需要取得食品经营许可的情形。除上述情形外，还开展其他食品经营项目的，应当依法取得食品经营许可。","b5683587ad","个人信息保护合规审计管理办法","https://www.cac.gov.cn/2025-02/14/c_1741233507681519.htm",0,"现行有效","2025-05-01",[]],"个人信息保护合规审计管理办法|第五条":["第五条 仅销售预包装食品的，应当报所在地县级以上地方市场监督管理部门备案。仅销售预包装食品的食品经营者在办理备案后，增加其他应当取得食品经营许可的食品经营项目的，应当依法取得食品经营许可；取得食品经营许可之日起备案自行失效。食品经营者已经取得食品经营许可，增加预包装食品销售的，不需要另行备案。已经取得食品生产许可的食品生产者在其生产加工场所或者通过网络销售其生产的预包装食品的，不需要另行备案。医疗机构、药品零售企业销售特殊医学用途配方食品中的特定全营养配方食品不需要备案，但是向医疗机构、药品零售企业销售特定全营养配方食品的经营企业，应当取得食品经营许可或者进行备案。","b5683587ad","个人信息保护合规审计管理办法","https://www.cac.gov.cn/2025-02/14/c_1741233507681519.htm",0,"现行有效","2025-05-01",[]],"互联网信息服务深度合成管理规定|第十九条":["第十九条深度合成服务提供者应当按照《互联网信息服务算法推荐管理规定》的有关规定，在提供服务之日起十个工作日内履行备案手续。完成备案的深度合成服务提供者应当在其对外提供服务的网站、应用程序等的显著位置标明其备案编号并提供公示信息链接。","a37cd2de4d","互联网信息服务深度合成管理规定","https://www.cac.gov.cn/2022-12/11/c_1672221949354811.htm",0,"现行有效","2023-01-10",[]],"食品标识监督管理办法|第三十三条":["第三十三条 食品经营者申请延续食品经营许可的，应当提交食品经营许可延续申请书，以及与延续食品经营许可事项有关的其他材料。食品经营者取得纸质食品经营许可证正本、副本的，应当同时提交。","1327b59001","食品标识监督管理办法","https://www.gov.cn/gongbao/2025/issue_12006/202504/content_7021456.html",0,"即将实施","2027-03-16",[]],"广告法|第十七条":["第十七条 除医疗、药品、医疗器械广告外，禁止其他任何广告涉及疾病治疗功能，并不得使用医疗用语或者易使推销的商品与药品、医疗器械相混淆的用语。","1bce3ff9af","中华人民共和国广告法","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_5474cf75173c45d6a0379730fb4e8d97.html",0,"现行有效","2021-04-29",[]],"网络反不正当竞争暂行规定|第九条":["第九条 经营者不得实施下列行为，对商品生产经营主体以及商品销售状况、交易信息、经营数据、用户评价等作虚假或者引人误解的商业宣传，欺骗、误导消费者或者相关公众：\n（一）虚假交易、虚假排名；\n（二）虚构交易额、成交量、预约量等与经营有关的数据信息；\n（三）采用谎称现货、虚构预订、虚假抢购等方式进行营销；\n（四）编造用户评价，或者采用误导性展示等方式隐匿差评、将好评前置、差评后置、不显著区分不同商品的评价等；\n（五）以返现、红包、卡券等方式利诱用户作出指定好评、点赞、定向投票等互动行为；\n（六）虚构收藏量、点击量、关注量、点赞量、阅读量、订阅量、转发量等流量数据；\n（七）虚构投票量、收听量、观看量、播放量、票房、收视率等互动数据；\n（八）虚构升学率、考试通过率、就业率等教育培训效果；\n（九）采用伪造口碑、炮制话题、制造虚假舆论热点、虚构网络就业者收入等方式进行营销；\n（十）其他虚假或者引人误解的商业宣传行为。经营者不得通过组织虚假交易、组织虚假排名等方式，帮助其他经营者实施前款虚假或者引人误解的商业宣传行为。","a96a7440af","网络反不正当竞争暂行规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2024/art_80019fe59e464196bef173dc56678a42.html",0,"现行有效","2024-09-01",[]],"个人信息保护法|第二十四条":["第二十四条 个人信息处理者利用个人信息进行自动化决策，应当保证决策的透明度和结果公平、公正，不得对个人在交易价格等交易条件上实行不合理的差别待遇。通过自动化决策方式向个人进行信息推送、商业营销，应当同时提供不针对其个人特征的选项，或者向个人提供便捷的拒绝方式。通过自动化决策方式作出对个人权益有重大影响的决定，个人有权要求个人信息处理者予以说明，并有权拒绝个人信息处理者仅通过自动化决策的方式作出决定。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"互联网信息服务算法推荐管理规定|第十八条":["第十八条算法推荐服务提供者向未成年人提供服务的，应当依法履行未成年人网络保护义务，并通过开发适合未成年人使用的模式、提供适合未成年人特点的服务等方式，便利未成年人获取有益身心健康的信息。算法推荐服务提供者不得向未成年人推送可能引发未成年人模仿不安全行为和违反社会公德行为、诱导未成年人不良嗜好等可能影响未成年人身心健康的信息，不得利用算法推荐服务诱导未成年人沉迷网络。","b207cac08f","互联网信息服务算法推荐管理规定","https://www.cac.gov.cn/2022-01/04/c_1642894606364259.htm",0,"现行有效","2022-03-01",[]],"互联网信息服务算法推荐管理规定|第十六条":["第十六条算法推荐服务提供者应当以显著方式告知用户其提供算法推荐服务的情况，并以适当方式公示算法推荐服务的基本原理、目的意图和主要运行机制等。","b207cac08f","互联网信息服务算法推荐管理规定","https://www.cac.gov.cn/2022-01/04/c_1642894606364259.htm",0,"现行有效","2022-03-01",[]],"明码标价和禁止价格欺诈规定|第二十三条":["第二十三条 经营者违反本规定第十六条至第二十条规定的，由县级以上市场监督管理部门依照《中华人民共和国价格法》《中华人民共和国反不正当竞争法》《中华人民共和国电子商务法》《价格违法行为行政处罚规定》等法律、行政法规进行处罚。","f435b274b6","明码标价和禁止价格欺诈规定","https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/fgs/art/2023/art_9a1f82a007964950a1a0f6c056f2fedf.html",0,"现行有效","2022-07-01",[]],"个人信息保护法|第五十五条":["第五十五条 有下列情形之一的，个人信息处理者应当事前进行个人信息保护影响评估，并对处理情况进行记录：\n（一）处理敏感个人信息；\n（二）利用个人信息进行自动化决策；\n（三）委托处理个人信息、向其他个人信息处理者提供个人信息、公开个人信息；\n（四）向境外提供个人信息；\n（五）其他对个人权益有重大影响的个人信息处理活动。","36a5c9bb89","中华人民共和国个人信息保护法","http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html",0,"现行有效","2021-11-01",[]],"食品安全法|第一百三十一条":["第一百三十一条违反本法规定，网络食品交易第三方平台提供者未对入网食品经营者进行实名登记、审查许可证，或者未履行报告、停止提供网络交易平台服务等义务的，由县级以上人民政府食品安全监督管理部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款；造成严重后果的，责令停业，直至由原发证部门吊销许可证；使消费者的合法权益受到损害的，应当与食品经营者承担连带责任。消费者通过网络食品交易第三方平台购买食品，其合法权益受到损害的，可以向入网食品经营者或者食品生产者要求赔偿。网络食品交易第三方平台提供者不能提供入网食品经营者的真实名称、地址和有效联系方式的，由网络食品交易第三方平台提供者赔偿。网络食品交易第三方平台提供者赔偿后，有权向入网食品经营者或者食品生产者追偿。网络食品交易第三方平台提供者作出更有利于消费者承诺的，应当履行其承诺。","e7b526bfbb","中华人民共和国食品安全法","https://sjfg.samr.gov.cn/law/file/pdf/3235243/1663322301314.pdf",0,"现行有效","2025-12-01",[]],"反垄断法|第三十九条":["第三十九条 行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，限定或者变相限定单位或者个人经营、购买、使用其指定的经营者提供的商品。","761957ef2c","中华人民共和国反垄断法","https://flk.npc.gov.cn/detail2.html?ZmY4MDgxODE4MjM0Y2NiNTAxODI5ZjQ2YzZhYzJhNWE=",0,"现行有效","2022-08-01",[]]};
